pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Penalize small-but-usable gaps less harshly, still discourage fragmentation.
    if post_residual > 0 && post_residual < 30 {
        score += 120.0 * (30.0 - post_residual as f64) / 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 80.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 8.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive if it enables a good future fit
    // (next item larger than current) or when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if next_item_size > item_size && next_item_size <= bin_capacity {
            score -= 60.0 + 40.0 * (next_item_size as f64 - item_size as f64);
        } else {
            score += 90.0 + 50.0 * progress;
        }
        if fragmentation < 20.0 {
            score += 40.0;
        }
    }

    // Lookahead: if the residual left behind exactly fits the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Penalize leaving a gap that is useless for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 60.0;
    }

    // Mild mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual (tight fits preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): tolerate larger residuals slightly (bins can absorb future items).
    // Late (progress ~ 1): strongly penalize residual waste.
    let progress_coupling = pr_norm * pr_norm * (progress - 0.5) * 40.0
        + pr_norm * (progress * progress) * 20.0;
    score += progress_coupling * cap;

    // Smooth penalty for residual that is small but not zero (dead space that
    // few future items can use) — quartic term in normalized residual.
    score += (pr_norm - 0.5) * (pr_norm - 0.5) * (pr_norm - 0.5) * (pr_norm - 0.5) * 30.0;

    // Lookahead: reward leaving room for the next item (smooth, saturating).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0) / cap;
        let exact_next = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= exact_next * exact_next * 15.0;
        // Penalize if residual after placement can't hold next item at all.
        let cannot_fit = ((nxt - pr) / cap).max(0.0).min(1.0);
        score += cannot_fit * cannot_fit * 12.0 * (1.0 - progress);
        let _ = fit_next;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones (smooth in count).
    let openness = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 10.0;
    score += openness * (1.0 - pr_norm);

    // New-bin candidate: add a smooth opening cost that shrinks as stream progresses,
    // so late in the stream we prefer squeezing into existing bins.
    if bin_residual == bin_capacity {
        score += 18.0 + 30.0 * progress * progress;
    }

    // Slight preference for bins below mean residual (balance residuals smoothly).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = 100.0 * (1.0 - x) * (1.0 - x) + 20.0 * x;

    // Smooth polynomial coupling with stream progress:
    // early on, be tolerant of leftovers; later, demand tight fits.
    score += 30.0 * x * (1.0 - progress) - 40.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize residuals that are too small to ever be useful again (dead space),
    // with a smooth quadratic penalty around the smallest plausible item (1..100 unknown).
    let deadness = (1.0 - x).powi(2);
    score += 15.0 * deadness * (0.5 + 0.5 * progress);

    // Reward bins whose residual matches the lookahead item (smooth Gaussian-like kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (-diff * diff * 50.0).exp();
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Slight preference for consolidating into bins with low mean residual (fuller bins).
    score += 0.05 * mean_residual;

    // Mild pressure against proliferating bins as stream progresses.
    score += 0.5 * open_bins_count as f64 * (0.2 + progress);

    // New empty bin candidate: make it attractive only when it's a genuinely good deal
    // (large item, poor fits elsewhere). Otherwise keep it mildly penalized.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 10.0 - 45.0 * tightness * tightness * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            // next item fits in the leftover: partial reward, scaled by how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 250.0 / (1.0 + slack * 0.5);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 2.0;
        }
    } else {
        // Last item: prefer tightest packing, exact fit already rewarded.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better hosts.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty discourages premature opening.
        score += 200.0;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 250.0;
        }
        // If this is the last-chance situation, allow opening a fresh bin
        // (compete with the lonely open bin, which already got -300).
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
        // Late in the stream, avoid leaving many half-empty bins behind.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 150.0 * (progress - 0.8) * 5.0;
        }
        // Many open bins with high mean residual: better to consolidate.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 80.0;
        }
    }

    // Mild global pressure: prefer denser bins when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it fall in?
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Dead-space penalty: residuals below quarter capacity are hard to fill.
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 3.0;
    }

    // Reward residuals that can still host a "large class" item (> half capacity).
    if post_residual >= half {
        score -= 12.0;
    } else if post_residual >= third {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < quarter {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += (next_item_size.min(post_residual) as f64).min(8.0);
    }

    // Modulo-harmonic bonus: residuals that are nice multiples pack well.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (tighter, more committed bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, encourage opening bins that keep large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        let poor_fit = post_residual < quarter && next_item_size > post_residual;
        if poor_fit {
            score -= 5.0;
        } else {
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (100.0 - match_gap.min(100.0));
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: only the final residual matters.
        score += 10.0;
    }

    // Tightness reward: small post_residual is good (less dead space).
    score -= 0.8 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Penalize creating residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Compare against mean residual: bins already below mean are valuable to preserve;
    // prefer filling bins with larger-than-mean residual.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist;
    // allow new bins more readily late in the stream or when few bins fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward bins that become (near) full after placement.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is an ideal two-item chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a gap; penalize by gap size.
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover: penalize proportionally
            // to how unusable the dead space is.
            score += 0.2 * post_residual as f64;
        }
    }

    // Relative to mean residual: bins with less residual than average are
    // "tighter" — prefer filling them (keeps many usable bins open).
    if mean_residual > 0.0 {
        score += 0.4 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a fresh bin only attractive when the
    // item is large relative to residual capacity (poor fit elsewhere) or
    // few bins are open. Otherwise penalize slightly so existing bins win.
    if bin_residual == bin_capacity {
        score -= 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Fresh bin can host both current and next item nicely.
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate
    // into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
