pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly or nearly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if next_item_size == post_residual {
            // Perfect 2-step match: huge reward.
            score -= 1000.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportional to tightness of the 2-step fill.
            let slack = post - next;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin's post-residual: penalize dead space,
            // especially when the leftover is small (unusable).
            let waste = next - post;
            score += 50.0 + 2.0 * waste;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild penalty for proliferation of open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.3;

    // New-bin candidate: neutral-ish base so it wins only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;

    // Base: prefer tight fits, but the penalty for residual grows super-linearly
    // as the stream progresses (waste matters more later).
    let residual_cost = pr * (1.0 + 2.0 * progress * progress) / cap;

    // Smooth non-linear coupling: a polynomial interaction between fill level
    // and stream progress. High fill + late stream => strong reward.
    let coupling = fill * fill * (1.0 + progress) * 12.0
                 - fill * fill * fill * (0.5 + progress) * 8.0;

    // Dead-space penalty: residuals too small for any plausible future item
    // (smoothly modeled around the smallest item scale).
    let dead = if pr > 0.0 {
        let tiny = (-norm_pr * 20.0).exp(); // near 1 when residual ~ 0
        tiny * 6.0 * (0.5 + progress)
    } else { 0.0 };

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -8.0 * (1.0 - norm_pr) } else { 0.0 };

    // Lookahead: reward if the post-residual accommodates the next item.
    let lookahead = if next_item_size > 0 {
        if pr as u32 >= next_item_size {
            -4.0 * (next_item_size as f64 / cap)
        } else {
            // penalize residuals that just barely miss the next item
            let gap = (next_item_size as f64 - pr) / cap;
            3.0 * (-gap * 10.0).exp()
        }
    } else { 0.0 };

    // Mild preference to keep mean residual balanced (avoid fragmenting).
    let balance = (mean_residual - pr).abs() / cap * 1.5;

    // New-bin candidate: keep it competitive but not dominant unless residuals
    // are heavily fragmented late in the stream.
    let new_bin_bias = if bin_residual == bin_capacity {
        4.0 + 6.0 * progress - 0.2 * open_bins_count as f64
    } else { 0.0 };

    let mut score = pr / cap * 10.0
        + residual_cost * 10.0
        + coupling
        + dead
        + last_chance
        + lookahead
        + balance
        + new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.5;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
        // Extra penalty if next item would exactly fill another bin better.
        if post_residual < next_item_size / 2 {
            score += 8.0;
        }
    }
    // Reward when post_residual can exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count grows; encourage consolidating into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.35 + 0.65 * t);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if no open bin fits well,
    // i.e. when mean residual across open bins is small relative to item.
    if bin_residual == bin_capacity {
        // Base new-bin score: keep it high unless open bins are truly poor.
        score = bin_capacity as f64 * 0.9 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight reward for bins tighter than average (good consolidation).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: group residuals by magnitude bands
    // (dead space classes). Residuals in the "useless" band (too small for the
    // smallest plausible item) are heavily penalized.
    let dead_threshold = 10u32.max(1);
    if post_residual < dead_threshold {
        score += 500.0; // nearly unusable sliver
    } else {
        // Integer-division harmonic class: how many average items still fit?
        let fits = post_residual / item_size.max(1);
        score -= (fits as f64) * 8.0;

        // Modulo arithmetic: residual mod item_size tells how "clean" the fit is.
        let rem = post_residual % item_size.max(1);
        score += (rem as f64) * 0.5;

        // Capacity-fraction bands of the post residual (harmonic classes of C).
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.05 {
            score += 40.0;      // dead space class
        } else if frac < 0.20 {
            score += 10.0;      // poor class
        } else if frac < 0.50 {
            score -= 5.0;       // good class
        } else {
            score -= 12.0;      // excellent class: half-full or better remains
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Exact harmonic match: next item leaves a clean class again.
            let rem2 = (post_residual - next_item_size) % item_size.max(1);
            score -= (item_size as f64 - rem2 as f64) * 0.3;
        } else {
            // Next item cannot follow here; penalize more if this bin is the
            // only fitting one (forced last-chance usage).
            if fitting_bins_count == 1 && bin_residual >= item_size {
                score -= 15.0; // still prefer using it rather than a new bin
            } else {
                score += 20.0;
            }
        }
    }

    // Last-chance bonus: if only this bin fits, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin is harmonically good.
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / bin_capacity as f64;
        if open_pressure > 0.35 && fitting_bins_count > 0 {
            score += 80.0; // keep using existing space
        } else {
            score -= 10.0; // opening fresh is fine
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.2;

    // Mild tie-break toward bins already below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum item size (1) is impossible, but small
    // residuals relative to typical item sizes create dead space. Penalize
    // post_residual in the "dead zone" [1, 20] super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - pr) * (21.0 - pr) * 0.8; // quadratic dead-space penalty
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when the stream is far along.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual cannot host the next item: mild dead-space penalty.
        score += 6.0;
    }

    // New-bin candidate: make it moderately unattractive by default; it should
    // win only when all open bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Slight preference for bins tighter than the mean (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum plausible item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small-but-usable gaps are still risky; moderate penalty.
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Coupling with mean residual: prefer bins that are tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor using existing ones over
    // opening a new bin (new-bin candidate has bin_residual == bin_capacity,
    // so it gets penalized through its large post_residual already, but add
    // explicit pressure proportional to open bins for existing bins).
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed, penalize.
        score += 10.0;
    }

    // Early in the stream, be slightly more willing to open bins (better packing
    // later); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item must be able to fit in the post residual at all
        if next_item_size > post_residual {
            score += 25.0;
        }
    }

    // Relative to mean residual: placing in a bin whose residual is near mean
    // keeps the fleet balanced; avoid fragmenting already-tiny residuals
    let res = post_residual as f64;
    let mean_gap = (res - mean_residual).abs();
    score += mean_gap * 0.15;

    // Penalize very small post_residual unless it's exactly 0 (perfect fill)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 {
            (bin_capacity as f64 - (item_size + next_item_size).min(bin_capacity) as f64)
        } else {
            (bin_capacity - item_size) as f64
        };
        // New bin is penalized by its own waste, discounted when many bins open late
        score = 15.0 + best_possible * 0.6 - (open_bins_count as f64) * 0.5 * (1.0 - progress);
        if post_residual == 0 { score -= 50.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but typical useful threshold)
    // are pure waste -> heavy penalty.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the leftover cannot fit the next item but the next item
    // would otherwise fit a residual we destroy.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many open bins: pressure to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate: make it moderately attractive only when existing
    // fits are poor (large post residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        score -= 8.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < next_item_size {
            score += 15.0; // empty bin handles the big next item better
        }
    } else {
        // Prefer bins whose residual is above average (less contended).
        if (bin_residual as f64) < mean_residual {
            score += 2.0;
        } else {
            score -= 1.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for any plausible item are worthless.
    // Treat gaps < 10 as total loss; gap in [10, 30) is partially wasted.
    let gap = post_residual as f64;
    if gap == 0.0 {
        score -= 25.0; // perfect fit reward
    } else if gap < 10.0 {
        score += 30.0; // unusable sliver: full dead space penalty on top of gap
    } else if gap < 30.0 {
        score += 0.9 * (30.0 - gap); // partial dead space
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Open bin pressure: discourage spreading across many bins when a good fit exists.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.8 + mean_residual * 0.05;
        score = 60.0 - crowded;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0; // an open bin fits; opening new bin is wasteful
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean
    // (keeps bin population homogeneous and mergeable).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on wasted residual, scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * x * x * (0.5 + progress);

    // Cubic coupling: strongly punish mid-range residuals as stream matures
    score += 25.0 * x * x * x * (1.0 - progress).abs();

    // Reward tight fits (small post residual)
    if post_residual <= 10 {
        score -= 15.0 * (11.0 - post_residual as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0 * (next_item_size as f64 - pr) / cap;
        } else {
            score += 2.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Interaction with mean residual: prefer bins below mean (keeps large gaps alive)
    score += 0.15 * (mean_residual - pr);

    // Mild penalty for proliferating bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer opening early, discourage late unless nothing fits well
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 40.0 * progress;
        score = open_penalty + 0.5 * (mean_residual - pr).abs();
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
