    score += 0.05 * (open_f / (1.0 + open_f)) * (1.0 - (1.0 - x) * (1.0 - x));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: group residuals by magnitude bands
    // (dead space classes). Residuals in the "useless" band (too small for the
    // smallest plausible item) are heavily penalized.
    let dead_threshold = 10u32.max(1);
    if post_residual < dead_threshold {
        score += 500.0; // nearly unusable sliver
    } else {
        // Integer-division harmonic class: how many average items still fit?
        let fits = post_residual / item_size.max(1);
        score -= (fits as f64) * 8.0;

        // Modulo arithmetic: residual mod item_size tells how "clean" the fit is.
        let rem = post_residual % item_size.max(1);
        score += (rem as f64) * 0.5;

        // Capacity-fraction bands of the post residual (harmonic classes of C).
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.05 {
            score += 40.0;      // dead space class
        } else if frac < 0.20 {
            score += 10.0;      // poor class
        } else if frac < 0.50 {
            score -= 5.0;       // good class
        } else {
            score -= 12.0;      // excellent class: half-full or better remains
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Exact harmonic match: next item leaves a clean class again.
            let rem2 = (post_residual - next_item_size) % item_size.max(1);
            score -= (item_size as f64 - rem2 as f64) * 0.3;
        } else {
            // Next item cannot follow here; penalize more if this bin is the
            // only fitting one (forced last-chance usage).
            if fitting_bins_count == 1 && bin_residual >= item_size {
                score -= 15.0; // still prefer using it rather than a new bin
            } else {
                score += 20.0;
            }
        }
    }

    // Last-chance bonus: if only this bin fits, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin is harmonically good.
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / bin_capacity as f64;
        if open_pressure > 0.35 && fitting_bins_count > 0 {
            score += 80.0; // keep using existing space
        } else {
            score -= 10.0; // opening fresh is fine
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.2;

    // Mild tie-break toward bins already below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // kills the bin for the next item
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate: make it attractive only for large items or when
    // mean residual across open bins is small (nothing useful to pack into).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if item_size > 50 || mean_r < item_size as f64 * 0.5 {
            score -= 30.0;
        } else {
            score += 20.0 + mean_r * 0.1;
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // penalize outliers wasting large residuals.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Mild preference for tighter overall fits as the stream progresses.
    score -= (bin_residual - post_residual) as f64 * 0.05 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Usable leftover for next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.3;
        } else {
            // Leftover too small for next item: penalize dead space more if it's tiny.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare against mean residual: bins already fragmented get a nudge toward use.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it neutral-ish unless item is large relative to capacity
    // (opening a fresh bin for large items is often fine).
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= bin_capacity / 2 {
            score -= 100.0;
        }
    }

    // Prefer filling nearly-full bins: tighter fit gets bonus.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    }

    // Penalize large dead space quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Exact fill is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // creates a stranded gap the next item cannot use
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.15 {
            score -= 12.0 * (0.15 - crowding) * 10.0; // plenty of slack elsewhere? no wait, low mean residual means bins are full -> opening is good
        }
        // Correct direction: low mean residual (full bins) favors new bin.
        score -= (1.0 - crowding) * 15.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins: discourage spreading further.
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, penalize it more aggressively
    let coupling = 1.0 + 3.0 * progress * progress + 2.0 * progress * norm_pr;
    score *= coupling;

    // Dead-space penalty: residuals too small to hold even the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead synergy: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty when bin is far below the mean residual (wasteful usage pattern)
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate handling: neutral baseline with slight pressure to consolidate
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 3.0;
        if fitting_bins_count >= 1 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins left in small residual
    // classes are "well packed" (waste is nearly unavoidable), reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds: residual <= 10 is excellent (only tiny items fit),
    // residual <= 20 good, <= 33 acceptable, else dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 33 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 12.0; // large dead space created
    }

    // Integer-division class: post_residual / item_size ratio — prefer bins
    // where the item is a large fraction of the residual (tight packing).
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_fraction;

    // Lookahead: if the next item would exactly fit the post_residual,
    // strongly reward leaving that gap (modular coupling).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to leftover after next
            let nxt_left = post_residual - next_item_size;
            score -= 15.0 * (1.0 - nxt_left as f64 / cap);
            if nxt_left <= 10 { score -= 20.0; }
        } else {
            // next item cannot use this residual: penalize large residuals
            score += 0.15 * pr;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 30.0 * fill_fraction;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer tighter fits (already via fraction)
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has huge post_residual;
    // make it attractive only when no open bin fits well, or when the item
    // is large relative to capacity (better to start fresh).
    if bin_residual == bin_capacity {
        // Prefer opening a new bin for big items or early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size >= bin_capacity / 2 { 30.0 } else { 0.0 };
        score -= 10.0 + large_item_bonus * (1.0 - progress) - 0.05 * open_bins_count as f64;
        // If next item is small, a fresh bin wastes capacity structure
        if next_item_size > 0 && next_item_size <= 20 {
            score += 15.0;
        }
    }

    // Mild penalty if this bin's residual is far from the mean (keep bins homogeneous)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }
    // Medium gaps (13..=30) are moderately wasteful.
    if post_residual > 12 && post_residual <= 30 {
        score += 1.5 * (post_residual as f64 - 12.0);
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already small (consolidate fullness).
    score += 0.4 * (bin_residual as f64 - post_residual as f64);

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive if the item would leave a large,
    // reusable residual AND open bins are crowded or would leave dead space.
    if bin_residual == bin_capacity {
        score += 25.0 * open_bins_count as f64;
        if post_residual >= 40 {
            score -= 30.0;
        }
        if post_residual > 0 && post_residual <= 12 {
            score += 60.0; // opening a bin that ends in a dead gap is bad
        }
    }

    // Lookahead: if the next item fits the post-residual well, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (fuller bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // penalize distance from perfect lookahead fit
            score += diff * 0.5;
            // reward if next item fits into post_residual
            if post_residual >= next_item_size {
                score -= 15.0;
            } else {
                score += 10.0; // dead space for next step
            }
        }
    } else {
        // last item: prefer minimal waste
        score -= 20.0;
    }

    // Tight fit reward: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= tightness * 5.0;

    // Compare against mean residual: prefer bins with less residual than average
    // (fills fuller bins first, keeps large residuals for big future items)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no open bin gives a tight fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual as f64) < mean_residual * 0.5;
        if good_fit_exists {
            score += 50.0; // discourage opening new bin when tight fit available
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 20.0;
        } else {
            score -= 10.0; // open new bin if fits are all bad
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // penalize many open bins slightly to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste of the bin.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Strong reward for exact or near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if the next item fits the resulting residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving residual that the next item cannot use at all.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Favor filling bins with small residuals relative to the mean (consolidate).
    let r = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (mean_residual - r) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more selective about opening new bins;
    // late in the stream, prefer using existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more so as stream progresses.
        score += 10.0 + 20.0 * progress;
        // But if no open bin fits well (large waste), opening fresh may win.
        if post_residual as f64 / bin_capacity as f64 > 0.6 && fitting_bins_count > 0 {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference to keep fewer open bins when many are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Small tie-breaker favoring larger items placed into tighter bins.
    score += 0.05 * item_size as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth coupling: reward small post_residual more as stream progresses
    score -= (1.0 - norm_pr).powi(3) * cap * (0.15 + 0.35 * progress);

    // Penalize very tight fits when lookahead item may still fit: smooth interaction
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).max(0.0);
        // Reward bins whose post_residual can still host the next item, smoothly
        score -= fits_next * cap * 0.5 * (1.0 - progress);
        // Penalize dead space that neither fits next item: quadratic in wasted space
        let waste = ((pr - nx) / cap).max(0.0).min(1.0);
        score += waste * waste * cap * 0.25 * (0.5 + progress);
    }

    // Last-chance bin bonus (smooth, avoiding discontinuity)
    if fitting_bins_count == 1 {
        score -= cap * 0.3 * (1.0 - progress * 0.5);
    }

    // Mean residual coupling: prefer bins near the mean early, diverging later
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * (0.2 + 0.4 * progress);

    // New-bin candidate handling: penalize opening new bins mildly, more early
    if bin_residual == bin_capacity {
        score += cap * (0.9 - 0.4 * progress) + open_bins_count as f64 * 0.05;
    }

    // Fragmentation penalty: smooth quadratic in post_residual for small residuals
    let frag = norm_pr.min(0.2) / 0.2;
    score += frag * frag * cap * 0.1 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction left over

    // Integer-division thresholds: residual classes of 25 (quarter bins)
    let quarter_class = post_residual / 25; // 0..4
    // Reward exact harmonic fits (residuals that are "usable" sizes)
    let harmonic_bonus = match quarter_class {
        0 => -30.0,                       // residual 0..24: near-perfect fill
        1 => -8.0,                        // 25..49: still decent
        2 => 4.0,                         // 50..74: half-bin waste zone
        3 => 12.0,                        // 75..99: large dead space
        _ => 20.0,
    };
    score += harmonic_bonus;

    // Modulo arithmetic: residuals divisible by common item sizes (10,20,25,50) are reusable
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 4.0; }
        if r % 20 == 0 { score -= 2.0; }
        if r >= 10 && r <= 80 {
            // residual falls in the range of plausible future items -> very reusable
            score -= 10.0;
        }
    } else {
        score -= 25.0; // perfect closure of the bin
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact lookahead match
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 40.0; }
            else if slack <= 10 { score -= 22.0; }
            else { score -= 10.0 - (slack as f64 / cap) * 6.0; }
        } else {
            // next item won't fit here; penalize more if leftover is dead space
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer tighter fits (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good residual class is available among open bins.
    if bin_residual == bin_capacity {
        // A fresh bin scores as its own post_residual (= capacity) plus penalty
        // that relaxes when open bins are fragmented or this is early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - pr).abs();
        score += 45.0;
        score -= 20.0 * progress;                 // early: prefer new bins to build diversity
        score -= 0.05 * open_bins_count as f64;   // many open bins -> prefer reusing
        if fragmentation > cap * 0.4 {
            score -= 15.0;                        // open bins badly fragmented -> new bin ok
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host both item and next item comfortably
            if item_size + next_item_size <= bin_capacity { score -= 18.0; }
        }
    }

    // Mild tie-break toward bins below mean residual (consolidate emptier bins)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize medium dead space mildly; large residuals are reusable.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Progress scaling: dead space matters more late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Prefer bins below mean residual (tighter bins keep big gaps open).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can be placed here afterwards: strong reward
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 - (slack_after_next as f64) * 0.5;
        } else {
            // Next item won't fit: penalize dead space proportional to gap
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
        // Perfect chaining: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Compare residual against mean residual of open bins
    // Bins with residual far above mean are "wasted space" candidates
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - res_f) * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit decently
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good fit exists
        let avg_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size {
            0.0 // new bin can chain with next item
        } else {
            60.0
        };
        score += 150.0 + avg_fit_penalty + (open_bins_count as f64) * 2.0;
        // Late in stream, opening new bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Prefer using bins with small residual overall (best-fit flavor)
    score += (post_residual as f64) * 0.6;

    // Mild penalty for very small unusable leftovers (dead space 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill achieved by this placement
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward high fill (tight fits) — subtract proportional to how full the bin gets
    score -= 40.0 * fill * fill;

    // Penalize dead space: post_residual that is too small to ever be useful
    // (smaller than the minimum plausible item size ~ 1..100 range, treat < 15 as near-dead)
    let dead = (15.0f64 - post_residual as f64).max(0.0);
    score += 3.0 * dead;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            // extra reward for perfect two-item packing
            if slack_after_next == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot follow into this bin: mild penalty, worse late in stream
            score += 10.0 + 15.0 * t;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // fits are poor. Penalize the empty-bin candidate when decent fits exist.
    if bin_residual == bin_capacity {
        let poor_fit_exists = (post_residual as f64) > 0.55 * bin_capacity as f64
            || (fitting_bins_count == 0);
        if fitting_bins_count > 0 && !poor_fit_exists {
            score += 45.0; // discourage opening a new bin when a reasonable fit exists
        }
        // Early in the stream, new bins are cheap and give flexibility
        score -= 25.0 * (1.0 - t);
        // Many open bins with high mean residual: reuse instead of opening
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Global balance: prefer bins whose residual is near the mean (keeps fleet homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in stream: pack tightly, avoid spreading
    score += 20.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: minimize post residual, but with a smooth polynomial penalty
    // that punishes very small residuals (dead space) non-linearly.
    let mut score = post;

    // Quartic dead-space coupling: tiny residuals become exponentially bad.
    score += 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post) * (item_size as f64);

    // Perfect fit reward (quadratic trough near zero residual).
    score -= 60.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Stream-progress coupling: later in the stream, tighten bins more
    // aggressively (polynomial ramp), early on be lenient.
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * ramp * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * ramp;
    }

    // New-bin candidate: penalize slightly so we prefer reusing bins unless
    // the fit is genuinely poor; the penalty decays as stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - ramp);
        // If next item is large, opening a fresh bin can be wise.
        if next_item_size > 0 && (next_item_size as f64) > post {
            score -= 20.0;
        }
    }

    // Lookahead synergy: reward leaving space for the next item smoothly.
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        if diff >= 0.0 {
            score -= 10.0 * (diff / cap) * (diff / cap);
        } else {
            score += 5.0 * (-diff / cap);
        }
    }

    // Crowd coupling: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).sqrt() * norm_post * 4.0;

    // Mean-residual alignment: favor bins near the mean residual (smooth).
    let d = (post - mean_residual) / cap;
    score += 8.0 * d * d;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // item classes (10, 20, 25, 50) are more reusable later.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals that are "harmonically clean" (divisible by common sizes)
    let mut harmony: f64 = 0.0;
    if pr == 0 {
        harmony += 12.0; // perfect closure, best outcome
    } else {
        if pr % 50 == 0 { harmony += 8.0; }
        else if pr % 25 == 0 { harmony += 5.0; }
        else if pr % 20 == 0 { harmony += 4.0; }
        else if pr % 10 == 0 { harmony += 3.0; }
        if pr % 5 == 0 { harmony += 1.0; }
    }
    score -= harmony;

    // Fraction-of-capacity classes: residual in a useful band gets rewarded
    let frac = post_residual as f64 / cap;
    if frac >= 0.4 {
        score -= 4.0; // roomy leftover, still very usable
    } else if frac < 0.1 && pr > 0 {
        score += 6.0; // dead sliver below smallest item size
    }

    // Lookahead coupling: does the next item harmonically fit the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // exact match next step
        } else if pr >= next_item_size && pr % next_item_size == 0 {
            score -= 9.0;  // residual is a multiple of next item
        } else if pr >= next_item_size {
            score -= 3.0;  // next item still fits
        } else {
            score += 5.0;  // next item won't fit here
        }
        // integer-division threshold: residual that can host next item twice
        if pr / next_item_size.max(1) >= 2 {
            score -= 2.5;
        }
    } else {
        // last item: prefer tightest bin
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate calibration: only attractive early in the stream or
    // when the item is large and would leave a clean harmonic residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 6.0 + 30.0 * progress + (item_size as f64 / cap) * 8.0;
        score -= new_bin_bonus;
        // penalize opening new bin when many bins are already open and loose
        score += open_bins_count as f64 * 0.6;
    }

    // Mild pull toward bins whose residual is near the mean (spread load evenly)
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // Small penalty for item classes that leave awkward mod-3 / mod-7 residues
    if pr > 0 && pr % 7 != 0 && pr % 3 != 0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is the ideal outcome
    }

    // Reward tight fits (waste ratio low).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_ratio;

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual already suggests crowding; encourage using crowded bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If this bin's residual is below the mean residual, it is a "shrinking"
    // bin: filling it first consolidates dead space.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving
    // that exact gap; otherwise penalize gaps slightly larger than next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 12.0;
        } else if post_residual > next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are truly full
    // (post_residual on an empty bin is large, so base score already penalizes it).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But if no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: does the next item fit exactly here?
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            // Perfect 2-item pairing: huge reward
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits: mild reward scaled by how well it fills
            let slack_after_next = post_residual as f64 - next;
            score -= 25.0 - slack_after_next * 0.4;
        } else {
            // Next item cannot follow: penalize dead space creation
            score += 15.0;
            // Extra penalty if post_residual is small-but-unusable
            if post_residual < 10 {
                score += 10.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Relative to mean residual: placing in a bin tighter than average is good
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item pairs perfectly with the residual of a fresh bin usage, allow it
        if next_item_size > 0 && (bin_capacity as f64 - next as f64) >= item_size as f64 {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, mildly normalized
    let mut score = pr;

    // Smooth non-linear coupling: residual^2 weighted by progress.
    // Late in the stream, small residuals (dead space) are penalized harder.
    let prn = pr / cap;
    score += prn * prn * (0.5 + 2.0 * progress) * cap * 0.1;

    // Reward tight fits (small post_residual) increasingly with progress
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 + 3.0 * progress) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize opening new bins when many bins are open (fragmentation)
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress + open_bins_count as f64 * 0.3;
    } else {
        // Reward reusing bins relative to mean residual
        score += (mean_residual - pr) * 0.05;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 10.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 3.0;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty for leaving awkward residual
        score += (pr - (next_item_size as f64)) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let post_frac = post_f / cap;

    // Dead-space penalty grows non-linearly: residuals in the "useless" class
    // (very small but nonzero) are heavily penalized, since they can host
    // almost no future item (items are >= 1, but small residuals waste space).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else if post_residual <= 10 {
        score += 45.0; // dead space class: too small to be useful
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Integer-division harmonic classes: residuals divisible by common item
    // sizes are more likely to be exactly filled later.
    let divisible = (post_residual % 10 == 0) as f64
        + (post_residual % 25 == 0) as f64
        + (post_residual % 50 == 0) as f64;
    score -= 6.0 * divisible;

    // Tight-fit reward: item fills a large fraction of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement sets up a perfect chain; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot follow here; penalize proportionally to waste.
            score += 8.0 * (1.0 - post_frac);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (consolidate small residuals, keep large residual bins flexible).
    score += 0.15 * (mean_residual - post_f).max(-50.0).min(50.0);

    // Late in the stream, prefer closing bins out (waste less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - post_frac);

    // Mild penalty for spreading across many bins when a tight fit exists.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 40.0 * (1.0 - decent);
        if post_frac > 0.5 && fitting_bins_count > 0 {
            score += 15.0; // opening fresh bin wastes the residual left behind
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are heavily penalized.
    // Minimum plausible item size assumed near 1..20; treat residual < 15 as near-dead space.
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if (post_residual as f64) < 5.0 {
        score -= 10.0;
    }

    // Last-chance bonus: only one bin can fit this item; strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = (open_bins_count as f64) * (1.0 + progress) * 0.8;
    if bin_residual == bin_capacity {
        // New empty bin candidate: must beat existing bins only when fits are poor.
        score += 8.0 + new_bin_penalty;
        // If next item is large and would waste this fresh bin, penalize further.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.9 {
            score += 4.0;
        }
    } else {
        // Reward reusing bins whose residual matches the current need well.
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.15;
        // Slight preference for bins below mean residual (consolidate emptier bins? no:
        // prefer filling fuller bins first, i.e. residual below mean is good).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Lookahead: if the post-residual can host the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Penalize leaving a gap that neither fits the next item nor is useful.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // 2-step lookahead: reward if next item exactly fills post_residual
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 150.0;
            } else if next_item_size <= post_residual {
                let waste_after_next = (post_residual - next_item_size) as f64;
                score -= 60.0 - 0.5 * waste_after_next;
            } else {
                // next item won't fit here: penalize small dead space less than huge dead space
                let dead = post_residual as f64;
                if dead < next_item_size as f64 {
                    score += 0.3 * (next_item_size as f64 - dead);
                }
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid forcing a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could fit (new-bin candidate gets residual == capacity)
    if bin_residual == bin_capacity {
        // new bin starts at high score; only attractive if current item is large and
        // lookahead suggests a fresh bin pays off
        score += 60.0;
        if item_size >= 60 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 30.0;
        }
        // late in stream, avoid proliferation of bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for filling nearly-full bins early
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit leaves (mostly) unusable sliver, still good
    }

    // Dead-space penalty: leftover space that no item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it uses leftover
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * nl;
        } else {
            // next item won't fit here: penalize leaving residual close-but-below next size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 4.0 * (10.0 - gap) / 10.0;
            }
        }
    }

    // Prefer filling bins that are already relatively empty vs. mean residual,
    // keeping many bins balanced is worse than concentrating load.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // late in the stream, exploit open bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (fitting_bins_count as f64).min(3.0);

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    // relative to residual or many bins are open (fragmentation control).
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).sqrt() * 1.5;
        score += 10.0 + open_bonus - 0.35 * item_size as f64;
        if item_size >= 70 {
            score -= 8.0; // big items are fine in a fresh bin
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to progress.
    // Later in the stream, tighter packing (small post_residual) matters more,
    // so residual is amplified by a smooth quadratic-in-progress factor.
    let mut score = pr * (0.8 + 1.2 * progress * progress);

    // Penalize dead space super-linearly: very small residuals are wasted.
    let dead = (1.0 - norm_pr).clamp(0.0, 1.0);
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward snug fits: small post_residual relative to item size.
    let snug = pr as f64 / (item_size.max(1) as f64);
    score -= 8.0 * (-snug).exp() * (0.5 + 0.5 * progress);

    // Lookahead: bonus if next item fits the post residual (smooth gate).
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 6.0 * (1.0 - (fits_next * 4.0).min(1.0)) * (0.5 + progress);
        } else {
            score += 4.0 * (-fits_next).min(1.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure from number of open bins and mean residual dispersion.
    score += 0.05 * open_bins_count as f64 * progress;
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: keep it neutral-ish, slightly worse early when
    // open bins exist and residual is plentiful.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size dividing capacity evenly
    // leave "perfect" residuals; reward exact-fit classes.
    let cap = bin_capacity as f64;

    // Class A: post_residual == 0 -> perfect closure, strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Class B: post_residual is a common small size (harmonic slot that a
    // future item of typical size can fill). Reward residuals in {10..20}
    // and multiples of 10 that divide capacity.
    if post_residual >= 1 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Class C: dead space penalty — residual too small for the minimum item
    // (1) is impossible here, but residuals below a "useful threshold" that
    // next_item_size cannot use are dead weight.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits in the leftover: strong chaining reward
            score -= 0.8 * (next_item_size as f64);
            // exact chain: post_residual == next_item_size closes bin next step
            if next_item_size == post_residual {
                score -= 15.0;
            }
        }
    }

    // Integer-division thresholds: classify how "full" the bin becomes.
    let fill_quarters = (bin_capacity - post_residual) / (bin_capacity / 4);
    match fill_quarters {
        0 => score += 10.0,          // barely filled: bad use of bin
        1 => score += 2.0,
        2 => score -= 1.0,
        3 => score -= 5.0,           // mostly full: good
        _ => score -= 12.0,          // fully or nearly full
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large relative to capacity or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let largeness = item_size as f64 / cap;
        score += 30.0;                       // base cost of a new bin
        score -= 25.0 * largeness;           // big items justify new bins
        score -= 15.0 * (1.0 - progress);    // early stream: new bins cheap
        if open_bins_count == 0 {
            score -= 100.0;                  // must open a bin
        }
        // If item + next item perfectly pack a fresh bin, open it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 50.0;
        }
    }

    // Coupling with mean residual: prefer bins whose post placement keeps
    // residual near the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Modulo class on item_size: items in "awkward" classes (e.g. 7, 13, 17
    // style non-divisors of 100) pair better with tight bins; reward using
    // bins whose residual shares a gcd class with the item.
    let g = gcd(post_residual, item_size);
    if g > 1 {
        score -= 2.0 + g as f64 * 0.3;
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: residual after placement, but dead space is not linear.
    let pr = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (here: < 10, or < half the next item when known) are heavily penalized.
    let min_useful = if next_item_size > 0 {
        ((next_item_size as f64) * 0.5).max(10.0).min(50.0)
    } else {
        10.0
    };

    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if (pr as u32) < min_useful as u32 {
        // Unusable dead space: quadratic penalty scaled by how close to full.
        let deadness = 1.0 - pr / min_useful;
        score += 15.0 + 25.0 * deadness * deadness;
    } else {
        // Usable leftover: mild preference for tighter fits.
        score += pr * 0.35;
    }

    // Reward filling bins deeply (waste minimization).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing ones,
    // and penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // If mean residual across open bins can still hold future items,
        // opening a new bin is wasteful.
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // Early in stream, opening bins is cheaper (need bins anyway).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If next item is large and this bin would be fresh, slight relief.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Existing bin: small penalty growing with open bin count to encourage consolidation.
        score += 0.15 * open_bins_count as f64;
        // Prefer bins whose residual is close to item (tight fit among candidates).
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward residuals that exactly match next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't fit here; dead space penalty
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when other bins fit well
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // but allow new bin if current item is huge and would leave awkward residue elsewhere
        if item_size > bin_capacity * 3 / 4 {
            score -= 40.0;
        }
    }

    // Slight preference to fill bins progressively over stream
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit flavor: strongly reward tight fits.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * tightness * tightness * (bin_residual as f64);

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 14.0 - 0.12 * chain_quality; // prefer exact-ish two-item chains
    } else if next_item_size > 0 {
        // Penalize creating residual the next item cannot use (dead space risk).
        score += 3.0 * (next_item_size as f64 / bin_capacity as f64) * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise this item forces a new bin and strands residual.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global pressure: when many open bins exist, discourage spreading;
    // favor consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 0 {
        score += 0.35 * (open_bins_count as f64).ln() * (0.5 + progress);
    }

    // Mean-residual coupling: if this bin is far below average residual
    // (relatively full), placing here is efficient; reward it.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate handling: an empty bin (residual == capacity) is a
    // fallback. Give it a moderate score: worse than a decent existing fit,
    // but better than a very poor fit that strands large dead space.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin grows with stream progress and open bins.
        score = 0.55 * bin_capacity as f64
            + 8.0 * progress
            + 1.5 * (open_bins_count as f64);
        // If nothing else fits well (many fitting bins means alternatives exist),
        // slight extra penalty so existing bins win unless they are terrible.
        if fitting_bins_count > 0 {
            score += 2.0;
        }
        // Late in the stream with no lookahead chain possible, new bins are cheap.
        if next_item_size == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on (t small) prefer tight fits less aggressively; late (t large) penalize waste strongly.
    let progress_waste = x * x * (0.5 + 2.5 * t) * cap;
    score += progress_waste;

    // Reward near-perfect fits with a smooth cubic term, scaled by progress.
    let tightness = 1.0 - x;
    score -= 30.0 * tightness.powi(3) * (0.3 + 0.7 * t);

    // Penalize residuals that are too small to be useful for typical items,
    // with smooth coupling to progress (dead space matters more later).
    let dead = (x * (1.0 - x)).powi(2); // peaks mid-range residuals
    score += 20.0 * dead * (1.0 - t);

    // Lookahead: if next item fits in post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = (x - nx).max(0.0) / cap.max(1.0);
        score -= 25.0 * (1.0 - fit_next / (x + 0.01)).max(0.0) * (1.0 - t * 0.5);
        // Penalize if next item barely misses
        let miss = (nx - x).max(0.0);
        score += 15.0 * miss / (nx + 1.0);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - t * 0.3);
    }

    // Slight preference for bins below mean residual (consolidate fuller bins),
    // smoothly scaled by number of open bins.
    let mean_norm = mean_residual / cap;
    score += 10.0 * (x - mean_norm) / (open_bins_count as f64 + 1.0).sqrt();

    // New-bin candidate: penalize opening a bin unless remaining open bins are poor fits,
    // smoothly relaxed as stream progresses.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 15.0 * (1.0 - t) - 10.0 * scarcity * (0.5 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in low classes (tiny slivers)
    // are nearly dead space -> penalize; large leftovers keep bins useful.
    let class = post_residual / (bin_capacity / 10).max(1); // 0..=10
    score += match class {
        0 => 12.0,                       // unusable sliver (0..10)
        1 => 6.0,                        // 10..20 nearly dead
        2 => 2.0,
        3 => -1.0,
        4 => -2.0,
        5 => -3.0,                       // ~half-full leftover is flexible
        6 => -2.5,
        7 => -2.0,
        8 => -1.0,
        _ => 0.0,
    };

    // Perfect or near-perfect fit reward (item fills bin_residual exactly).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the
    // next item exactly or nearly (harmonic pairing).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0;
        } else if gap > 0 && gap <= 5 {
            score -= 15.0;
        } else if gap > 0 && gap <= 15 {
            score -= 7.0;
        } else if gap < 0 {
            // next item won't fit here; mild penalty scaled by shortfall
            score += ((-gap).min(40) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean
    // residual spread across open bins. Make the empty bin attractive
    // only when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base cost of a fresh bin, discounted if existing bins are fragmented
        score += 30.0 - (fragmentation * 0.4).min(25.0);
        // early in the stream, fresh bins are cheap (plenty of future items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for filling fuller bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / cap) * progress * 8.0;

    // Tie-break toward bins below mean residual (consolidate emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // marginal gap, only useful for very small items
    } else if post_residual > 60 {
        score += 6.0; // large gap but wasteful placement of a small item
    } else {
        // post_residual in 21..=60: sweet spot, reward tight fits
        score -= 15.0 * (1.0 - post_residual as f64 / 60.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0; // chains a near-perfect follow-up placement
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // leftover can't host the next item
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a bin unless the current
    // best fits are poor (few fitting bins or large dead space elsewhere).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere: open a new bin
        } else if fitting_bins_count == 1 {
            score += 45.0 + pressure; // keep the last-chance bin alive
        } else {
            score += 20.0 + pressure; // mild preference for existing bins
        }
    }

    // Open-bins pressure: with many open bins, favor consolidation.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins below mean residual (fill emptier-than-average bins less,
    // keep tight bins tight): penalize bins with residual below mean.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild reward proportional to leftover after both
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize wasted space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that keep residuals near the mean (balance),
    // penalize creating extreme outliers.
    let drift = post_residual as f64 - mean_residual;
    score += 0.2 * drift.abs();

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great 2-step chain.
    if bin_residual == bin_capacity {
        score += 300.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 350.0;
        }
        // Late in the stream, opening new bins is cheap since bins rarely refill.
        let progress = step_index as f64 / total_items as f64;
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-fit residual is small.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness).powi(3);

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack);
        } else {
            // Penalize leaving a residual too small for the next item (dead space risk).
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste * (1.0 - waste).powi(2);
        }
    } else {
        // Last item: any residual is pure waste; maximize packing density.
        score += 12.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let open_penalty = 22.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is mandatory; slight preference signal.
            score -= 30.0;
        } else {
            // Best existing fit residual among fitting bins approximated via mean residual.
            let decent_fit = mean_residual - item_size as f64;
            if decent_fit < 12.0 {
                score -= 6.0; // existing fits are poor-ish; opening is competitive
            } else {
                score += open_penalty;
            }
        }
    }

    // Time horizon: early in stream, be conservative about fragmentation;
    // late in stream, squeeze bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.35 * progress;

    // Mild penalty proportional to residual relative to mean residual across bins:
    // prefer bins below-average residual (they are the "almost full" ones).
    score += 0.25 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: tight fit reward, with polynomial shaping on residual
    let mut score = pr as f64;
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr); // reward small post-residual non-linearly
    score -= 20.0 * norm_item * (1.0 - norm_item) * 4.0; // reward filling mid/large chunks

    // Dead-space penalty: residuals too small for typical future items
    let dead = if pr < 10.0 { 0.0 } else { 0.0 };
    let _ = dead;
    score += 25.0 * (norm_pr * (1.0 - norm_pr)) * (1.0 - norm_item); // penalize awkward leftover when item is small

    // Stream progress coupling: early on, keep bins flexible; later, pack tight
    let tightness = 1.0 - progress;
    score += 15.0 * tightness * norm_pr; // early: penalize low residuals less/more smoothly
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 18.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into fuller ones
    let crowd = (open_bins_count as f64 / (1.0 + total_items as f64 * 0.1)).min(1.0);
    score += 10.0 * crowd * norm_pr;

    // Mean residual interaction: prefer bins deviating below mean residual (fuller bins)
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: make empty bin mildly unattractive unless residuals are hopeless
    if bin_residual == bin_capacity {
        score += 60.0 - 45.0 * progress - 20.0 * (1.0 - mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: how "wasted" is the leftover space
    // relative to the smallest plausible item (1) and typical classes.
    let pr = post_residual as f64;

    // Penalize dead space that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual > 0 && (post_residual as f64) < nx {
            // leftover is unusable for the next item -> dead space penalty
            score += 12.0 * (nx - pr) / nx;
        } else if post_residual >= next_item_size {
            // leftover can host the next item -> reward proportional to snugness
            let snug = 1.0 - ((pr - nx) / bin_capacity as f64).abs();
            score -= 6.0 * snug;
        }
    } else {
        // last item: any bin that fits is fine; prefer the tightest (already via post_residual)
        score -= 4.0;
    }

    // Modulo-class logic on post_residual: residuals in "awkward" classes
    // (small primes-ish bands) are hard to fill later.
    let cls = post_residual % 17;
    let cls_penalty = match cls {
        0 => -3.0,           // perfectly aligned residual
        1..=5 => 2.5,        // tiny slivers, likely dead
        6..=12 => 0.5,       // mid band, mildly useful
        _ => -1.5,           // larger band, reusable
    };
    score += cls_penalty * (0.5 + 0.5 * progress);

    // Integer-division threshold: post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post_residual / item_size;
        if ratio == 0 { score -= 5.0; }        // very tight fit -> great
        else if ratio == 1 { score -= 1.0; }   // decent
        else { score += 1.0 * ratio as f64; }  // loose fit penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    } else if fitting_bins_count > 1 && !is_new_bin {
        score -= 2.0; // mild preference for reusing open bins over new ones
    }

    // New-bin candidate handling: opening a new bin is costly unless
    // no open bin fits or all fits are terrible (large post_residual).
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // compare against best possible existing fit: penalize new bin
            // more when mean residual across open bins is large (bins are half-empty)
            score += 8.0 + 0.15 * mean_residual + 10.0 * progress;
            // but if the item is huge, a fresh bin may still be cleanest
            if item_size >= bin_capacity / 2 {
                score -= 6.0;
            }
        }
    }

    // Mild global pressure: fewer open bins -> slightly favor consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are unusable; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small but usable residual).
    if post_residual > 0 && post_residual <= 20 {
        score -= 6.0;
    }

    // Penalize post-residuals that can't fit the lookahead item if this bin
    // could otherwise have been paired with it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, scaled by open bin count.
        score += 12.0 + open_bins_count as f64 * 2.0;
        // If a last-chance bin exists, strongly avoid opening a new one.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // If mean residual across open bins is large, opening new bins is wasteful.
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64) * 0.5;
        }
    } else {
        // Favor bins whose residual is closest to the item (best fit shaping).
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.15;
        // Last-chance bin bonus: strongly prefer using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Slight preference for placing into bins early in the stream progression
    // to keep later flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-perfect lookahead fits (post_residual slightly above next_item_size)
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap <= 5 {
            score -= 100.0 - (gap as f64) * 15.0;
        }
        // Penalize residuals that are just barely too small for the next item
        if gap < 0 && gap >= -5 {
            score += 20.0 + (-gap as f64) * 5.0;
        }
    }

    // Penalize large residual relative to mean residual of open bins (wasted capacity)
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.5;

    // Reward tight fits: small post_residual is good
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 50.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Discourage opening new bins when decent open bins exist (mid-stream)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let open_penalty = 80.0 * (1.0 - progress * 0.5);
        score += open_penalty;
        // If next item fits perfectly in the fresh bin too, soften the penalty
        if next_item_size > 0 && next_item_size == item_size {
            score -= 30.0;
        }
    }

    // Late stream: prefer consolidating into fewest bins
    if step_index + 1 >= total_items.saturating_sub(1) {
        if bin_residual != bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins whose post-residual is small (tight fit),
    // but dead space below a "useful" threshold is worse than moderate space.
    let usable_threshold = 10.0; // smallest item size
    if (post_residual as f64) < usable_threshold {
        // Completely wasted residual: heavy penalty proportional to how wasted it is
        score += (usable_threshold - post_residual as f64) * 3.0;
    }

    // Lookahead coupling: reward if the next item exactly fits the post-residual,
    // penalize if post-residual is too small for the next item (dead end).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item can also go here: good bin
        } else {
            // post-residual too small for next item: dead space penalty scaled
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.8;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        // Even more attractive if the fit is decent
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= fit_ratio * 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Penalize the fresh bin moderately, but less
    // when many bins are open and mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        score += 15.0;
        // If open bins are fragmented (high mean residual vs item size), a new bin
        // is more attractive: reduce the penalty.
        let fragmentation = if bin_capacity as f64 > 0.0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 0.0 };
        score -= fragmentation * 12.0;
        // Early in the stream, opening bins is cheap; later, consolidate.
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins with residual close to item size (best-fit shaping)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.05;

    // Mild reward for using bins when many are open (avoid bin proliferation)
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Prefer filling bins that are already partially consumed
    let used = (bin_capacity - bin_residual) as f64;
    score -= used * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual (tight fits preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): tolerate larger residuals slightly (bins can absorb future items).
    // Late (progress ~ 1): strongly penalize residual waste.
    let progress_coupling = pr_norm * pr_norm * (progress - 0.5) * 40.0
        + pr_norm * (progress * progress) * 20.0;
    score += progress_coupling * cap;

    // Smooth penalty for residual that is small but not zero (dead space that
    // few future items can use) — quartic term in normalized residual.
    score += (pr_norm - 0.5) * (pr_norm - 0.5) * (pr_norm - 0.5) * (pr_norm - 0.5) * 30.0;

    // Lookahead: reward leaving room for the next item (smooth, saturating).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0) / cap;
        let exact_next = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= exact_next * exact_next * 15.0;
        // Penalize if residual after placement can't hold next item at all.
        let cannot_fit = ((nxt - pr) / cap).max(0.0).min(1.0);
        score += cannot_fit * cannot_fit * 12.0 * (1.0 - progress);
        let _ = fit_next;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones (smooth in count).
    let openness = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 10.0;
    score += openness * (1.0 - pr_norm);

    // New-bin candidate: add a smooth opening cost that shrinks as stream progresses,
    // so late in the stream we prefer squeezing into existing bins.
    if bin_residual == bin_capacity {
        score += 18.0 + 30.0 * progress * progress;
    }

    // Slight preference for bins below mean residual (balance residuals smoothly).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "usable" ---
    // Residuals divisible into small chunks (e.g. multiples of 10/20) are more
    // reusable; odd tiny residuals are dead space.
    let r = post_residual;
    let class_bonus: f64 = if r == 0 {
        -60.0 // perfect fit: strongly favored
    } else if r % 20 == 0 {
        -8.0
    } else if r % 10 == 0 {
        -4.0
    } else if r % 5 == 0 {
        -1.0
    } else if r < 10 {
        12.0 // sub-10 odd residual is nearly dead space
    } else {
        0.0
    };
    score += class_bonus;

    // --- Integer-division thresholds: quantize residual quality ---
    let bucket = r / 25; // 0..4 coarse class
    score += match bucket {
        0 => 6.0,  // 0..24: small leftover, but only good if it was a tight fit
        1 => 0.0,
        2 => -2.0,
        _ => -4.0, // roomy bin keeps flexibility
    };

    // --- Lookahead coupling: can next item fit into post_residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (chaining).
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + slack * 0.05;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize if this placement strands us: next item won't fit here.
        score += 5.0;
    } else {
        // Last item: prefer zero-waste strongly.
        score -= 5.0;
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when existing residuals are poor fits
        // (item leaves large awkward residual elsewhere) or few bins fit.
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + ((mean_residual < item_size as f64 + 5.0) as i32 as f64);
        score = 100.0 - 40.0 * tightness - 20.0 * pressure;
        // Late in the stream, prefer closing out existing bins rather than
        // proliferating new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        if open_bins_count > 6 {
            score += 8.0;
        }
    }

    // --- Mean-residual harmony: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // --- Modulo harmony between item and residual: complementary sizes ---
    if (bin_capacity - item_size) % 10 == 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than equal-but-larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // Lookahead cannot use this gap: mild penalty.
            score += 4.0;
        }
    }

    // Tight-fit reward: fraction of bin filled by this item.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: prefer existing bins generally,
    // but allow opening a new bin when the item barely fits nowhere else
    // and the current bin would be left with a large wasted gap.
    if bin_residual == bin_capacity {
        // New bin: penalize mildly when other bins fit, more when many are open.
        let base = if fitting_bins_count == 0 { 5.0 } else { 18.0 };
        score += base + open_bins_count as f64 * 1.5;
        // If the next item is large, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Existing bin that fits: slight bonus when it is the only option.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Penalize placing into a bin whose residual is far above the mean
        // (keep residuals balanced) unless the fit is tight.
        let dev = bin_residual as f64 - mean_residual;
        score += (dev * 0.05).max(0.0);
    }

    // Late in the stream, consolidate to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack left
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize if next item cannot fit in the residual (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (gap / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual of open bins
    let tightness = post_residual as f64 - mean_residual;
    score += 0.3 * tightness;

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild bonus for filling bins when many are open (consolidation)
    if open_bins_count > 3 {
        score -= (item_size as f64) * 0.1;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, but only if it's truly unusable
    // for the lookahead item (or there is no lookahead).
    let dead = post_residual as f64;
    let dead_unusable = if next_item_size > 0 {
        (next_item_size as f64) > dead
    } else {
        true
    };
    if dead_unusable {
        score += dead * 0.5;
    } else {
        // Dead space exactly usable by next item: strong reward.
        score -= 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many candidates (already via fit_ratio).
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, decaying as stream progresses
        // (fewer future chances to amortize the bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 12.0 * progress;

        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * (fitting_bins_count as f64);
        }

        // If open bins have large mean residual, prefer reusing them.
        score += 0.2 * mean_residual;

        // Late in the stream, opening bins leaves stranded waste: extra penalty.
        score += 8.0 * progress;
    } else {
        // Reward keeping bins balanced: bins below mean residual are slightly favored.
        score += 0.05 * (mean_residual - bin_residual as f64);

        // Slight penalty for having many open bins (encourages consolidation early).
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // Lookahead chain bonus: if next item fits exactly in the post residual,
    // this is a two-item perfect packing.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Small items: avoid wasting a nearly empty large-residual bin on tiny items
    // when other bins exist.
    if item_size <= 15 && bin_residual >= 70 && open_bins_count > 1 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear coupling: squared residual penalized more as stream progresses.
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward near-perfect fits smoothly (tanh of fill fraction).
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 40.0 * (fill * fill * 4.0).tanh();

    // Lookahead: if next item fits the post-residual, reward this bin smoothly.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 12.0 * fits_next * (0.5 + snug) * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).tanh();
        score += 55.0 * (1.0 - pressure);
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity-fraction classes. Small leftovers in low classes are good.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic class

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo logic: leftovers that are multiples of common small item
    // granularities (10, 20, 25) are reusable dead space -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd leftovers (non-multiple of 5) tend to be dead space -> penalize.
    if post_residual % 5 != 0 {
        score += 7.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after chain matters
            let chain_left = post_residual - next_item_size;
            score -= 20.0 - (chain_left as f64) * 0.3;
        } else {
            // next item cannot use this bin's leftover: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Integer-division threshold on residual: bins with residual below
    // half capacity are "closing" bins — using them is good.
    if bin_residual < bin_capacity / 2 {
        score -= 12.0;
    } else if bin_residual == bin_capacity {
        // New-bin candidate: mild penalty so it's chosen only when
        // open bins fit poorly; grows with number of open bins.
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is an outlier worth closing out.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    }

    // Early in the stream, allow more bin spreading; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class bonus: class 0-1 (tiny leftovers) are ideal.
    if class <= 1 {
        score -= 10.0;
    } else if class >= 7 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits (waste <= 3).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Open-bins pressure: prefer closing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: placing into a below-average-residual bin (tight bin) is good.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space that the next item cannot use
    }

    // New-bin candidate: make it moderately attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact-ish fits (low post_residual) strongly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_quality * fit_quality;

    // 2-step lookahead: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits too: partial bonus proportional to resulting residual
        let two_step_residual = post_residual - next_item_size;
        score -= 25.0 * (1.0 - two_step_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize wasted dead space
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Compare residual against mean residual of open bins: prefer bins with
    // below-average residual (tighter bins), penalize dumping into loose bins.
    let mean_diff = mean_residual - post_residual as f64;
    score += 0.2 * mean_diff;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Early in the stream, opening bins is cheap; later it's costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for consolidating when many bins are open.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on relative wasted space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post-residual that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.25 * (post_residual as f64);
        } else {
            // Reward leaving space exactly usable by the next item.
            let gap = post_residual - next_item_size;
            score -= 8.0 * (-gap as f64 / 15.0).exp();
        }
    }

    // Last-chance bonus: only bin that fits, avoid wasting its unique capacity.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty for using a scarce-tight one? Encourage
    // filling bins with small residuals first via mean-residual coupling.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual (more filled bins) to consolidate.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be conservative with open bins; later, pack hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; relax late in the stream or when few bins fit.
        score += 40.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, new bin is fine
        } else if fitting_bins_count == 1 {
            score += 5.0; // slight nudge to use the last-chance bin
        }
        // If next item is huge, a fresh bin keeps big space available.
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Small penalty on many open bins to encourage closing them out.
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward small post-residual, with non-linear sharpening over progress
    let norm_post = post / cap;
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Non-linear coupling: dead space penalty grows quadratically as stream matures
    score += 20.0 * norm_post * norm_post * (0.3 + progress);

    // Tight fit bonus (smooth, non-piecewise): strongly reward near-exact fills
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bin bonus: avoid wasting a scarce fitting opportunity
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Prefer bins below mean residual (keeps residuals balanced) — smooth coupling
    score += 0.4 * (mean_residual - post);

    // Lookahead: reward leaving room for the next item (smooth hinge via quadratic)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            score += 3.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for proliferating open bins early, fading with progress
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress - 8.0 * norm_post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "capacity fraction band" it falls into.
    let quarter = bin_capacity / 4;                 // 25
    let eighth = bin_capacity / 8;                  // 12

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= eighth {
        score -= 35.0;
    } else if post_residual <= quarter {
        score -= 18.0;
    }

    // Penalize dead space by harmonic class of post_residual (integer division bands).
    let dead_class = post_residual / quarter;       // 0..3
    score += dead_class as f64 * 6.0;

    // Harmonic coupling: can the NEXT item exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;                          // perfect chaining
        } else if next_item_size < post_residual {
            let next_class = next_item_size / eighth;
            let post_class = post_residual / eighth;
            if next_class == post_class {
                score -= 12.0;                      // same harmonic band: likely good reuse
            } else {
                score += 5.0;                       // mismatched band
            }
            // If next item cannot fit elsewhere it may need this residual later
            if next_item_size > post_residual {
                score += 4.0;
            }
        } else {
            score += 8.0;                           // next item too big for this bin anyway
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when plenty of bins can fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus crowding pressure.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Early in the stream, new bins are cheaper (stream still long).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += rel * 5.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (harmonic with typical sizes) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0) {
        score -= 8.0;
    }
    // Odd, awkward residuals are less reusable.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, favor consolidation into tight fits.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Prefer bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot use the leftover, penalize leaving awkward gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate: baseline cost so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.2;
        // Opening a new bin is attractive if the item is large and would leave
        // a tiny dead gap in any existing bin.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score = post_residual as f64 * (1.0 + 0.5 * progress);

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-exact fit reward (post_residual <= 10).
    if post_residual > 0 && post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post_residual, this bin will be perfectly filled over two steps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportional to how well it matches.
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit here: penalize bins that leave a
            // residual just below the next item size (wasted slot).
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot <= 20.0 {
                score += 60.0 * (1.0 - overshoot / 20.0);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far from the mean are
    // either unusually full (good targets) or unusually empty (save them).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Tighter than average: good.
        score -= 0.5 * (-dev);
    } else {
        // Looser than average: mild penalty, scaled by how many bins exist.
        score += 0.3 * dev / (1.0 + open_bins_count as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize unless the item is huge
    // relative to all residuals, or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Baseline penalty: opening a new bin is generally costly.
        score += 120.0 + 10.0 * open_bins_count as f64;
        // But if the item is large and would leave a very tight residual
        // elsewhere, opening fresh can be right; soften when item is big.
        score -= 0.5 * item_size as f64;
        // If next item is huge too, a fresh bin pairs large items well.
        if next_item_size >= 60 {
            score -= 40.0;
        }
    }

    // Penalize leaving residuals that are likely dead space (small, odd gaps)
    // when the item itself was small — big items in big gaps is fine.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let mut score = post;

    // Reward tight fits strongly.
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post);
    }

    // Lookahead: if next item fits the post residual exactly-ish, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: consolidate; few open bins: allow spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * (post / cap) * 8.0;

    // Global mean residual coupling: prefer bins near the mean to keep balance.
    score += 0.15 * (post - mean_residual).abs();

    // Time horizon: early in stream, be exploratory (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - t);
        score += 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let size_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual, mildly sub-linear
    let mut score = pr.powf(0.85);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate spread
    let progress_shape = 0.5 + 0.5 * progress;
    score += 40.0 * pr_norm * pr_norm * (1.0 - progress_shape) * 2.0;
    score -= 30.0 * pr_norm * (1.0 - pr_norm) * progress_shape;

    // Reward placing large items (reduces fragmentation risk)
    score -= 15.0 * size_norm * size_norm;

    // Lookahead: reward if next item fits in the post residual (smooth quadratic)
    let fit_gap = next_norm - pr_norm;
    if next_item_size > 0 {
        score += 25.0 * fit_gap.max(0.0) * fit_gap.max(0.0);
        score -= 10.0 * (-fit_gap).max(0.0) * (-fit_gap).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // Mild penalty when this bin's residual is far from the mean (outlier bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight pressure against opening new bins when many are already open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" size classes (multiples of common item granularities) are
    // more valuable to keep. Penalize residuals that don't align with
    // typical class boundaries.
    let pr = post_residual;
    let class_10 = (pr % 10 == 0) as i32 as f64;
    let class_5 = (pr % 5 == 0) as i32 as f64;
    let class_20 = (pr % 20 == 0) as i32 as f64;
    score -= 12.0 * class_10 + 5.0 * class_5 + 8.0 * class_20;

    // Integer-division threshold: residual in [1..=15] is dead space
    // (nothing in 10..80 fits). Penalize heavily.
    let dead = (pr > 0 && pr < 10) as i32 as f64;
    score += 25.0 * dead;

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual: mild reward,
            // scaled by how well the chained residual aligns to classes
            let chain = pr - next_item_size;
            let chain_align = ((chain % 10 == 0) as i32 as f64) * 10.0
                + ((chain % 5 == 0) as i32 as f64) * 4.0;
            score -= 10.0 + chain_align;
        } else {
            // next item cannot use this bin's leftover: penalty grows with
            // how far off it is, modulated by modulo class of gap
            let gap = next_item_size - pr;
            let gap_mod = (gap % 10) as f64;
            score += 6.0 + gap_mod * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && pr <= 30 {
        score -= 15.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first),
    // weighted by stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= tightness * 20.0 * (0.5 + 0.5 * progress);

    // Slight bias toward consolidating when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (pr as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: only attractive when no open bin has a good
    // harmonic fit; make empty bin moderately expensive.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Favor bins whose residual was large (avoid fragmenting big spaces).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Open-bin pressure: when many bins are open, prefer reusing them over new bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 20.0 + 5.0 * open_bins_count as f64;
        // But allow a new bin if it would fit the next item nicely and this bin would leave dead space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    } else {
        score -= pressure.min(15.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward keeping room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Slight preference for bins with below-mean residual (tighter packing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: this item leaves exactly room for the next one.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Perfect chain fit: strong reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of the chain.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will not fit: penalize wasted residual relative to next size.
            score += 0.5 * gap + 10.0;
        }

        // Double-perfect: post_residual == next_item_size == 0 handled by exact match above.
        if post_residual == 0 {
            score -= 40.0; // bin closed perfectly, always great.
        }
    } else {
        // Last item: just prefer minimal residual.
        score -= 20.0;
    }

    // Tight fit for current item is good (low post_residual), but avoid tiny dead space
    // that can't hold anything (items >= 1, so residual 0 is best).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space too small for typical items
    }

    // Compare against mean residual: bins with residual near the item size are better matches.
    let mean_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.1 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good chain exists.
    if bin_residual == bin_capacity {
        let good_chain = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if fitting_bins_count > 0 && !good_chain {
            score += 45.0; // keep using open bins when no perfect chain is formed
        }
        // Early in stream, mildly discourage proliferation.
        if open_bins_count > 2 {
            score += 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize more if it wastes a scarce fitting option.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty to encourage spreading across bins.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state: prefer filling bins with below-average residual (balance open bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, allow new bins more freely (less future to plan for).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount penalty as stream progresses.
        score += 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        // Existing bins get a mild discount late in the stream to encourage consolidation.
        score -= 5.0 * progress;
    }

    // Coupling: large items prefer the emptiest bins (avoid fragmenting tight bins).
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.6 {
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: tight fit reward, non-linear in post_residual
    let mut score = post / cap;
    score += (post / cap).powi(3) * 2.0;

    // Smooth interaction: as stream progresses, punish residual waste more
    score += (post / cap) * (0.5 + 2.5 * progress * progress);

    // Mean-residual coupling: prefer bins whose residual is close to bin_residual (avoid fragmenting)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * (1.0 + progress);

    // New-bin candidate handling
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        if fitting_bins_count == 0 {
            // must open a bin
            score -= 10.0;
        } else {
            // penalize opening new bin, more so early (want to fill existing bins)
            score += 3.0 + 2.0 * (1.0 - progress);
            // but if the best existing fit would leave a large dead zone, allow opening
            score -= (post / cap) * 1.5;
        }
    } else {
        // last-chance bonus: only one bin fits, keep item stream compact
        if fitting_bins_count == 1 {
            score -= 1.0 + progress;
        }
        // prefer bins whose leftover can still hold the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 0.8 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            } else {
                score += 0.5 * (next_item_size - post_residual) as f64 / cap;
            }
        }
    }

    // mild preference for more-filled bins overall
    score -= (1.0 - bin_residual as f64 / cap) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Tight fit reward: harmonic class of post_residual ----
    // post_residual classes: 0 (perfect), small (1..=5 golden), medium, large
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, always take
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // ---- Harmonic classes via capacity fractions ----
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f; // residual as fraction of capacity
    // Penalize residuals in "dead zones": (0.3,0.6) is hard to fill later
    if frac > 0.30 && frac < 0.60 {
        score += 25.0 * (0.45 - (frac - 0.45).abs()) * 4.0;
    }
    // Reward residuals in the "easy refill" zone: divisible by common small sizes
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // ---- Integer division thresholds on next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: big reward, scaled by how snugly
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0; // chain of perfect fits
            } else if slack <= 10 {
                score -= 80.0;
            } else {
                score -= 20.0;
            }
        } else {
            // lookahead won't fit here: penalize more if the waste is large
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
        // Harmonic class of lookahead: large items (>50) are hard to place later,
        // so favor bins that can absorb them now
        if next_item_size > 50 && next_item_size <= post_residual {
            score -= 30.0;
        }
    } else {
        // last item: pure waste minimization
        score = post_residual as f64 * 2.0;
        if post_residual == 0 { score -= 2000.0; }
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost = item waste in fresh bin + pressure from open bins
        let mut nb = (bin_capacity - item_size) as f64;
        // Prefer new bin when existing bins would be left with ugly residuals
        if mean_residual < 15.0 && post_residual > 20.0 {
            nb -= 30.0; // open bins are nearly full anyway; fresh bin is fine
        }
        // As stream progresses, discourage hoarding many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 10.0 + (open_bins_count as f64) * 2.0;
        score += nb;
    } else {
        // Slight preference for using existing bins over opening new ones
        score -= 5.0;
        // Prefer fullest bins (small bin_residual) mildly
        score += 0.1 * (bin_residual as f64);
    }

    // ---- Mean residual coupling: if this bin is far below mean, filling it balances state ----
    let dev = mean_residual - bin_residual as f64;
    score -= 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Mild reward for tight fits generally.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements when many bins are open,
    // pushing toward consolidation unless fit is good.
    score += (open_bins_count as f64) * 0.5 * (1.0 - tightness);

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual unusable by next item: penalize.
        score += 10.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    // or many bins already exist with poor residuals.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - item_size as f64).abs() < 5.0 && open_bins_count > 2;
        if fitting_bins_count > 0 && !poor_fits {
            score += 40.0; // discourage new bin when reasonable fits exist
        } else if fitting_bins_count > 0 {
            score -= 5.0; // allow new bin when fits are poor
        }
    }

    // Mean residual coupling: bins far below mean residual are better targets.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: excellent chaining, big reward.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.25 * chain_slack;
        } else {
            // Next item won't fit here: penalize leftover dead space that
            // nothing in the immediate future can use.
            score += 0.35 * post_residual as f64;
        }
        // If next item exactly fills post_residual, reward heavily.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: any residual is permanent waste.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins; placing here is fine (small post_residual already does it),
    // but penalize placing into unusually empty bins when tighter options exist.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // every other open bin. Make the empty-bin candidate costly unless the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Large items late in the stream may justify a fresh bin.
        if (item_size as f64) > 0.7 * bin_capacity as f64 && progress > 0.5 {
            score -= 20.0;
        }
        // If nothing else fits tightly, allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core best-fit-like base: prefer small post_residual.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space: residuals too small for typical future items.
    let dead_threshold = 12.0;
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Next item won't chain here; penalize proportionally to wasted pairing potential.
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
        // If next item is large, prefer keeping big-residual bins for it.
        if next_item_size > 50 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Competition: mild penalty so the best fit among many wins more sharply.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.15 * mean_gap;
    } else {
        score += 0.10 * (-mean_gap);
    }

    // Time horizon: early in the stream, keep bins flexible (favor mid-range residuals);
    // late in the stream, prioritize closing bins out (tight fits).
    if progress < 0.3 {
        score += 0.05 * ((post_residual as f64) - mean_residual).abs();
    } else if progress > 0.7 {
        score -= 6.0 * tightness;
    }

    // New-bin candidate handling: empty bin gets a moderate default score,
    // worse than good fits but better than terrible dead-space fits.
    if bin_residual == bin_capacity {
        score = 40.0 + 0.1 * item_size as f64 - 10.0 * progress;
        // Open a new bin when the item barely fits anywhere or would leave big dead space.
        if post_residual as f64 > 30.0 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins with more prior content (fewer total bins).
    score -= 0.08 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress) - 1.6 * pr_norm * pr_norm * (1.0 - progress) + 2.2 * pr_norm * pr_norm * pr_norm;
    let mut score = pr * (1.0 + 0.5 * progress) + 40.0 * poly;

    // Reward tight fits (small post residual) with smooth falloff
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: penalize if next item could use this residual well, reward blocking waste
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) as f64;
        score += 0.35 * waste * (1.0 - progress);
        if nx <= pr {
            score -= 12.0 * (1.0 - nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Slight penalty for opening a brand-new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.6 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean residual context: penalize bins far from the fleet mean (fragmentation)
    score += 0.15 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are "usable" future slots.
    let r = post_residual;
    let harmonic_bonus = if r == 0 {
        -60.0 // perfect fit, ideal
    } else if r % 50 == 0 {
        -40.0
    } else if r % 25 == 0 {
        -25.0
    } else if r % 20 == 0 {
        -20.0
    } else if r % 10 == 0 {
        -12.0
    } else {
        // awkward leftover: dead space penalty grows for tiny residuals
        if r < 10 { 35.0 } else { 8.0 }
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r && r % next_item_size == 0 {
            score -= 18.0;
        } else if next_item_size > r {
            // next item won't fit here anyway; slight penalty for wasting space
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (future
    // flexibility); later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0;
    score += progress * post_residual as f64 * 0.15;

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but typical useful threshold)
    // are pure waste -> heavy penalty.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the leftover cannot fit the next item but the next item
    // would otherwise fit a residual we destroy.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many open bins: pressure to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate: make it moderately attractive only when existing
    // fits are poor (large post residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        score -= 8.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < next_item_size {
            score += 15.0; // empty bin handles the big next item better
        }
    } else {
        // Prefer bins whose residual is above average (less contended).
        if (bin_residual as f64) < mean_residual {
            score += 2.0;
        } else {
            score -= 1.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect-fit reward: small post_residual strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Exact 2-step fill: item now + next item exactly fills bin.
        if diff < 0.5 {
            score -= 55.0;
        } else if diff <= 5.0 {
            score -= 30.0 * (1.0 - diff / 6.0);
        } else {
            // Penalize residuals that neither fit next item nor stay reusable.
            score += diff * 0.25;
            if post < nxt {
                // Dead space relative to lookahead: unusable for next item.
                score += (nxt - post) * 0.5;
            }
        }
        // If next item fits exactly into current residual (before placement),
        // mild penalty for breaking that chain.
        if bin_residual as f64 == nxt && item_size as f64 != nxt {
            score += 10.0;
        }
    } else {
        // Last item: only perfect fit matters.
        score += post * 0.5;
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual
    // is below the mean (concentrating usage into tight bins).
    score += (post - mean_residual).max(-40.0).min(40.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the item is large relative to capacity (poor fit anywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / cap;
        let base = 20.0 + 30.0 * big_item;
        // Early stream: fresh bins cheap; late stream: reuse is king.
        score = base * (1.0 - 0.6 * progress) + 10.0;
        // Next item large too: pairing in a fresh bin can be good.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the average next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward leaving room exactly for the lookahead item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when existing bins fit well,
    // but allow it when the stream is early or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - 10.0 * progress - 0.1 * open_bins_count as f64;
        if fragmentation > 25.0 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // new bin can pair this item with the next one
        }
    } else {
        // Mild preference for bins already below mean residual (balance usage).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for larger residual bins when many bins are open.
    score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = 100.0 * (1.0 - x) * (1.0 - x) + 20.0 * x;

    // Smooth polynomial coupling with stream progress:
    // early on, be tolerant of leftovers; later, demand tight fits.
    score += 30.0 * x * (1.0 - progress) - 40.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize residuals that are too small to ever be useful again (dead space),
    // with a smooth quadratic penalty around the smallest plausible item (1..100 unknown).
    let deadness = (1.0 - x).powi(2);
    score += 15.0 * deadness * (0.5 + 0.5 * progress);

    // Reward bins whose residual matches the lookahead item (smooth Gaussian-like kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (-diff * diff * 50.0).exp();
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Slight preference for consolidating into bins with low mean residual (fuller bins).
    score += 0.05 * mean_residual;

    // Mild pressure against proliferating bins as stream progresses.
    score += 0.5 * open_bins_count as f64 * (0.2 + progress);

    // New empty bin candidate: make it attractive only when it's a genuinely good deal
    // (large item, poor fits elsewhere). Otherwise keep it mildly penalized.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 10.0 - 45.0 * tightness * tightness * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it divides the capacity
    let div = bin_capacity.max(1) / post_residual.max(1);
    score -= 8.0 * (div as f64).min(10.0);

    // Reward post_residuals that are multiples of common small item sizes
    let mut harm = 0.0;
    for k in [10u32, 20, 25, 50] {
        if post_residual % k == 0 {
            harm += 4.0;
        }
    }
    score -= harm;

    // Penalize awkward residual classes (mod 10 near but not at zero)
    let m = post_residual % 10;
    if m != 0 {
        score += 3.0 * (5 - (m as i32 - 5).abs()) as f64 * 0.4;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong preference to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        score = 60.0 - 30.0 * pressure as f64 + 0.1 * mean_residual;
    }

    // Prefer tight fills as stream progresses
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host even the
    // smallest item are pure waste -> heavy penalty proportional to gap size.
    if post_residual < 10 {
        score += (post_residual as f64) * 6.0 + 8.0;
    } else if post_residual < 20 {
        // Marginal zone: only useful for tiny future items.
        score += (20 - post_residual) as f64 * 2.0;
    } else {
        // Usable residual: reward leaving a gap that matches the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0 + (post_residual as f64).min(60.0) * 0.15;
        } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
            // The lookahead item no longer fits after this placement -> penalty.
            score += 3.0;
        }
    }

    // Reward tight fits (small waste relative to item size).
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - waste_ratio.min(1.0)) * 5.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // but relax pressure late in the stream (fewer chances to consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (0.35 - 0.2 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are very fragmented
    // (high mean residual spread) or this item is huge relative to gaps.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 15.0; // base reluctance to open a new bin
        if fragmentation > 0.5 {
            score -= (fragmentation - 0.5) * 30.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 3.0; // keep room for big lookahead items
        }
    }

    // Slight penalty for placing into bins whose residual far exceeds item
    // (encourages best-fit style selection among usable bins).
    if bin_residual > item_size + 30 {
        score += (bin_residual - item_size - 30) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-fit residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Favor tighter fits relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are very poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Slightly cheaper to open new bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many open bins already, discourage opening more
        score += 1.5 * open_bins_count as f64;
    }

    // Mild preference for filling bins that are already fairly full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Penalize unusable dead space: residuals too small for the smallest item.
    if post_residual < 1 {
        score -= 60.0; // perfect fill, excellent
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else {
        // dead space penalty grows if nothing in [1,100] range can use it well
        score += 8.0 * (post_residual as f64 / 100.0).powi(2);
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item can't follow here: mild penalty, worse if post_residual is stranded
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity; grows as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 25.0 * progress;
        // If many open bins exist with slack, opening new bins is wasteful.
        score += 3.0 * open_bins_count as f64;
        // If mean residual across open bins is large, avoid new bin.
        score += 0.5 * mean_residual;
    }

    // Global pressure: when open bins are mostly full (low mean residual),
    // encourage consolidating into existing bins.
    if bin_residual < bin_capacity {
        score += 0.2 * mean_residual;
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;

    // Base: prefer tight fits, but the penalty for residual grows super-linearly
    // as the stream progresses (waste matters more later).
    let residual_cost = pr * (1.0 + 2.0 * progress * progress) / cap;

    // Smooth non-linear coupling: a polynomial interaction between fill level
    // and stream progress. High fill + late stream => strong reward.
    let coupling = fill * fill * (1.0 + progress) * 12.0
                 - fill * fill * fill * (0.5 + progress) * 8.0;

    // Dead-space penalty: residuals too small for any plausible future item
    // (smoothly modeled around the smallest item scale).
    let dead = if pr > 0.0 {
        let tiny = (-norm_pr * 20.0).exp(); // near 1 when residual ~ 0
        tiny * 6.0 * (0.5 + progress)
    } else { 0.0 };

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -8.0 * (1.0 - norm_pr) } else { 0.0 };

    // Lookahead: reward if the post-residual accommodates the next item.
    let lookahead = if next_item_size > 0 {
        if pr as u32 >= next_item_size {
            -4.0 * (next_item_size as f64 / cap)
        } else {
            // penalize residuals that just barely miss the next item
            let gap = (next_item_size as f64 - pr) / cap;
            3.0 * (-gap * 10.0).exp()
        }
    } else { 0.0 };

    // Mild preference to keep mean residual balanced (avoid fragmenting).
    let balance = (mean_residual - pr).abs() / cap * 1.5;

    // New-bin candidate: keep it competitive but not dominant unless residuals
    // are heavily fragmented late in the stream.
    let new_bin_bias = if bin_residual == bin_capacity {
        4.0 + 6.0 * progress - 0.2 * open_bins_count as f64
    } else { 0.0 };

    let mut score = pr / cap * 10.0
        + residual_cost * 10.0
        + coupling
        + dead
        + last_chance
        + lookahead
        + balance
        + new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into
    // coarse buckets (dead space classes) via integer division.
    let class = post_residual / 10; // 0..=10 harmonic class
    // Penalize mid-range dead space classes more than tiny or exact fills.
    let class_penalty = match class {
        0 => -40.0,                       // near-perfect fit, strongly reward
        1 => -25.0,                       // excellent
        2 => -12.0,
        3 => 5.0,                         // awkward leftover
        4 => 12.0,
        5 => 18.0,                        // worst: half-empty bin
        6 => 14.0,
        7 => 8.0,
        8 => 2.0,
        9 => -6.0,                        // large residual: still reusable
        _ => -15.0,                       // fresh/empty bin class
    };
    score += class_penalty;

    // Modulo coupling: leftovers that are multiples of 5 pair well with
    // typical item sizes; odd tiny leftovers are dead space.
    if post_residual % 5 == 0 { score -= 6.0; }
    if post_residual % 10 == 0 && post_residual > 0 { score -= 6.0; }

    // Lookahead: reward if the next item can also fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 8.0; // next item won't fit here; this bin becomes dead
        }
        // Exact pair: item + next fills bin completely -> golden placement
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive early
    // in the stream or when all open bins are too full / mean residual low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 70.0 - 40.0 * progress;
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size >= 60 { score += 5.0; }
    }

    // Mild pressure against hoarding many open bins with fat residuals.
    score += 0.15 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 stream,
    // but tiny gaps < 10 are near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual tightly matches the item (tightness ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Penalize leaving a gap that is unusable by the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }
    // Reward when post_residual can still host the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * (1.0 - tightness)) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this item would otherwise create dead space) or bins are congested.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 + 10.0;
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 30.0;
        }
        score += open_bins_count as f64 * 1.5;
    }

    // Mild preference for filling bins below mean residual (balancing).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect chain: next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Next item fits in the remaining space at all
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space penalty scaled by how much of post_residual is wasted
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist and fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin: only attractive if item is large and would leave big dead space elsewhere
        score += 20.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        // If next item is small, a fresh bin can chain nicely
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 12.0;
        }
    }

    // Mild stream-progression pressure: later in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Lookahead: reward placements whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover is useful for the next item — mild reward.
            score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Leftover is dead space relative to the next item — penalize
            // proportionally to how much space is stranded.
            let stranded = post_residual as f64;
            score += 3.0 * stranded * (stranded / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Penalize leaving large residual in bins when many bins are already open
    // (fragmentation pressure grows with open bin count).
    let frag_pressure = (open_bins_count as f64).ln().max(1.0);
    score += 0.05 * frag_pressure * post_residual as f64;

    // Global state coupling: if mean residual across open bins is high,
    // encourage consolidating into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
    } else {
        // New-bin candidate: penalize opening a new bin unless current bins
        // are nearly full on average or the item is large and fits nothing well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 20.0 + 0.4 * mean_residual + 15.0 * (1.0 - progress);
        // If the item is big relative to capacity and mean residual is small,
        // a new bin becomes more attractive (reduce the penalty).
        let size_factor = item_size as f64 / bin_capacity as f64;
        let relief = 25.0 * size_factor * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        score += new_bin_penalty - relief;
    }

    // Slight preference for bins whose residual is closest to the item size
    // (exact tightness coupling, non-linear).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness * tightness / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);
    // Penalize large dead space more strongly as stream progresses
    score += progress * norm_pr * norm_pr * cap * 0.3;
    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * 0.2;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    // Lookahead: prefer bins whose post residual matches next item smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 / (1.0 + gap * gap / (cap * cap));
        score -= 15.0 * fit_next * poly.max(0.01);
    }
    // Smooth interaction with mean residual across open bins
    let mr = mean_residual / cap;
    score += 8.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "useful" classes.
    // Class 0: residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Class by integer division into capacity-fraction bands.
        let band = post_residual / 10; // 0..=10
        // Residuals in [1,9] are dead space; [10,29] can host small items; >=30 are flexible.
        match band {
            0 => score += 60.0,            // 1..9: nearly dead
            1 | 2 => score += 15.0,        // 10..29: usable for small items
            3 | 4 => score += 0.0,         // 30..49
            _ => score -= 5.0,             // 50+: still flexible
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 9 {
                score -= 80.0; // next item nearly fills this bin
            } else {
                score -= (20.0 * (1.0 - slack as f64 / bin_capacity as f64)).max(0.0);
            }
        } else {
            // next item cannot fit here; penalize proportionally to wasted opportunity
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin starts with high score; only allow opening
    // a new bin when current item is large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score = 100.0
            + (item_size as f64 / bin_capacity as f64) * 30.0
            + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 40.0; // pairing potential in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        }
    }

    // Mild preference to fill older/more crowded bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Slight phase bias: late in stream, tighten packing (favor small post_residual more).
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += phase * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Gaps that cannot fit the smallest conceivable item are dead.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += post_residual as f64 * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else (large post_residual penalty already handles that),
    // but keep a mild base preference for reusing bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Lookahead: if next item could use this bin's future residual, dampen penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
    } else {
        // Favor bins whose residual is close to mean (balanced usage).
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact 2-step match
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // next item fits after this placement: scale reward by closeness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover gap relative to item size
            score += 0.5 * diff;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below/at mean (well-filled bins)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current item is huge
    // and would waste an existing bin
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 70 {
            score -= 55.0; // huge item: fresh bin is fine
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 1.5 {
            score -= 15.0; // fresh bin leaves room for the future
        }
    }

    // Slight preference for keeping number of open bins low early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that likely cannot host future items.
    if post_residual > 0 && post_residual < item_size {
        score += 12.0; // stranded sliver
    }
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.05 * next_item_size as f64;
        } else {
            score += 8.0;
            // Bonus if post_residual is small enough to be "closed" usefully.
            if post_residual < next_item_size / 2 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fits are poor or stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (mean_residual - item_size as f64).abs() > 0.6 * mean_residual.max(1.0);
        let base_penalty = 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 || (poor_fits && fitting_bins_count <= 2) {
            score -= 20.0;
        } else {
            score += base_penalty;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // encourage consolidating into existing bins.
    if open_bins_count > 3 {
        score += 0.3 * mean_residual * (post_residual as f64 / bin_capacity as f64);
        score -= 2.0 * open_bins_count as f64 * fit_ratio;
    }

    // Time horizon: late in the stream, be extra thrifty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = x * (1.0 + 0.6 * t) - 0.35 * x * x * (1.0 + t);

    // Reward tight fits: small post residual gets extra discount, stronger late in stream.
    let tightness = (1.0 - x).powi(3);
    score -= 1.2 * tightness * (0.5 + t);

    // Penalize dead space that is too small for typical items (near-zero usable) but not a perfect fit.
    let dead = x * (1.0 - x);
    score += 0.5 * dead * (1.0 + 2.0 * t);

    // Lookahead: favor bins whose residual after placement can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let fit_frac = nxt / cap;
            score -= 0.8 * fit_frac * (1.0 - t);
        } else {
            score += 0.3 * (1.0 - t);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 + t);
    }

    // Slight preference against spreading across too many open bins when residuals are large.
    let mean_x = mean_residual / cap;
    score += 0.15 * mean_x * x * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral baseline so it wins only when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 0.55 + 0.4 * t - 0.2 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits (small leftover) rewarded with non-linear decay.
    score -= 120.0 * (-(pr / 12.0)).exp();

    // Harmonic class penalty: dead space in awkward modulo bands is less reusable.
    // Items 1..100, common small items cluster near small values; residuals that are
    // congruent to small sizes modulo 10 are more reusable.
    let mod_class = post_residual % 10;
    let mod_bonus: f64 = match mod_class {
        0 => 18.0,
        1 | 2 | 3 => 10.0,
        4 | 5 | 6 => 4.0,
        _ => -6.0, // awkward 7..9 leftover
    };
    score -= mod_bonus;

    // Penalize residuals that cannot host the lookahead item (wasted for k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host next item: reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (-(slack / 25.0)).exp();
        } else {
            // cannot host next item: penalize proportionally to wasted fraction
            score += 25.0 * (1.0 - pr / cap);
        }
    }

    // Integer-division threshold classes on post_residual (capacity eighths).
    let eighth = (post_residual * 8) / bin_capacity.max(1);
    score += match eighth {
        0 => -40.0,          // nearly full bin, great
        1 => -20.0,
        2 => 0.0,
        3 => 8.0,
        4 => 14.0,
        5 => 18.0,
        _ => 22.0,           // mostly empty bin: poor choice unless last chance
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive for large items or when
    // open bins would be left with useless slivers.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap * 0.9;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // next item also large, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // small items should go into existing bins
        if item_size <= 30 {
            score += 60.0;
        }
    }

    // Mild pressure to fill bins with large mean residual (spread usage).
    score += 0.15 * mean_residual;

    // Slight preference for more-filled bins overall.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable (min item = 10... but sizes 1..100, use small threshold).
    let dead_threshold: f64 = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can host the next item (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a residual that just barely misses the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity so post_residual is large,
    // but add explicit pressure scaled by how full existing bins are.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 12.0 * fill_ratio * (open_bins_count as f64).sqrt();
        // Opening a bin is cheap early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Slight preference for fuller bins (smaller residual before placement).
        score += 0.05 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * -10.0;
        // Prefer bins below mean residual (they are the fullest).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item must be able to fit in the post residual at all
        if next_item_size > post_residual {
            score += 25.0;
        }
    }

    // Relative to mean residual: placing in a bin whose residual is near mean
    // keeps the fleet balanced; avoid fragmenting already-tiny residuals
    let res = post_residual as f64;
    let mean_gap = (res - mean_residual).abs();
    score += mean_gap * 0.15;

    // Penalize very small post_residual unless it's exactly 0 (perfect fill)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 {
            (bin_capacity as f64 - (item_size + next_item_size).min(bin_capacity) as f64)
        } else {
            (bin_capacity - item_size) as f64
        };
        // New bin is penalized by its own waste, discounted when many bins open late
        score = 15.0 + best_possible * 0.6 - (open_bins_count as f64) * 0.5 * (1.0 - progress);
        if post_residual == 0 { score -= 50.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0 / post_residual as f64;
    }

    // Penalize dead space: residual too small for the smallest future items (<= ~10).
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportionally to leftover waste after it.
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.4;
            if two_step_waste == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: mild penalty for creating a stranded bin.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling: an empty bin is only attractive early in the stream
    // or when the current bin would leave unusable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin, reduced early, increased late.
        score += 8.0 + 30.0 * progress;
        // If item is large and no open bin fits well, opening is fine.
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If next item is also large, prefer a fresh bin for it.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Quadratic dead-space penalty, amplified as the stream progresses.
    let dead_frac = post / cap;
    score += (dead_frac * dead_frac) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - dead_frac;
    score -= tightness * tightness * cap * 0.4;

    // Lookahead coupling: if the next item exactly fills the post residual,
    // strongly favor this bin; if next item roughly fits, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= cap * (1.0 - gap).powi(3) * (0.3 + 0.4 * progress);
        } else {
            // Next item cannot use this residual: slight penalty scaling with progress.
            score += dead_frac * cap * 0.2 * progress;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Contextual coupling with mean residual: prefer bins deviating below the mean
    // residual (filling the emptiest-ish bins keeps a spread of usable residuals).
    let dev = (post - mean_residual) / cap;
    score += dev * cap * (0.1 + 0.2 * progress);

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open (consolidation pressure grows with progress).
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.7 * progress) + (open_bins_count as f64) * (0.4 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with tightness reward
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Harmonic class of the post-residual: which "next item size class" fits.
    // Classes at 10, 20, 25, 50 (classic harmonic item sizes).
    let classes: [u32; 5] = [10, 20, 25, 33, 50];
    let mut class_fit = -1i32;
    for (i, &c) in classes.iter().enumerate() {
        if post_residual >= c {
            class_fit = i as i32;
        }
    }
    // Reward residuals that still admit a useful class (larger class = better)
    if class_fit >= 0 {
        score -= 4.0 * class_fit as f64;
    } else {
        // dead residual < 10: strongly penalize unless it was a near-perfect fit
        if post_residual > 0 {
            score += 8.0;
        }
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo / integer-division harmonic structure on residual:
    // residuals that are multiples of 10 pair well with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward for exact two-item fill
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // gives a good fit (tightness low) or open bins are mostly full.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 30.0;
        // but if the item is huge and few bins fit it, opening may be wise
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // late in the stream, avoid scattering
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if mean residual across open bins is small, opening is natural
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // slight preference for keeping number of open bins low
        score -= 1.5;
    }

    // Penalize leaving residuals in the awkward 1..9 range harder as stream progresses
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for any plausible item are worthless.
    // Treat gaps < 10 as total loss; gap in [10, 30) is partially wasted.
    let gap = post_residual as f64;
    if gap == 0.0 {
        score -= 25.0; // perfect fit reward
    } else if gap < 10.0 {
        score += 30.0; // unusable sliver: full dead space penalty on top of gap
    } else if gap < 30.0 {
        score += 0.9 * (30.0 - gap); // partial dead space
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Open bin pressure: discourage spreading across many bins when a good fit exists.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.8 + mean_residual * 0.05;
        score = 60.0 - crowded;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0; // an open bin fits; opening new bin is wasteful
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean
    // (keeps bin population homogeneous and mergeable).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size,
    // penalize post_residuals that leave awkward gaps relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect chain: next item fits exactly into the residual.
            if gap == 0.0 {
                score -= 500.0;
            } else if gap <= 10.0 {
                score -= 150.0;
            } else {
                // Larger leftover after the chained fit is wasted potential.
                score += gap * 0.5;
            }
        } else {
            // Next item cannot use this residual at all: penalize proportionally
            // to how much of the residual is unusable for the next item.
            let unusable = nxt - pr;
            score += unusable * 2.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (packing into fuller bins), penalize bins looser than the mean.
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = (post_residual as f64 - mr) / mr;
        score += rel * 30.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin wastes potential capacity.
    // Only attractive when the item is large relative to capacity and no good
    // fit exists (post_residual of a fresh bin would be large).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; less so for large items early in the stream.
        score += 300.0;
        score -= fill_ratio * 200.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 150.0;
        // If many bins are open, discourage yet another one.
        score += open_bins_count as f64 * 10.0;
        // If the next item is small, a fresh large residual is more useful.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 80.0;
        }
    }

    // Slight tie-breaker: prefer bins with more residual consumed so far.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize leaving small, hard-to-fill dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // If next item is slightly larger than post_residual, mild penalty for stranding space.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Crowding effect: many open bins with large mean residual -> prefer consolidation.
    let crowding = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score += crowding * 2.0;

    // Time horizon: early in the stream, be more exploratory (favor tight fits less aggressively);
    // late in the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: only attractive when item is large relative to capacity and open bins are poor fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Discourage new bins when plenty of aggregate residual exists.
        score += mean_residual * 0.3;
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score -= (bin_residual as f64 - item_size as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * (1.0 - norm_pr) * t;
    score += 40.0 * poly;

    // Reward tight fits: post_residual near zero
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + t);

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 15.0 * (1.0 - gap.min(1.0)).powi(2) * (1.0 - t);
    }

    // Penalize last-chance bins mildly unless fit is tight
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr).powi(2);
        score += 5.0 * norm_pr * (1.0 - norm_item);
    }

    // Mean residual interaction: penalize bins deviating from mean
    let dev = (mean_residual - pr).abs() / cap;
    score += 8.0 * dev * (0.5 + 0.5 * t);

    // Slight preference for consolidating into fewer bins late in stream
    score -= 3.0 * fit_ratio * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - norm_item) * (1.0 - 0.5 * t);
        if next_item_size > 0 && norm_next + norm_item > 0.9 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small item friendly" classes (0,1..=10, or multiples of 10) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 && pr <= 30 {
        score -= 25.0; // leftover is a round number in the small-item band
    } else if pr <= 10 {
        score -= 18.0; // tiny dead space
    } else if pr % 10 == 0 {
        score -= 8.0;  // round but larger leftover
    } else {
        // irregular leftover: penalize by its distance to nearest multiple of 10
        let d = (pr % 10).min(10 - pr % 10);
        score += d as f64 * 1.5;
    }

    // Integer division thresholds: leftover class pr/20 (0..=5)
    let class = pr / 20;
    score -= (5 - class.min(5)) as f64 * 4.0;

    // Lookahead coupling: does the leftover harmonically fit next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact / harmonic matches get strong reward
            if pr % next_item_size.max(1) == 0 {
                score -= 22.0;
            } else {
                score -= 10.0;
            }
            // leftover after a hypothetical next placement
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 15.0;
            } else if pr2 <= 10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this leftover: penalize dead space proportionally
            score += (next_item_size - pr).min(40) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        // base cost of opening a new bin
        score += 55.0;
        // discount when open bins are crowded / residuals are large
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        score -= crowd.min(8.0) * 2.0;
        // late in stream, prefer closing out existing bins
        score += progress * 15.0;
        // large items open fresh bins more willingly
        if item_size >= 50 {
            score -= 12.0;
        }
    }

    // Mild preference for tighter existing bins
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Progression: slightly prefer filling older bins as stream advances
    score += (step_index as f64 / (total_items.max(1) as f64)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small but potentially usable gaps: moderate penalty scaled by gap size.
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Bonus if the leftover gap can still host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Bin would have fit the lookahead item but this placement breaks it.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 3.0;
        // But if the item leaves a perfect residual, new bin is still attractive.
        if post_residual == 0 {
            score -= 130.0;
        }
    }

    // Mild progress term: slightly prefer consolidating into older bins
    // early in the stream when mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual - post_residual as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward: post_residual exactly matches the next item's size (2-step lookahead match)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * progress;
    }
    // Moderate reward: next item still fits into the post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.15 * slack;
    }

    // Penalize small non-zero dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward closing a bin exactly (perfect packing)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals are poor
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen unless existing bins are bad
        score += 15.0;
        // If the mean residual of open bins is large, existing bins are fine -> penalize new bin more
        if mean_residual > (post_residual as f64) + 20.0 {
            score += 25.0;
        }
        // Late in the stream, discourage opening new bins
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is close to the mean (balanced usage)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Mild pressure to consolidate into fewer bins
    if open_bins_count > 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight_fit_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;
    score -= tight_fit_bonus;

    // Penalize leaving residuals that are too small to be useful for future items
    // (dead space). If post_residual is small but nonzero, it's wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits in the post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item doesn't fit: penalize proportionally to how much of next item is wasted
        let gap = next_item_size as f64 - post_residual as f64;
        score += gap * 0.08;
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless current
    // residuals are all poor fits (large fragmentation).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 8.0;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // If mean residual across open bins is high, there's plenty of room
        // elsewhere; opening a new bin is less needed but we still prefer
        // consolidating. Penalize more when mean residual is large.
        score += mean_residual * 0.10;
        // Late in the stream, prefer closing out existing bins rather than
        // starting new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Existing bin: slight preference for bins with residuals close to the
        // item size (perfect fill), scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_match = 1.0 - ((bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64);
        score -= fit_match * (4.0 + progress * 6.0);
    }

    // Global pressure: when many bins are open relative to items processed,
    // encourage consolidation into existing bins.
    if open_bins_count > 0 {
        let bins_per_item = open_bins_count as f64 / (step_index as f64 + 1.0);
        if bin_residual != bin_capacity {
            score -= bins_per_item * 3.0;
        }
    }

    // Small tie-breaker favoring fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in the stream, penalize dead space strongly.
    let progress_coupling = 1.0 + 3.0 * progress * progress + 2.0 * progress * norm_pr;
    score *= progress_coupling;

    // Smooth penalty for leaving residuals that no plausible next item fits:
    // interaction between post_residual and lookahead size.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.5 * gap * gap / cap;
        // Reward bins whose post_residual exactly accommodates the next item.
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (smooth sigmoid-like gate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - norm_pr;
        score -= 6.0 * fit_quality * fit_quality;
    }

    // Mild penalty proportional to mean residual imbalance (prefer balanced fills).
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer keeping it closed early; more attractive later
    // or when existing residuals are highly fragmented.
    if bin_residual == bin_capacity {
        score = cap * (1.5 - progress) + 0.4 * mean_residual;
        if fitting_bins_count == 1 {
            score += 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Harmonic class of post_residual: reward residuals that are "usable" classes.
    // Class A: post_residual == 0 (perfect closure) -> strong reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Class B: post_residual < 10 (dead space, unusable for min item 1) -> penalty
    else if post_residual < 10 {
        score += 12.0;
    }
    // Class C: post_residual divisible into nice fractions of capacity
    let cap = bin_capacity as u32;
    if post_residual == cap / 2 || post_residual == cap / 4 || post_residual == 3 * cap / 4 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 {
        score -= 5.0; // round-number residuals are easier to fill later
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual -> slight penalty proportional to waste
            score += 3.0;
        }
        // integer-division threshold coupling: next item divides residual evenly
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening penalty so we
    // only open when open bins are genuinely bad fits.
    if bin_residual == cap {
        score += 20.0;
        // but if item is huge relative to capacity, new bin is fine
        if item_size * 2 >= cap {
            score -= 10.0;
        }
    }

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Spread-awareness: many open bins with low mean residual -> prefer consolidation
    if open_bins_count > 3 && (mean_residual < 30.0) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..small) can use are heavily penalized.
    let dead_zone: u32 = 12;
    if post_residual > 0 && post_residual < dead_zone {
        // The smaller the unusable gap relative to the smallest plausible item, the worse.
        let severity = (dead_zone - post_residual) as f64 / dead_zone as f64;
        score += 25.0 * severity * severity;
    }
    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Moderate residual that can still host the next item is mildly rewarded.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        // Residual cannot host the lookahead item: penalize proportionally.
        score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 {
            1.0
        } else {
            let best_gap = (bin_residual - item_size) as f64;
            (best_gap / bin_capacity as f64).max(0.0)
        };
        // Base cost of opening a bin, discounted if current fits are all poor.
        score += 14.0 - 10.0 * bad_fit;
        // Late in the stream, opening new bins is even less attractive.
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size exactly (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            // Strong reward for exact match, decaying with gap size.
            score -= 30.0 * (-gap / 12.0).exp();
        } else {
            // Next item won't fit here: penalize dead space creation,
            // scaled by how small the leftover is (unusable sliver).
            let dead = pr;
            score += 8.0 * (dead / 40.0).exp() * (1.0 - dead / (bin_capacity as f64));
        }
    } else {
        // Last item: purely minimize leftover.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more
    // valuable to fill; bins looser than average can absorb waste.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fit_ratio = item_size as f64 / residual.max(1.0);
    score -= 12.0 * fit_ratio;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space), but reward exact/near-exact closures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_zone = (post_residual as f64) > 0.0 && (post_residual as f64) < 10.0;
    if dead_zone {
        score += 8.0 * (1.0 - progress);
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure is excellent
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post-residual can't host next item: mild penalty scaled by waste
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is penalized unless current bins
    // would create lots of dead space.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        let pressure = avg_waste / bin_capacity as f64;
        // Prefer new bin when open bins are mostly full (few options left) and
        // this item is large relative to typical residual.
        score += 25.0;
        score -= 30.0 * pressure;
        score += 0.4 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (future items can use them).
        score -= 15.0 * (1.0 - progress);
        // Large items justify fresh bins more.
        score -= 0.1 * item_size as f64;
    } else {
        // Prefer bins below mean residual (balance load) slightly.
        score += 2.0 * (residual - mean_residual) / bin_capacity as f64;
    }

    // Global consolidation pressure: as stream progresses, encourage filling
    // existing bins rather than spreading.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual and item size
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Non-linear polynomial coupling: penalize mid-range dead space quadratically,
    // with strength increasing as the stream progresses.
    let dead_space_penalty = (pr * (1.0 - pr)).powi(2) * (1.0 + 3.0 * progress) * cap;
    score += dead_space_penalty;

    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= (1.0 - pr).powi(3) * cap * 0.5;

    // Interaction: item size vs progress — prefer packing large items early,
    // small items later (smooth polynomial in progress).
    score += it * (progress - 0.5) * cap * 0.4;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 + progress);
    }

    // Penalize spreading across many open bins (smooth in open count)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead coupling: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr * cap {
        let nx = next_item_size as f64 / cap;
        score -= nx * cap * 0.5 * (1.0 - pr);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers that are "harmonically useful"
    // (large enough to host common small items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional position within the bin (0..1)
    let post_frac = post / cap;

    // Class the post_residual by integer division thresholds (harmonic tiers)
    // tier 0: post > 50 (half bin left, very usable)
    // tier 1: 25 < post <= 50
    // tier 2: 10 < post <= 25 (danger zone: dead space for small items)
    // tier 3: post <= 10 (near-full, excellent)
    let tier: u32 = if post_residual > 50 { 0 }
        else if post_residual > 25 { 1 }
        else if post_residual > 10 { 2 }
        else { 3 };

    match tier {
        0 => score -= 12.0,          // plenty of room remains: good
        1 => score -= 4.0,           // moderate room
        2 => score += 10.0,          // dead-space risk zone: penalize
        _ => score -= 8.0,           // near-perfect fill: reward strongly
    }

    // Modulo-arithmetic harmony: leftover compatible with common item sizes
    // (multiples of 10 and common sizes 10..80) gets a bonus.
    if post_residual >= 10 {
        let harmonics = [10u32, 20, 25, 30, 40, 50];
        if harmonics.iter().any(|&h| post_residual == h) {
            score -= 6.0;
        }
        // leftover that is an exact multiple of 10 is highly reusable
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    } else if post_residual > 0 {
        // tiny unusable sliver
        score += 5.0;
    }

    // Lookahead: does the next item fit in the resulting residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // perfect lookahead fit: strong reward
        score -= 14.0;
        // extra reward if next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this leftover: penalize proportionally to waste
        let waste = post / (next_item_size as f64);
        score += 6.0 * (1.0 - waste.min(1.0));
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has neutral base (post = cap).
    // Make it attractive only when current fit is bad. Compare against
    // mean residual: if open bins are already fragmented, prefer new bin.
    if bin_residual == bin_capacity {
        // base new-bin score equals cap minus tier-0 bonus already applied;
        // adjust with stream progression: later in the stream, prefer
        // consolidating into existing bins unless fit is poor.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // penalize new bins when many bins are open and mean residual is high
        // (fragmentation means we should reuse)
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Prefer tighter existing bins: the smaller the residual before placement
    // relative to item, the better the fit quality.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Exact fit is ideal regardless of anything else.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Mild pressure to close bins as stream progresses (prefer filling old bins)
    score += 2.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are heavily penalized (quadratic in unusability).
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        let gap = (dead_threshold - post_residual) as f64;
        score += 6.0 * gap * gap / dead_threshold as f64;
    }

    // Reward near-perfect fits (residual exactly 0 is ideal).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size {
            score += 4.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            if slack < dead_threshold as f64 {
                score += 2.0 * (dead_threshold as f64 - slack) / dead_threshold as f64;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * pressure * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins with below-average residual
    // (tighter bins) to keep large residuals available for large items.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize slightly so we only open a new bin
    // when every open bin would create real dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly or nearly.
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by how badly.
            score += 8.0 * (gap as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness matters.
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins that are already "used up"
    // (residual below mean) to concentrate waste in few bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin unless no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline penalty; relax if item is large and mean residual is small.
        let mut penalty = 45.0 + 20.0 * (1.0 - progress);
        if item_size as f64 > mean_residual + 5.0 {
            penalty -= 30.0; // existing bins are too full anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 25.0; // fresh bin enables lookahead chain
        }
        score += penalty.max(0.0);
    }

    // Avoid leaving exactly tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space elimination).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin, more so when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * (fitting_bins_count as f64) * (1.0 - 0.5 * progress);
    }

    // Prefer bins tighter than the mean residual (keep large holes for large items).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for consolidating into fewer bins early in the stream.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, with non-linear polynomial coupling
    let mut score = post * (1.0 + 0.6 * progress);

    // Non-linear penalty on wasted space: quadratic dead-space term scaled by progress
    let post_norm = post / cap;
    score += 8.0 * post_norm * post_norm * (0.5 + progress);

    // Reward near-perfect fits (small residual) with a smooth exponential bonus
    let tightness = 1.0 - post_norm;
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead: bonus if the next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fills leftover nicely
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        } else {
            // leftover too small for next item: penalize proportionally
            score += 2.0 * (1.0 - post / nxt);
        }
    } else {
        // last item: reward zero waste strongly
        score -= 5.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fits are poor (large post residual) or few bins open
    if bin_residual == bin_capacity {
        let poor_fit = post_norm; // for empty bin, post_norm == 1.0
        let _ = poor_fit;
        // Score of empty bin: baseline near cap, adjusted by how bad alternatives would be
        score = cap * (0.55 + 0.25 * (1.0 - progress));
        score -= 3.0 * (mean_residual / cap);
        if open_bins_count == 0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
        // late in stream, avoid opening new bins unless necessary
        score += 6.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            // a fresh bin can host both items
            let combined = item_size as f64 + next_item_size as f64;
            if combined <= cap {
                score -= 4.0;
            }
        }
    }

    // Mild penalty proportional to number of open bins to discourage spreading
    if bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // modulo fractions of capacity (residuals in high-utility classes).
    let pr = post_residual;
    // Class bonus: residuals divisible into common item sizes are valuable
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else {
        // reward residuals that can host typical next items
        let class = pr % 10;
        let class_bonus = match class {
            0 => 8.0,          // multiple of 10: flexible
            5 => 4.0,          // half-decade
            2 | 4 | 6 | 8 => 1.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Integer-division thresholds: residual >= half capacity is a "rich" bin
        if pr * 2 >= bin_capacity {
            score -= 3.0;
        }
        if pr * 3 >= bin_capacity * 2 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: strongly reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0 + (pr - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // dead space penalty scaled by how much next item overshoots
        score += ((next_item_size - pr) as f64) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-high baseline; open a new bin only when
    // existing fits would create large dead space or none fit well.
    if bin_residual == bin_capacity {
        score = 60.0
            + (open_bins_count as f64).sqrt() * 2.0
            - (mean_residual / bin_capacity as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild phase term: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.5;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
        // Extra penalty if next item would exactly fill another bin better.
        if post_residual < next_item_size / 2 {
            score += 8.0;
        }
    }
    // Reward when post_residual can exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count grows; encourage consolidating into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.35 + 0.65 * t);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if no open bin fits well,
    // i.e. when mean residual across open bins is small relative to item.
    if bin_residual == bin_capacity {
        // Base new-bin score: keep it high unless open bins are truly poor.
        score = bin_capacity as f64 * 0.9 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight reward for bins tighter than average (good consolidation).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * f64::exp(-gap / 8.0);
        // Exact match: next item fills this bin completely afterwards.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Avoid leaving a residual that can't fit the next item if it's small waste
        if next_item_size > post_residual {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 10.0 * f64::exp(-(post_residual as f64) / 5.0);
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (consume crowded space), penalize consuming sparse space.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing (min size 1..) can use well:
    // small nonzero post_residuals are awkward only if tiny; exact tiny fits are fine.
    if post_residual > 0 && post_residual < 3 {
        score += 6.0;
    }

    // Slight preference for keeping fewer open bins when residuals are similar.
    score += 0.01 * open_bins_count as f64;

    // Early stream: be more conservative, favor tightest fits; late stream: pack fast.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins that leave small, hard-to-use residuals.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Dead-space penalty: residuals below the minimum item size (1) can never be used,
    // and tiny residuals (< 10) are nearly dead for typical streams.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; residual is likely stranded.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: opening a new bin is costly; discourage unless it enables
    // a much better fit. New bin residual = full capacity.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
        score += 18.0 + 10.0 * progress + 1.5 * crowding;
        // But if existing bins are badly fragmented (high mean residual but poor fit),
        // a fresh bin becomes more attractive.
        if mean_residual > 40.0 {
            score -= 12.0;
        }
    }

    // Mild preference for filling already-open bins as the stream progresses,
    // reducing the number of open bins at the end.
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = post / cap; // normalized post residual in [0,1]
    let p = progress;
    // Penalize wasted space more strongly as stream progresses (fewer chances to fill it).
    score += 30.0 * (1.0 - p) * x * (1.0 - x) * (1.0 - x) - 10.0 * p * x * x;

    // Reward tight fits: small post residual gets a quadratic bonus.
    score -= 25.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - p);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            // Perfect chain: post_residual == next_item_size
            score -= 35.0 * (1.0 - gap * gap) * (0.5 + 0.5 * p);
        } else {
            // Next item won't fit: dead space risk, penalize.
            score += 15.0 * (nxt / cap) * (1.0 - p);
        }
    }

    // Coupling with mean residual: prefer bins whose residual differs from mean
    // (concentrate waste into few bins, keep others flexible).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate (empty bin): penalize mildly early, more when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - p) + if fitting_bins_count > 0 { 25.0 } else { 0.0 };
    }

    // Slight preference for using existing bins when many are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot" of the capacity it falls into.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty for tiny unusable residuals (harmonic bottom class).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residuals in (0, quarter] are hard to fill: graded penalty.
    if post_residual <= quarter {
        score += (quarter - post_residual) as f64 * 0.5;
    }
    // Residuals that exactly divide the capacity (harmonic anchors) are valuable.
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward residuals that can host the next item's class.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Bonus if next item would leave another harmonic-class residual.
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 10.0;
        } else if next_post >= 10 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.6 {
            score -= 15.0; // big item: fresh bin is fine
        } else if fitting_bins_count > 0 {
            score += 20.0; // small item: prefer existing bins
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    // Global context: when open bins are collectively full, prefer reuse.
    if mean_residual < (item_size as f64) && bin_residual >= item_size {
        score -= 4.0;
    }

    // Modulo-class tiebreak on post_residual to break ties deterministically.
    let cls = post_residual % 8;
    score += cls as f64 * 0.125;

    // Slight preference for tighter bins when many bins fit the item.
    if fitting_bins_count > 2 {
        score += (bin_residual - item_size) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small gap zone: risky dead space, mild penalty.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 - (slack as f64).min(10.0) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual becomes dead space for the known next item.
        score += 6.0;
    }

    // Open-bin pressure: prefer spreading across existing bins when few are
    // open; prefer filling bins densely when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * 0.15;

    // Last chance: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 18.0;
        if post_residual < 10 {
            score += 30.0; // undo: dead space not worth saving a bin
        }
    }

    // Mean residual coupling: penalize bins far below the mean residual
    // (they are already "tight"); prefer using bins with lots of slack.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // New-bin candidate: empty bin should only win when no open bin gives a
    // decent fit. Make it moderately attractive by default.
    if bin_residual == bin_capacity {
        score = 35.0 + pressure * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin keeps full flexibility
            score -= 3.0;
        }
        if fitting_bins_count <= 1 {
            // no real alternative: new bin is fine
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this is a perfect pairing — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits inside leftover: good chaining, mild reward
            // proportional to tightness of the second fit.
            let second_left = post_residual - next_item_size;
            if second_left <= 10 {
                score -= 150.0;
            } else {
                score -= 40.0;
            }
        } else {
            // Next item will NOT fit here: leftover risks becoming dead space.
            // Penalize small unusable leftovers more than large usable ones.
            let gap = next_item_size - post_residual;
            if post_residual < 10 {
                score += 120.0; // tiny dead space
            } else if gap <= 10 {
                score += 40.0; // near miss, moderately bad
            } else {
                score += 10.0; // large leftover may still be useful later
            }
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "nearly full" — placing here consolidates waste; reward that.
    if (bin_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - bin_residual as f64);
    } else {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless the current item is
    // large and no open bin offers a decent fit. An empty bin starts with
    // score == capacity, so bias it upward slightly to prefer filling
    // existing bins, but allow it when open bins would leave big waste.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the item is huge relative to capacity and fits poorly anywhere,
        // opening a fresh bin becomes competitive.
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Late in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += (post_residual as f64) * (1.0 - usable) * 0.8;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 2.5 * (-gap / 15.0);
    }

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins early / when few bins open; scale with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 15.0 * (1.0 - progress);
        // But if the item is large and fits poorly anywhere, opening a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 8.0;
        }
    }

    // Prefer packing into bins whose residual is already small (consolidate).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild pressure to close bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * (1.0 + step_index as f64 / (total_items.max(1) as f64));

    score
}

