pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the same residue class
    // modulo 10 tend to admit the same future item classes.
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.15;

    // Dead-space penalty: residuals below 10 are nearly unusable (min item = 1,
    // but small residuals waste capacity on average).
    if post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward: harmonic sweet spots (0 residual, or residual that
    // exactly matches the lookahead item).
    if post_residual == 0 {
        score -= 60.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Lookahead fit: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally to waste.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Integer-division threshold on residual fraction of capacity.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score -= 8.0; // large residual left: bin stays flexible
    } else if frac < 0.2 && post_residual > 0 {
        score += 10.0; // small awkward leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: score it neutrally-high so it's chosen only when
    // open bins have bad fits, but slightly cheaper late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 - progress * 10.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

