    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Penalize new bins unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
