    // Next item fits in the leftover space: strong reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tightness;
    }
    // Next item does NOT fit in leftover: penalize dead space, worse for large leftovers.
    if next_item_size > post_residual {
        score += (post_residual as f64) * (post_residual as f64) / 50.0;
    }

    // Small leftovers are unusable dead space; penalize sharply below threshold.
    if post_residual < 10 {
        score += 40.0;
    }

