    // (tighter packing) when the fit is good, avoid dumping into already-loose bins.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin (only one fitting bin): strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (residual == capacity): penalize unless the current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening fresh is worthwhile if item leaves a huge hole elsewhere or no real fit.
        if post_residual == 0 {
            score -= 55.0; // perfect fit in a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // Slight preference for filling older bins as the stream progresses (reduce bin sprawl).
    score -= 0.01 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

