    }

    // Lookahead coupling: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Penalize spreading across many open bins mildly; encourage consolidation
    // when mean residual is low (bins are getting full).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Time horizon: later in the stream, favor closing bins tightly (higher fill ratio),
    // early in the stream allow more exploratory placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 40.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
