        score += 120.0 + 200.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.5 * item_size as f64;
        // If several bins already fit, discourage a new bin.
        score += 30.0 * fitting_bins_count as f64;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
