    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Mild pressure toward consolidation relative to the mean residual
    score += 0.15 * (post - mean_residual);

    // New-bin candidate: keep it attractive only when open bins are very full
    if bin_residual == bin_capacity {
        score -= 8.0 * mean_residual / cap * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
