    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of 10, or small enough to be
    // fillable by small items) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residue 0 => perfectly harmonic leftover, reward strongly.
        if class == 0 {
            score -= 25.0;
        } else if class <= 3 {
            // Tiny dead space, nearly harmonic.
            score -= 8.0;
        } else if class >= 7 {
            // Awkward leftover: penalize.
            score += 10.0 + (class as f64 - 6.0) * 3.0;
        }
    } else {
        // Perfect fill: maximally reward.
        score -= 60.0;
    }

    // Integer-division threshold: leftover in [1,9] is dead space unless
    // the next item can use it.
    if pr > 0 && pr < 10 {
        if (next_item_size as u32) <= pr && next_item_size > 0 {
            score -= 15.0; // next item exactly consumes dead space
        } else {
            score += 12.0; // unusable sliver
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let slack = pr - next_item_size as u32;
        score -= 10.0 + slack as f64 * 0.3;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: prefer fuller bins when many bins are open.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Mean residual coupling: when mean residual is high, keep tight fits;
    // when low, spread items.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Stream progression: late in the stream, prefer perfect fills more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - pr as f64) * 0.1;

    // New-bin candidate handling: an empty bin has large post_residual;
    // only prefer it when no open bin fits well (fitting_bins_count == 0)
    // or the current item is huge.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin anyway
        } else if item_size >= 60 {
            score += 15.0; // big items: prefer existing bins if possible
        } else {
            score += 45.0; // discourage opening new bins casually
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..10) are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize residuals that cannot fit the known next item (k=2 lookahead):
    // a gap that blocks the upcoming item is dead space in waiting.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward filling bins that are already fairly empty (consolidation):
    // prefer placing into bins whose residual is small relative to capacity.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: with many open bins, favor consolidating into
    // existing bins over spreading; mildly discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and late
        // in the stream, unless it is the only fitting option.
        let pressure = open_bins_count as f64 * 3.0 + progress * 15.0;
        score += pressure;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new one.
        score -= 25.0;
    }

    // Slight preference toward bins below the mean residual (keeps larger
    // gaps available for larger future items).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the next item cannot use.
        score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize when this bin's residual deviates favorably from mean (keep balanced residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Discourage opening a new bin when open bins can already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 20.0 * (1.0 - progress);
    }

    // Mildly prefer consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better (already the base).

    // Penalize large leftover dead space non-linearly; small residuals (<=10)
    // are nearly dead space, but exact zero is perfect.
    if post_residual == 0 {
        score -= 50.0; // perfect fit bonus
    } else if post_residual <= 10 {
        score += 15.0; // nearly-dead space penalty
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer the bin with the least residual waste.
        score += 0.5 * fitting_bins_count as f64;
    }

    // Lookahead: if the next item can also fit into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving a residual too small for the next item (dead space risk).
        score += 0.3 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the current item is huge relative to mean residual across bins,
        // opening a fresh bin may be wise: reduce penalty.
        let avg_gap = mean_residual - item_size as f64;
        if avg_gap > 20.0 {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Slight preference for fuller bins (low residual relative to capacity).
        score += 0.1 * (bin_capacity - bin_residual) as f64 * -0.01;
        // Prefer bins whose residual deviates below the mean (consolidating space).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Global state: many open bins -> encourage consolidation into existing bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Base: penalize post-residual with non-linear (convex) coupling so
    // small residuals are strongly favored over moderate ones.
    let mut score = pr + 60.0 * pr2 + 90.0 * pr3;

    // Stream-progress coupling: early on, waste tolerance is higher (favor
    // spreading), late in the stream, tighten (multiply penalty upward).
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - pr_norm);
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth bonus when item fills most of bin.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill * (1.0 - pr_norm);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Many fitting bins: mild penalty for this bin if its residual is far
    // from the mean (encourages balanced residual profiles).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * (open_bins_count as f64).ln().max(1.0) / (1.0 + fitting_bins_count as f64);

    // Lookahead: if next item fits exactly into the post-residual, reward;
    // if next item is much larger than post-residual, mildly penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs();
        score += 0.15 * gap;
        if nxt <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // New-bin candidate: keep it competitive only when open bins would leave
    // large dead space; otherwise make the empty bin unattractive.
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap).clamp(0.0, 1.0);
        score = 45.0 + 55.0 * (1.0 - spread) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse dead-space classes via integer division.
    let class = post_residual / 10; // 0..10 harmonic class of leftover space
    // Small classes (tight fits) are excellent: reward them nonlinearly.
    score -= match class {
        0 => 18.0,
        1 => 9.0,
        2 => 4.0,
        3 => 1.0,
        _ => 0.0,
    };

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo coupling: post_residual divisible by small harmonics (10, 20, 25)
    // tends to pair well with future items on a 100-capacity grid.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }
    if post_residual % 20 == 0 {
        score -= 1.0;
    }

    // Lookahead: does next_item_size fit in the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chain potential: strongly favor bins that can host the next item too.
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 + slack * 0.05;
        if (post_residual - next_item_size) == 0 {
            score -= 10.0; // perfect two-item chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize if next item is small
        // (wasted capacity on a long stream).
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open-bin
    // residuals are poor (large post_residual would be created elsewhere).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin: residual = 100 - item_size.
        score = (bin_capacity - item_size) as f64;
        // Penalize opening bins when many are already open and have usable space.
        score += open_bins_count as f64 * 0.5;
        // Early in the stream, opening bins is cheaper (building diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 4.0;
        // If next item is large and current item is small, a fresh bin is attractive.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 6.0;
        }
        // Guard: never let the empty bin beat an exact/tight fit elsewhere.
        if score < 1.0 {
            score = 1.0;
        }
    }

    // Mild penalty for spreading across many bins with large mean residual.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 0.02 * (mean_residual - 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if it's smaller than the smallest plausible item (1) —
    // but practically, gaps below ~10 can only be filled by very small items,
    // so apply a superlinear penalty in the low-gap regime.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * 8.0; // near-zero gap => large penalty
    } else if gap == 0.0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Penalize gaps that cannot host the lookahead item (wasted capacity w.r.t. future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward if the lookahead item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many open bins
    // unless this placement is efficient (large item fraction of residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score += open_bins_count as f64 * (1.0 - fill_ratio) * 3.0;
    score -= fill_ratio * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; grows with number of open bins and stream progress.
        let mut new_bin_cost = 30.0 + open_bins_count as f64 * 1.5;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost += progress * 10.0;
        // If item is large relative to capacity, a fresh bin is reasonable.
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // If lookahead item is large, having a fresh bin available helps.
        if next_item_size > 0 && next_item_size > 60 {
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost;
    }

    // Mild alignment with mean residual: prefer bins whose residual deviates
    // favorably (smaller than mean => tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Strong reward for tight 2-step fit
            score -= (bin_capacity as f64 / (1.0 + slack)) * 0.6;
            if slack == 0.0 {
                score -= 25.0; // perfect 2-step chain
            }
        } else {
            // Next item cannot fit here; penalize large dead space
            score += 0.15 * (post - nxt).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless current bins are too full
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 40.0 * (1.0 - tightness);
        // If item is large, opening a fresh bin is more acceptable
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer filling bins tighter than the mean residual
    let diff = post_residual as f64 - mean_residual;
    score += 0.1 * diff;

    // Slight preference for compact bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // if post-residual is awkward relative to next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // existing residuals are fragmented or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut open_penalty = 12.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            open_penalty -= 30.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            open_penalty -= 5.0; // fresh bin is flexible for lookahead
        }
        score += open_penalty + 0.05 * fragmentation * (1.0 - progress);
    } else {
        // Prefer bins with larger residual when many bins are open (consolidation).
        score -= 0.02 * bin_residual as f64 / open_bins_count.max(1) as f64;
    }

    // Mild time-horizon modulation: early on, be greedy about tight fits;
    // later, be more conservative about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Base: prefer small post-residual, smoothly warped
    let mut score = pr_frac * (1.0 + 0.6 * pr_frac * pr_frac);

    // Reward tight fits with a smooth non-linear coupling scaled by stream progress
    score -= (1.0 - pr_frac) * (1.0 - pr_frac) * (1.0 + 1.5 * progress);

    // Penalize dead space that is too small for typical future items,
    // penalized more as the stream progresses (less room to recover)
    let dead = pr_frac * (1.0 - pr_frac);
    score += 0.8 * dead * (0.5 + progress);

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as u32) >= (next_item_size as u32) {
            let snug = 1.0 - ((pr as f64 - nxt) / cap);
            score -= 0.9 * snug * (1.0 + progress);
        } else {
            // post-residual too small for next item: mild penalty growing with progress
            score += 0.5 * (1.0 - pr_frac) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., a large bin) is mildly favored to consolidate space
    let mean_frac = mean_residual / cap;
    score += 0.3 * (pr_frac - mean_frac) * (pr_frac - mean_frac);

    // New-bin candidate handling: only attractive early or when current bin fits poorly
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = 0.9 + 0.6 * openness + 1.2 * fit_frac * progress;
        if fitting_bins_count == 1 {
            score += 3.0; // never open new bin when an existing one is the last chance
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead-space classes
    // post_residual mod 10 captures "waste classes"; small residues (<10) are near-unusable.
    let residue_class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // nearly dead space
    } else if residue_class == 0 {
        score -= 25.0; // perfectly divisible leftover, easy to refill
    } else if residue_class <= 3 {
        score += 15.0;
    }

    // Compatibility: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item divides or nearly fills the leftover
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next % 10 == 0 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            score += 20.0; // next item can't use this bin's leftover
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave a bad class and the item fits snugly alone (large item).
    if bin_residual == bin_capacity {
        // empty bin: attractive if item is large (tight fit) or many bins open
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 20.0;
        } else {
            score += 35.0 + 10.0 * (1.0 - tightness);
        }
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // Nudge toward bins tighter than the mean residual (good packing)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small to fit even the smallest plausible item (1..100).
    // Treat gaps below ~10 as pure waste, and gaps 10..30 as increasingly risky.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 30 {
        // Penalize gaps that few item sizes can fill.
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when residual is plentiful.
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual alignment: prefer bins close to the mean residual (keeps flexibility).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 10 {
            score -= 10.0; // still better than a fresh bin for tiny waste
        }
    }

    // New-bin candidate: make it moderately unattractive unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
    }

    // Slight stream-progression tilt: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chaining the next item into this bin, stronger the tighter the chain.
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving dead space the next item can't use.
            score += 8.0;
            if post_residual < 10 {
                score -= 4.0; // tiny dead space is fine (near-perfect fill)
            }
        }
        // Perfect 2-item fill (post_residual == next_item_size) is excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (denser bins), avoid wasting space in the emptiest bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for opening a new bin early in the stream when many
    // bins are already open and fit is poor (post_residual large).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 40 {
        score += 6.0 * (1.0 - progress);
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is barely larger than item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.75 {
        score -= 12.0 * fit_ratio * fit_ratio;
    }

    // Penalize large post-residuals that are too small to host typical future items
    // (dead space): if post_residual < next_item_size, waste is likely.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.05 * post_residual as f64;
    }
    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer consolidating into existing bins
    // (keep flexibility); late in stream, tight packing matters most.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> favor filling
    // existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score -= 0.3 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let poor_fit = fit_ratio < 0.5;
        if poor_fit || item_frac > 0.9 {
            score -= 5.0 + 10.0 * item_frac;
        } else {
            score += 20.0; // discourage opening bins when decent fits exist
        }
    }

    // Small penalty for very small items into large-residual bins (save big
    // residual bins for big items).
    if item_size < 20 && bin_residual > 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) waste shaping.
    let mut score = pr_norm * (1.0 + 1.5 * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late in the stream, punish them harder.
    let progress_coupling = pr_norm * (0.5 + 2.0 * progress * progress);
    score += progress_coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr_norm;
    score -= 1.2 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = (nx - pr_norm).max(0.0);
        score += 2.5 * unusable * (1.0 + progress);
        // Smooth lookahead fit bonus: residual close to next item size.
        let closeness = 1.0 - ((pr_norm - nx) / cap * 4.0).abs().min(1.0);
        score -= 1.0 * closeness * closeness;
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Reference to mean residual: bins with residual far below mean waste less.
    let mean_norm = mean_residual / cap;
    score += 0.8 * (pr_norm - mean_norm).abs() * (pr_norm - mean_norm);

    // New-bin candidate handling: empty bin gets a smooth baseline penalty
    // that decreases as the stream progresses (open new bins more readily early).
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) + 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useless" low-residue classes (dead space) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post) / 10.0;
    }

    // Harmonic class reward: leftover that is a "nice" fraction of capacity
    // (divisible into many useful chunk sizes) is favored.
    let nice = |r: u32| -> f64 {
        let mut n = 0.0f64;
        for d in [10u32, 20, 25, 50].iter() {
            if r > 0 && r % d == 0 { n += 1.0; }
        }
        n
    };
    score -= 6.0 * nice(post_residual);

    // Penalize post_residual classes that pair badly with the next item:
    // if next item cannot fit into the leftover, this bin creates a forced gap.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else if next_item_size == post_residual {
            // perfect pair: exhaust the bin
            score -= 30.0;
        } else {
            // leftover after also placing next item
            let r2 = post_residual - next_item_size;
            if r2 < 10 { score += 5.0; }
            score -= 3.0 * nice(r2);
        }
    } else {
        // last item: prefer filling as tightly as possible
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // attractive only when the item fits poorly everywhere else. Base bias:
    if bin_residual == bin_capacity {
        // opening fresh is mildly penalized so existing bins are preferred,
        // unless the fit would be terrible (large dead space).
        score += 15.0;
        if post_residual >= 20 {
            score -= 5.0;
        }
    }

    // Prefer bins below mean residual when item is large (pack tight bins first),
    // above mean when item is small (consolidate slack).
    let item = item_size as f64;
    if item > cap * 0.5 {
        if post < mean_residual { score -= 4.0; } else { score += 2.0; }
    } else {
        if post >= mean_residual { score -= 2.0; }
    }

    // Late in the stream: tighten packing, avoid leaving medium gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - progress);
    }

    // Slight preference for bins with many open competitors to keep bin count low.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable gap below minimum item size
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // awkward narrow gap
    }

    // Perfect or near-perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    // or the next item would fit better in a fresh bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > (bin_residual as f64) * 0.9 {
            score -= 12.0;
        }
    }

    // Lookahead: bonus if the post residual can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are already small; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + 0.5 * progress);

    // Slight preference for bins tighter than the mean (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (the next item fills this bin perfectly).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight matching bonus: strongest when post_residual == next_item_size
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Slight penalty if next item cannot fit here at all (post_residual < next_item_size)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 12.0;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no good fit exists; penalize new-bin slightly
    // otherwise to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0; // allow new bin when alternatives are exhausted
        }
    }

    // Mild consolidation pressure early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item would leave this bin useless if we place here badly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, but relax later; also penalize
        // when open bins are already fragmented (high mean residual)
        score = 0.5 * bin_capacity as f64
            + 60.0 * (1.0 - progress)
            - 20.0 * progress
            + 0.3 * mean_residual;
        if fitting_bins_count == 1 {
            score += 50.0; // avoid wasting a fitting bin's last chance
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 10.0; // new bin can host the next big item too
        }
    } else {
        // Late in stream: fill existing bins aggressively
        score -= 15.0 * progress;
        // Fragmentation control: prefer bins with residual near mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
        // Prefer fuller bins (smaller residual) slightly
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Normalized post-residual (fraction of capacity wasted after placement)
    let pr = post_residual as f64 / bin_capacity as f64;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Base: non-linear waste penalty, amplified as stream progresses
    score = post_residual as f64 + 60.0 * progress * pr2 + 40.0 * (1.0 - progress) * pr3;

    // Coupling with mean residual: bins deviating from mean residual are less attractive
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev * dev * (0.5 + progress);

    // Smooth interaction: post_residual vs next item fit
    if next_item_size > 0 {
        let nxt = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        // reward if next item fits into post residual (smooth logistic-like coupling)
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        let fit_next = 1.0 / (1.0 + (-gap * 8.0).exp());
        score -= 25.0 * fit_next * (1.0 - pr) * (1.0 - progress * 0.5);
        // mild penalty if post residual is just barely below next item (dead space trap)
        if gap < 0.0 {
            score += 10.0 * (-gap) * nxt * progress;
        }
    }

    // Reward tight fits (small post residual relative to bin residual used)
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill * (1.0 - progress);

    // Last-chance bin: strongly favored to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * open_bins_count as f64 * (0.3 + progress);
        // but allow new bin when current item leaves terrible waste in any existing bin
        score -= 35.0 * pr2 * progress;
    }

    // Smooth congestion coupling: many open bins with high mean residual -> prefer consolidation
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.02 * congestion * pr2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice"
    // (multiples of common item size classes), penalize dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual (capacity fractions & common sizes)
    if post_residual % 10 == 0 {
        score -= 6.0; // residual aligns with decile: highly reusable
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 2.5;
    }
    if post_residual % 3 == 0 {
        score -= 1.0;
    }
    if post_residual % 4 == 0 {
        score -= 0.8;
    }
    // Penalize awkward residuals (prime-ish / odd small gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly dead space
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Integer division thresholds: residual usable by next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits: strong reward, scaled by how tightly it fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - (slack / cap) * 4.0;
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 3.0; // chain keeps harmonic alignment
        }
    } else if next_item_size > 0 {
        // next item won't fit here; residual becomes dead weight
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make it unattractive unless residuals
    // of open bins are all poor fits (high mean residual waste).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (mean_residual / cap).clamp(0.0, 1.0);
        // base penalty keeps packing into existing bins
        score += 18.0;
        // but allow opening when open bins are fragmented late in stream
        score -= waste * 10.0 + progress * 4.0 + (open_bins_count as f64) * 0.3;
        // opening a bin for a large item is fine (it fills deeply)
        score -= (item_size as f64 / cap) * 6.0;
    }

    // Slight preference for fuller bins (tightness beyond raw residual)
    let fill_ratio = (bin_residual as f64) / cap;
    score += fill_ratio * 3.0;

    // Mild penalty when many bins compete: prefer concentrating load
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 6.0 {
        // tiny gap: nearly dead space, but if it's exactly 0 it's a perfect fit
        if post_residual == 0 {
            score -= 40.0;
        } else {
            score += 30.0;
        }
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // this bin could also serve the next item: strong reward
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // placement strands the next item into another bin / new bin
            score += 5.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing residuals are large (item fits well nowhere) or fits are poor.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin; add open-bin pressure so we prefer
        // filling existing bins when they fit reasonably well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 10.0 * progress;

        // if the item would leave a large hole in a fresh bin relative to
        // what open bins offer, slight penalty/bonus adjustments:
        if post_residual > 40 {
            score += 10.0; // fresh bin would be mostly empty: discourage
        }
        if mean_residual < item_size as f64 {
            // no open bin is roomy enough in aggregate; new bin is attractive
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin keeps lookahead flexibility
        }
    }

    // Open-bins pressure: with many open bins, tighten selection toward
    // minimizing residual spread (avoid fragmenting space).
    score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs();

    // Mild preference for bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving (almost) no dead space.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 400.0; // next item fills this bin exactly
        } else if diff <= 10.0 {
            score -= 120.0 - diff * 8.0;
        } else {
            // penalize residuals that are too small for anything useful
            let progress = step_index as f64 / total_items.max(1) as f64;
            let small_res_penalty = (20.0 - post_residual as f64).max(0.0) * (1.5 + progress);
            score += small_res_penalty;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 200.0 * fit_ratio;
        } else {
            score += 50.0; // poor fit in the only fitting bin -> consider new bin
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 80.0; // base cost of opening a new bin
        score += waste * 0.5;
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 100.0; // new bin can also take the next item
        }
    }

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Mild penalty for leaving residual in the awkward 11..30 zone (hard to fill).
    if post_residual >= 11 && post_residual <= 30 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra bonus if next item exactly fills the bin afterwards.
            if post_residual - next_item_size == 0 {
                score -= 15.0;
            }
        } else if next_item_size > post_residual && post_residual < next_item_size.min(40) {
            // Dead space unusable for the lookahead item: mild penalty scaled by gap.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer filling bins as much as possible.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // Penalize opening a new bin when good open bins exist, unless stream is early
    // and many items remain (then spreading load can pay off).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: anchor at capacity minus item size.
        score = 100.0 - item_size as f64;
        // Late in the stream, opening new bins is wasteful.
        score += 25.0 * progress;
        // Many open bins with slack: avoid adding more bins.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 12.0;
        }
        // Early stream with few bins: mild encouragement to open a fresh bin
        // to preserve flexibility for large future items.
        if progress < 0.2 && open_bins_count < 3 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual
    // means this bin is already tight; using it preserves loose bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Slight preference to fill bins with larger items (less leftover relative waste).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (quadratic penalty on leftover). Late: reward tight fills more.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    let coupling = post * post / cap * (1.0 - progress) * 0.5 + post * progress * 0.3;
    score += coupling;

    // Reward near-perfect fits increasingly with progress.
    score -= tightness * tightness * cap * (0.2 + 0.8 * progress);

    // Lookahead: if the next item fits into post_residual, reward; else penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a bin unless existing bins are badly fragmented.
    let fragmentation = (mean_residual - post) / cap;
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) - 8.0 * fragmentation.max(0.0);
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills and near-exact fills are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 10 {
        score -= 20.0;
    }

    // Modulo classes: residuals that are multiples of common small item sizes
    // (or near-multiples) remain reusable; odd dead space is penalized.
    let reusable = |r: u32| -> bool {
        r == 0 || (10..=80).any(|k| r % k == 0 && r >= k) || r >= 10
    };
    if !reusable(pr) {
        score += 25.0; // dead space in the 1..9 band
    }

    // Integer-division thresholds: post_residual bucketed by how many
    // average-size items (say ~30) could still land there.
    let slots = pr / 30;
    score += match slots {
        0 => 30.0,   // nothing meaningful fits afterwards
        1 => 0.0,
        2 => -8.0,
        _ => -14.0,
    };

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 25.0;
            } else if slack <= 15 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; mildly penalize leaving large gap
            score += (pr.min(next_item_size)) as f64 * 0.1;
        }
    }

    // Tightness coupling: reward using most of the bin's residual.
    let fill_frac = item_size as f64 / bin_residual as f64;
    if fill_frac > 0.85 {
        score -= 18.0;
    } else if fill_frac > 0.6 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: usually bad unless current fit is terrible
    // and many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.4 * cap;
        let crowding = open_bins_count as f64 > 4.0 + 20.0 * progress;
        if poor_fit && crowding && fitting_bins_count > 0 {
            score -= 10.0; // allow a fresh bin occasionally
        } else {
            score += 70.0; // default: prefer existing bins
        }
    }

    // Mild penalty for spreading across many open bins with fat residuals.
    if mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "dead zone" (1..10)
    // are nearly unusable for future items -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward bins whose residual becomes exactly matchable by the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0; // bin stays usable for the next item
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item cannot reuse this gap
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins; few open bins -> new bins are cheap.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it only wins when
        // existing fits are poor.
        score += 30.0 + 25.0 * bin_pressure;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            score -= 20.0;
        }
    } else {
        // Filling an existing bin is mildly rewarded as bins accumulate.
        score -= 8.0 * bin_pressure;
    }

    // Prefer bins below mean residual (they are the "fuller" ones) to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this is a perfect chained placement — reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // If next item fits into the post residual, mild reward proportional
    // to how well it fills (prefer tighter chains).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (next_item_size as f64 / post_residual as f64) * 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover space: penalize dead space,
        // especially when the leftover is small (unusable fragment).
        score += (post_residual as f64).powf(1.5) * 0.05;
    }

    // Relative to mean residual: prefer bins that end up tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else. Penalize the empty-bin candidate
    // by default, but relax the penalty if post_residual would be small
    // (a fresh bin that will be packed efficiently).
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 120.0; // fresh bin supports the lookahead well
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 140.0; // near-perfect fresh fit
        }
    }

    // Small unusable fragments are dead space: penalize non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Stream progression: later in the stream, favor consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    // Prefer denser packing among many open bins: bins below mean residual
    // get a slight extra edge.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias: strong reward for tight fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powf(3.0);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect chaining bonus: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Penalize dead space that cannot host the next item.
            let dead = post_residual as f64;
            score += 0.15 * dead;
        }
    } else {
        // Last item: pure tightness matters, chain bonus irrelevant.
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 20.0;
        // More open bins => higher cost of yet another bin.
        new_bin_penalty += 1.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper (no future to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty -= 10.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_penalty += 6.0 * (fitting_bins_count.min(5) as f64);
        // If mean residual is large, open bins have room; avoid a new bin.
        new_bin_penalty += 0.2 * mean_residual;
        score += new_bin_penalty;
    } else {
        // Mild penalty for using bins far below mean residual (keeps balance).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.05 * dev;
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit)
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate loose fits (future items can fill gaps);
    // late in stream, strongly punish residual dead space.
    let tightness = (post / cap).powi(2);
    let progress_weight = 0.5 + 3.0 * progress * progress;
    score += progress_weight * tightness * cap * 0.5;

    // Smooth fill-ratio reward: bins that are well utilized get a bonus.
    let fill = (bin_residual as f64) / cap;
    score -= 2.0 * fill * fill * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 0 {
        // mild scarcity reward as fitting bins become rare
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - diff / cap).max(0.0);
        // penalize leaving a residual that no plausible item (>=1) can use well
        if post > 0.0 && post < 10.0 {
            score += 6.0 * (10.0 - post) / 10.0;
        }
    }

    // Mean-residual coupling: avoid making this bin an outlier of waste
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin, more so early and
    // when many open bins exist; relax penalty if item is large.
    if bin_residual == bin_capacity {
        let size_penalty = (cap - item) / cap; // small items -> larger penalty
        score += 12.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64 + 10.0 * size_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25 encode
    // "re-usability classes" of leftover space for typical item sizes.
    let pr = post_residual;
    let residue10 = (pr % 10) as f64;
    let residue25 = (pr % 25) as f64;

    // Penalize awkward leftovers: large residues that are not near a
    // "harmonic" multiple of 10 or 25 are dead space.
    score += residue10 * 0.8;
    score += (25.0 - residue25).abs().min(residue25) * 0.5;

    // Reward post_residuals that are exact harmonic divisions of capacity.
    if pr > 0 && (bin_capacity % pr == 0) {
        score -= 6.0;
    }
    if pr == 0 {
        score -= 15.0; // perfect fill is best
    }

    // Integer-division thresholds: leftover in [next_item_size, next+10)
    // is prime for the lookahead item.
    if next_item_size > 0 && pr >= next_item_size {
        let fit_class = pr / next_item_size.max(1); // how many next items fit
        score -= (fit_class as f64).min(3.0) * 4.0;
        // exact fit for the lookahead
        if pr == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // leftover too small for lookahead: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer tight fits overall (small relative slack).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 5.0;

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * progress * 0.5;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, discounted when current bins are full-ish
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 100.0 - crowding * 40.0 - progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    let dead_zone = 15.0; // gaps below this are nearly unusable (min item size ~1..100, but small gaps waste capacity)
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    }

    // Reward residual that exactly (or nearly) accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 - (slack as f64).min(12.0) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: mild penalty proportional to how badly it misses.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Fit quality: tightness of fit relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: discourage scattering across many bins; encourage
    // filling existing bins when there are already many open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.4 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (keeps bin pool homogeneous),
    // unless this is a last-chance bin.
    if fitting_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base mild penalty so we prefer decent existing fits...
        score += 20.0;
        // ...but if no other bin fits (fitting_bins_count==1 refers to this
        // candidate only) or all fits are terrible, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        if post_residual as f64 >= item_size as f64 * 0.2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pair: item + next item fills bin completely
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            // extra bonus if the remainder after the next item is tiny (<=10)
            let rem2 = post_residual as f64 - next_item_size as f64;
            if rem2 <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(40.0);
        }
    }

    // Penalize bins whose residual deviates badly from the mean (avoid fragmenting the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        // new-bin candidate: base score = full capacity; make it attractive only
        // when no good fit exists (handled implicitly since post_residual = C - item
        // is large for a fresh bin, and bonuses above reduce open-bin scores).
        score += 10.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if many bins are open, discourage spreading
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference for tighter fits overall (small post_residual relative to capacity).
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    } else if post_residual < 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves further residual: mild reward scaled by fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space: penalize proportional to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 10.0 * (overflow / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize new-bin candidate unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual of open bins.
        let waste_pressure = mean_residual * (open_bins_count as f64).sqrt();
        score += 40.0 + waste_pressure * 0.5;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Mild penalty for leaving residuals that few future item sizes can use
    // (odd-sized leftovers between 51 and 69 are hard to fill).
    if post_residual >= 51 && post_residual <= 69 {
        score += 12.0;
    }

    // Slight preference for bins already below mean residual (balancing).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized residual
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with cubic discount
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Stream-progress coupling: later in the stream, demand tighter fits
    score += 25.0 * norm_pr * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 * (next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportional to wasted space
        score += 10.0 * norm_pr;
    }

    // Coupling with mean residual: placing into a bin with residual far below mean
    // concentrates large residuals elsewhere (good); near-mean is neutral
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev;

    // New-bin candidate: penalize opening new bins when open bins exist, softened by progress
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on friendly
    // residue classes (multiples of 10 / 5) are more reusable -> reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else if pr < 10 {
        score += 6.0; // dead space below min item size
    }

    // Integer-division threshold coupling: small post_residual classes.
    let cls = pr / 20; // 0..=4 harmonic class
    score += cls as f64 * 2.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here; keep residual flexible
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening
    // early when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Penalize waste relative to mean residual (fragmentation signal).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize "dead space": small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (near-zero post residual) but not exact fills that waste a perfect bin.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / (bin_capacity as f64 / 2.0)).max(0.0);
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Post residual too small for next item AND tiny: dead space penalty already applied,
        // add extra since next item cannot use it.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 8.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If no open bin leaves a reasonable gap, allow new bin more readily.
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Mild reward for using existing bins as open count grows.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins with residual close to mean (balanced packing) slightly.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead fit: next item leaves small leftover
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-slack / 15.0).exp();
    }

    // Penalize leaving dead space the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 * (next_item_size - post_residual) as f64 / 10.0;
    }

    // Reward tight fills relative to mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Slight preference for compact bins when many bins are open
    score += open_bins_count as f64 * 0.1;

    // Small late-stream tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, only chosen when no open bin scores better
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize wasted space after placement.
    // Tight fits are rewarded super-linearly.
    let post = post_residual as f64;
    score += 0.35 * (post * post) / bin_capacity as f64;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // especially snugly; penalize leaving a gap that neither fits anything well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - 0.08 * slack;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space the known next item cannot use.
        score += 0.10 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current fits are poor or the item fits the empty bin far better than
    // any existing residual pattern suggests.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // A fresh bin perfectly accommodates future large items; cheaper early
        // in the stream when plenty of stream remains.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large and would need a fresh bin anyway, opening now
        // for the current item is reasonable.
        if next_item_size > 50 {
            score -= 8.0;
        }
        // If many bins are open with large mean residual, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
    }

    // Crowd control: when many bins are open, prefer consolidation into
    // emptier bins to enable future closures; when few are open, be pickier.
    if open_bins_count > 3 {
        score -= 0.5 * (bin_residual as f64 - mean_residual).clamp(-20.0, 20.0) * 0.1;
    }

    // Prefer filling bins that are already relatively full (small residual
    // relative to mean) to drive bins toward closure.
    let mean_r = mean_residual.max(1.0);
    if (bin_residual as f64) < mean_r {
        score -= 0.5 * (mean_r - bin_residual as f64).min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fill = 1.0 - pr / cap;
    let next_fit = if next_item_size > 0 && (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
    let mut score = pr * (1.0 + 0.5 * progress * fill);
    score -= 12.0 * next_fit * (1.0 - progress);
    score += 0.05 * (pr - mean_residual).powi(2) / cap;
    score += if fitting_bins_count == 1 { -8.0 } else { 0.0 };
    score += 0.02 * pr * pr / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: exponential decay on post_residual.
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: classify post_residual into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor() as i32; // eighth-capacity classes
    // Reward classes that are most reusable by future items (small residuals of 0..=12,
    // or large residuals >= half capacity are both "useful" classes).
    let class_usefulness: f64 = match class {
        0 => 40.0,          // residual < 12.5% : near-full, essentially closed
        1 => 10.0,          // 12.5%..25% : awkward dead zone
        2 => 0.0,           // 25%..37.5%
        3 => -5.0,
        4 => -15.0,         // ~half full bin, very reusable
        5 => -10.0,
        6 => -5.0,
        7 => -20.0,         // mostly empty, flexible
        _ => 0.0,
    };
    score -= class_usefulness;

    // Integer-division threshold on post_residual: does next item fit?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Chain potential: reward leaving space exactly usable by lookahead.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-slack / 10.0).exp();
        // Harmonic pairing bonus when item+next sums to a capacity fraction.
        let sum = item_size + next_item_size;
        if cap * 0.5 - sum as f64 <= 1.0 && sum as f64 <= cap * 0.5 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; mild penalty for stranding this bin's remainder.
        score += (post_residual as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only when no existing bin fits well or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins generally; less when many bins open (fragmentation) or early.
        let new_bin_penalty = 55.0 - 20.0 * progress - (open_bins_count as f64).min(10.0);
        // If item is large and would leave a big residual, new bin is fine.
        let large_item_bonus = if item_size as f64 / cap > 0.5 { 15.0 } else { 0.0 };
        score += new_bin_penalty - large_item_bonus;
        // If this is the only option (no open bins), make it attractive.
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual wastes flexibility;
    // prefer bins whose residual is above mean (they are more "loaded").
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev.max(0.0);

    // Mild preference for fewer open bins (bin consolidation).
    score += 0.5 * open_bins_count as f64;

    // Small jitter-free tiebreak: exact-fill classes via modulo arithmetic.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1, but practically < ~10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to the bin.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 50.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // If this bin cannot also fit the lookahead item, slight penalty
    // (dead end for next step), unless post_residual is unusable anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // If the next item fits exactly in the resulting residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it moderately attractive only when existing
    // bins would leave bad dead space or when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0;
        score -= 0.3 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            // an existing bin is the only fit: discourage new bin there
            score += 20.0;
        }
    }

    // Mild late-stream preference for closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chaining of two items).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this one: mildly reward tightness.
        score -= 8.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    // Penalize residuals far below the mean residual (creating unusable slivers).
    score += 0.5 * (mean_residual - post_residual as f64).abs() * if (post_residual as f64) < mean_residual { 1.0 } else { 0.3 };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // (fewer future placement constraints) or few bins are open.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        score -= large_item_bonus + (open_bins_count as f64 * 2.0);
        // Penalize opening a new bin early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Small global tightening: prefer bins whose post residual is a multiple of
    // common small item sizes (5/10), improving future fit odds.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit leaves negligible dead space
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0;
            if slack_after_next < 10 {
                score -= 8.0; // chained perfect fit
            }
        } else {
            // Penalize leaving residual that no plausible next item can use
            // (dead space smaller than the minimum plausible item).
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and
        // how many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 70.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is small, open bins are crowded:
        // opening a new bin is more justified.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // If the next item is large, having a fresh bin helps.
        if next_item_size >= 60 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // scaled by global mean residual context.
        let gap = (bin_residual - item_size) as f64;
        score += (gap / bin_capacity as f64) * (mean_residual / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth penalty for awkward residual sizes (mid-range dead space)
    let awkward = norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 12.0 * awkward * (0.5 + progress);

    // Reward tight fits: small post residual
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: prefer residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (pr - nxt) / cap;
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to prefer filling existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 3.0;
    } else {
        score += 4.0 * (1.0 - progress);
    }

    // Coupling with mean residual: penalize bins far from the fleet mean
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low modulo classes
    // (e.g. <=10) are "dead space" classes; penalize them quadratically.
    let dead = if post_residual <= 10 { 1.0 } else { 0.0 };
    score += dead * 25.0;

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Integer-division threshold: post_residual divisible by small integers
    // (harmonic slots of size 10 / 20 / 25) are reusable by future items.
    let harmonic = (post_residual % 10 == 0 && post_residual > 0)
        || (post_residual % 20 == 0 && post_residual > 0)
        || (post_residual % 25 == 0 && post_residual > 0);
    if harmonic {
        score -= 12.0;
    } else if post_residual > 0 {
        // odd/unusual residuals get mild penalty scaled by class
        score += (post_residual % 10) as f64 * 0.6;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot ever fit in post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: only bin that fits the item -> strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: opening a new bin should be discouraged unless
    // this is a poor fit everywhere; base new-bin score is post_residual (=capacity),
    // add mild penalty so existing decent fits win, but relax late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        // opening a bin when many are already open is wasteful
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Fraction-of-capacity harmonic class of item size.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0; // large items deserve tighter packing
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum plausible item (1..=100 range,
    // typical small items ~10) are effectively wasted. Penalize gaps below a usable threshold.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap smaller than the next item is likely dead space.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer tight packing
    // into already-open bins vs. opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bias = 15.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    }

    // Prefer bins with residual close to the item (tight fit) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward scaled by remaining slack
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0);
        }
    }

    // Compare against mean residual: bins with unusually small residual are precious
    if (bin_residual as f64) < mean_residual {
        score -= 8.0; // tight bin, use it
    } else {
        score += 4.0; // roomy bin, save it
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< 10 cannot hold any item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or stream is late
        score += 10.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next_item_size is wasted unless nothing else can use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space relative to lookahead item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        } else {
            // the next item can still fit here: strong reward
            score -= 6.0;
            // extra reward if next item fills this bin nicely
            let gap = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // last item: minimize post residual aggressively
        score *= 1.2;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: be pickier about sloppy fits
        score += 0.15 * post_residual as f64;
    }

    // Time horizon: early in the stream, prefer spreading load / keeping
    // flexibility; late in the stream, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 0.5 + 1.5 * t;
    score *= consolidation;

    // Compare against global mean residual: bins far above mean residual
    // (i.e., relatively empty) are less urgent to fill; bins below mean
    // (nearly full) are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize opening new bins when several open bins exist, unless
    // this IS the new-bin candidate (residual == capacity).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost grows with open bins and stream progress
        score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - t);
        // but reward if no existing bin fits well
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    } else if open_bins_count < 2 {
        score -= 2.0; // few bins: keep using them
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: minimize wasted space, non-linearly penalized
    let mut score = post * (1.0 + 0.35 * norm_post * norm_post);

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Stream-progress polynomial coupling: late stream amplifies waste penalty
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += post * prog_poly * 0.8;

    // Penalize residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt && post > 0.0 {
            score += (nxt - post) * (1.5 + 2.0 * prog_poly);
        }
        // Reward leaving room exactly for the next item
        if post >= nxt && post < nxt * 1.4 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // penalty decays as mean residual across bins grows
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.6 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild coupling with crowding of open bins
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // small-residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let class = match pr {
        0 => 0usize,               // perfect fit
        _ if pr % 10 == 0 => 1,    // decile residue: highly reusable
        _ if pr % 5 == 0 => 2,     // half-decile: reusable
        _ => 3,                    // awkward residue
    };
    score -= match class {
        0 => 40.0,
        1 => 18.0,
        2 => 8.0,
        _ => 0.0,
    };

    // Penalize large dead space in awkward class: leftover that no typical item
    // (size 1..=100) can plausibly pair with is wasted capacity.
    if class == 3 && pr > 50 {
        score += (pr as f64 - 50.0) * 0.9;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual
    // (harmonic match), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size > pr {
            // next item won't fit here; mild penalty scaled by excess
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should only win when the item is
    // large relative to capacity or current open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        score += 55.0
            - item_size as f64 * 0.35
            - fragmentation * 0.4
            - open_bins_count as f64 * 0.5
            - progress * 5.0;
    }

    // Tie-break toward tighter existing bins via mean residual pressure.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small harmonic jitter on residual quartile to break ties deterministically.
    let quartile = (pr * 4) / bin_capacity.max(1);
    score += quartile as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are useless.
    let dead_zone: f64 = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post_residual as f64 + 1.0) * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap just barely too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bin pressure.
        score += 30.0 + pressure * 15.0;
    } else {
        score -= pressure * 5.0;
    }

    // Mild attraction to bins below mean residual (loose bins get filled).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize post_residual that is small but unusable: dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // bonus if it fills nearly exactly
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: late in the stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 15.0 + 30.0 * progress;
        // but if nothing fits well, opening can win: reduce penalty when
        // all existing residuals are too tight relative to item
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // early stream: new bins are cheap to open
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer bins with residual below mean
    // (consolidate waste into fewer bins)
    if bin_residual as f64 > mean_residual {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Many open bins: encourage closing them out (fill small-residual bins)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for larger items going into emptier bins
    if item_size > 60 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer small post_residual (tight fits). Late: relax slightly,
    // since residual space is more valuable when bins are scarce.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 0.5;
    score += 60.0 * poly;

    // Tight fit reward: quadratic in filled fraction of the bin.
    let filled = (bin_residual - post_residual) as f64 / cap;
    score -= 25.0 * filled * filled;

    // Lookahead: penalize if the residual cannot host the next item,
    // reward if it can exactly or nearly host it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (1.0 - pr / nx);
        } else {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack).powi(3);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: mildly penalize unless open bins are crowded or
    // the fit would be very poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 * (1.0 - crowding) + 30.0 * norm_pr * norm_pr;
    }

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Reward residuals that land on "harmonic" grid points (multiples of 10/25),
    // since future items (1..100 unknown dist) more often fit compactly there.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        if r10 == 0 { score -= 12.0; }
        if r25 == 0 { score -= 18.0; }
        if r10 != 0 && r25 != 0 {
            // dead space penalty grows for small non-aligned residuals
            score += (10 - r10) as f64 * 1.5;
        }
    }

    // Integer-division thresholds: how many 10-sized units fit after placement.
    let units = post_residual / 10;
    score -= units as f64 * 4.0;

    // Lookahead coupling: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: penalize leftover mismatch
            let nxt_post = post_residual - next_item_size;
            score += (nxt_post % 10) as f64 * 0.8;
        } else {
            // next item won't fit here: mild penalty if residual becomes wasted
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (small post_residual) or existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bias = 20.0
            + (item_size as f64 / bin_capacity as f64) * 40.0
            + mean_residual * 0.35
            + progress * 10.0;
        score += new_bin_bias;
    } else {
        // Prefer tighter bins: residual fraction penalty.
        score += (bin_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Slight preference to keep bin count low when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 50.0;
    }

    // Penalize gaps that are too small to fit the smallest plausible next item,
    // scaled by whether the lookahead item could actually use the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * next_item_size as f64;
    }
    // Reward gaps that exactly (or nearly) accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // Prefer bins tighter than the average residual (good fits).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild bonus for filling larger fractions of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when existing bins would leave
    // severe dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual > 0 && post_residual < 10 { 120.0 } else { 0.0 };
        score += 80.0 + dead_space_penalty - (item_size as f64 * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus for lookahead (post_residual close to next_item_size)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // reward tight fits for the next item
        score -= 30.0 * (1.0 - slack / 40.0).max(0.0);
    }

    // Penalize post_residual slightly above next_item_size (dead space next round)
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score += 8.0;
    }

    // Penalize tiny unusable residuals (<10, minimum item size)
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Prefer fuller bins as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= (bin_capacity - bin_residual) as f64 * 0.15 * (0.5 + progress);

    // Discourage opening new bins when open bins exist and fit reasonably
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Favor exact-fit of current item (post_residual near zero)
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer filling bins tightly.
    let mut score = post * 1.0;

    // Strong reward for near-perfect fits (dead space penalty is convex).
    let waste_ratio = post / cap;
    score += waste_ratio * waste_ratio * 60.0;

    // Exact or near-exact closure bonus.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_fit_gap = post - nxt;
            if next_fit_gap == 0.0 {
                score -= 70.0;
            } else if next_fit_gap <= 10.0 {
                score -= 35.0;
            }
            // Pairing bonus scaled by how tight the pair is.
            score -= (10.0 - next_fit_gap.min(10.0)) * 1.5;
        } else {
            // Next item cannot use this residual: slight penalty for leaving stranded space.
            score += (nxt - post).min(30.0) * 0.4;
        }
    } else {
        // Last item: closing bins is free value.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Many open bins with slack: prefer reusing existing capacity over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= crowding * 0.5 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a mild handicap so it only wins
    // when all open bins are genuinely poor fits, but becomes more attractive
    // early in the stream when there is plenty of future demand.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 25.0;
        let poor_alternatives = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 15.0 - early_bonus - poor_alternatives;
    }

    // Prefer bins whose residual is close to the item (tight fit among candidates).
    let tightness = (residual - item) / cap;
    score += tightness * 10.0;

    // Slight preference for bins with residual below mean (consolidate slack).
    if residual < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic waste penalty on post residual, modulated by stream progress.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth coupling: later in the stream, penalize large residuals more (want tight packing).
    score += 40.0 * norm_post * norm_post * (progress * progress);

    // Reward near-perfect fits with a smooth sigmoid-like bonus.
    let fit_quality = 1.0 - norm_post;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Penalize opening a new bin when existing bins fit, with smooth dependence on progress.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 15.0 + 30.0 * (1.0 - progress);
        // But if no open bin fits well, opening becomes attractive: penalize more when many bins compete.
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap).powi(3);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to wasted potential.
        score += 4.0 * (next_item_size as f64 - post) / cap;
    }

    // Smooth open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += 1.5 * (open_bins_count as f64).powf(0.5) * norm_post;

    // Deviation of this bin's residual from mean residual: prefer bins below mean (tighter).
    score += 3.0 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes are highly reusable.
    let post = post_residual;
    if post > 0 {
        let mut harmonic_bonus = 0.0;
        for &s in &[10u32, 20, 25, 50] {
            if post % s == 0 {
                harmonic_bonus += 8.0;
            }
        }
        // Perfect-fit reward dominates everything.
        if post == 0 {
            score -= 1000.0;
        }
        // Small unusable dead space penalty (non-harmonic crumbs).
        if post < 10 {
            score += 30.0;
        }
        score -= harmonic_bonus;
    } else {
        score -= 1000.0; // exact fill
    }

    // Integer-division threshold on next item: does this bin also fit the lookahead?
    if next_item_size > 0 && next_item_size <= post {
        score -= 15.0; // chain-fit reward
    } else if next_item_size > 0 && post > 0 && next_item_size > post {
        score += 5.0; // lookahead won't fit here
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; discounted when many bins are already open
        // and mean residual is high (fragmentation) — consolidation is hopeless.
        let mut new_bin_cost = 60.0;
        if mean_residual > 30.0 {
            new_bin_cost -= 10.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0; // no alternative
        }
        score += new_bin_cost;
    }

    // Tight fit reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Slight preference to keep mean residual balanced (avoid extreme skew).
    score += 0.1 * (post as f64 - mean_residual).abs();

    // Mild stream-progression pressure: late in stream, favor closing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // Tiny gap: nearly dead space unless next item is tiny.
            let rescue = if next_item_size > 0 && (next_item_size as f64) <= gap { 0.0 } else { 40.0 };
            score += rescue * (1.0 + (10.0 - gap) / 10.0);
        } else if gap <= 20.0 {
            let rescue = if next_item_size > 0 && (next_item_size as f64) <= gap { 0.0 } else { 12.0 };
            score += rescue;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (3.0 + 4.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize by default; only attractive when item is large
        // and existing residuals are small (poor fits everywhere).
        score += 6.0 + pressure;
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 25.0 {
            score -= 10.0; // existing bins have plenty of room; discourage new bin
        } else if mean_gap < 0.0 {
            score += 5.0; // item barely fits anywhere; new bin slightly less bad
        }
    }

    // Lookahead: if next item would fit the post-residual exactly, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place item so that the next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect lookahead match (next item almost fits the post-residual).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving large unusable dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Reward keeping bins tight relative to mean residual (good consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when plenty of fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 80.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // forced to open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            new_bin_penalty -= 20.0; // next item is large; fresh bin useful
        }
        score += new_bin_penalty * (0.5 + 0.5 * (1.0 - progress));
        // Small tie-break so a fresh bin with exact future fit is still attractive.
        if next_item_size > 0 && next_item_size == bin_residual {
            score -= 900.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that can't host typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: prefer bins whose post_residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 {
        score -= 5.0 * (mean_residual / (bin_capacity as f64)) * ((open_bins_count as f64).ln().max(1.0));
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = tightness < 0.5 && fitting_bins_count > 0;
        score += if poor_fit { 10.0 } else { 60.0 };
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count <= 1 {
            score -= 45.0; // pairing current + next items in a fresh bin
        }
    }

    // Mild penalty for very full bins early on (keep flexibility)
    if progress < 0.3 && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let nxt = next_item_size as f64;

    // Base: waste after placement, weighted by a smooth progress polynomial
    let progress_w = 0.6 + 0.8 * t * t - 0.3 * t * t * t;
    let mut score = pr * progress_w;

    // Non-linear coupling: quadratic dead-space penalty when residual is tiny
    score += 12.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 20.0 * (-pr / 15.0).exp();

    // Lookahead coupling: smooth interaction between post_residual and next item
    if nxt > 0.0 {
        let gap = (nxt - pr).abs();
        let usable = nxt / cap;
        score -= 6.0 * usable * (1.0 - (gap / cap).min(1.0));
        // Penalize if next item cannot fit in post residual (dead end)
        score += 4.0 * (nxt - pr).max(0.0) / cap * (1.0 + t);
    }

    // Scarcity bonus: last fitting bin should be favored
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    } else {
        score += 1.5 * (fit - 1.0).sqrt();
    }

    // Mean residual context: penalize bins far below mean residual (poorly filled)
    score += 0.5 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * t + 0.4 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it only when post_residual would be tiny elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when the item leaves
        // a "harmonic" residual that is likely reusable.
        let mut new_score = 55.0;
        // Harmonic classes of post_residual modulo capacity quarters.
        let q = post_residual % 25;
        if q == 0 { new_score -= 30.0; }        // perfect quarter alignment
        else if post_residual % 10 == 0 { new_score -= 18.0; }
        else if post_residual % 5 == 0 { new_score -= 10.0; }
        // Lookahead: if next item fits into the fresh residual, reward opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            new_score -= 22.0;
        }
        // Late in the stream, opening bins is cheap (few future items to fill).
        let progress = step_index as f64 / total_items as f64;
        new_score -= 20.0 * progress;
        // Many open bins -> consolidation preferred, penalize opening more.
        new_score += (open_bins_count as f64).min(10.0) * 1.5;
        return new_score;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Perfect fills: residual 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic classes of post_residual: multiples of 10 are highly reusable.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
        // Dead-space penalty: residuals in (0,10) are nearly unusable
        // since min item size is 1, but small leftovers waste capacity.
        if post_residual < 5 {
            score += 8.0;
        }
        // Integer-division threshold: post_residual in [25,50) is a
        // "half-bin" sweet spot; below 25 it's a cramped quarter bin.
        if post_residual < 25 {
            score += 6.0;
        } else if post_residual >= 50 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead pairing: if next item exactly fills the post_residual,
    // this placement sets up a perfect completion.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves further residue: mild reward scaled by fit ratio.
        let ratio = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * ratio;
    } else if next_item_size > post_residual {
        // Next item won't fit here regardless; penalize leaving a mid-range residual.
        if post_residual > 0 && post_residual < 20 {
            score += 10.0;
        }
    }

    // Coupling with mean residual: placing into a bin below mean residual
    // (i.e., a fuller bin) balances the pool of open bins.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Progress-dependent aggression: late in the stream, prioritize closing
    // bins out (perfect fits) over preserving flexibility.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residual close to item size (tight packing).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Penalize small-but-usable gaps less harshly, still discourage fragmentation.
    if post_residual > 0 && post_residual < 30 {
        score += 120.0 * (30.0 - post_residual as f64) / 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 80.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 8.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive if it enables a good future fit
    // (next item larger than current) or when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if next_item_size > item_size && next_item_size <= bin_capacity {
            score -= 60.0 + 40.0 * (next_item_size as f64 - item_size as f64);
        } else {
            score += 90.0 + 50.0 * progress;
        }
        if fragmentation < 20.0 {
            score += 40.0;
        }
    }

    // Lookahead: if the residual left behind exactly fits the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Penalize leaving a gap that is useless for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 60.0;
    }

    // Mild mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fills (dead space elimination)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits into post_residual, this is a great match
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tight chains: next item nearly fills leftover space
        score -= 80.0 - slack.min(80.0);
        if slack <= 5.0 {
            score -= 40.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item would NOT fit here after placement: penalize wasted residual
        let gap = (post_residual as f64).min(next_item_size as f64);
        score += 0.5 * gap;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize new-bin candidate unless item is large and no open bin is tight
    if bin_residual == bin_capacity {
        // new bin: base score = capacity - item = post_residual (already high)
        // discourage opening when many bins could fit and mean residual is large
        score += 25.0 + 0.4 * mean_residual;
        if fitting_bins_count > 2 {
            score += 30.0;
        }
        // allow opening for large items that would leave bad fragmentation
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Early stream: be more conservative with bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 10.0 * (0.2 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear squashing).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight * tight);

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            score -= (15.0 - (chain as f64).min(15.0)) * 0.8;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fit is loose
    // and there are many open bins (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let loose = (item_size as f64) / (bin_capacity as f64);
        score += 20.0 + 25.0 * (1.0 - loose) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if mean_residual < (item_size as f64) * 1.2 {
            score += 15.0; // open bins are tight, better to open fresh
        }
    }

    // Mild preference for filling bins with larger residuals among open bins.
    if bin_residual != bin_capacity {
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream consolidation: fewer open bins desired as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln1p();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Quadratic dead-space penalty, modulated by stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic coupling between post-residual and progress
    score += 8.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * tightness;

    // Interact with mean residual: prefer bins near/below mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Lookahead: penalize if next item could fit in post-residual (keep usable space)
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: smooth penalty that relaxes late in the stream
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score += 30.0 * openness * openness + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild consolidation pressure with open bins count
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo common capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Perfect-fit bonus: post_residual exactly divisible by common item classes
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Reward residuals that are "harmonic" — divisible by small integers (likely future fits)
        let mut harmonic_bonus = 0.0;
        for m in [10i64, 20, 25, 50] {
            if pr % m == 0 {
                harmonic_bonus += 15.0;
            }
        }
        score -= harmonic_bonus;

        // Penalize dead space in awkward residue classes (prime-ish / odd small residuals)
        if pr < 10 && pr > 0 {
            score += 40.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if nis > 0 && nis == pr {
        score -= 500.0;
    } else if nis > 0 && nis <= pr {
        // next item fits: reward proportionally to tightness
        score -= 50.0 * (nis as f64 / pr as f64);
    } else if nis > 0 {
        // next item won't fit here: penalize leaving large unusable space
        score += 0.3 * (nis as f64);
    }

    // Capacity fraction thresholds: bins below 1/4 residual are nearly closed
    if (post_residual as f64) < cap * 0.25 {
        score += 20.0;
    } else if (post_residual as f64) > cap * 0.75 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bins are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < cap * 0.15 {
            score -= 60.0; // open bins nearly full, fresh bin is good
        } else {
            score += 30.0 + fragmentation * 0.5;
        }
        // Early stream: opening bins cheaply is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter existing bins vs mean
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    // A residual gap is "dead" if it's smaller than the smallest plausible item.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on post_residual: squared term punishes mid-size wasted gaps.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    score += bin_pressure * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item.
        score += (next_item_size as f64 - pr).min(20.0) * 0.8;
    }

    // Mean residual coupling: placing into a bin with residual far below mean
    // (a tight bin) is good; spreading across loose bins wastes capacity.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: baseline attractiveness so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only if existing fits are bad (high score so far),
        // more willing later in the stream.
        score += 25.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual is valuable; penalize unusable dead space (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward proportional to tightness.
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 30.0; // big items may justify a fresh bin slightly more
        }
    }

    // Early in the stream, be more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading items thin.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
