pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core: quadratic penalty on wasted space after placement.
    let mut score = post * post / cap;

    // Smooth non-linear coupling with stream progress: waste becomes
    // increasingly expensive as the stream matures (fewer future chances
    // to compensate), weighted by a saturating polynomial.
    let prog_w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += post * (0.5 + 1.5 * prog_w);

    // Reward tight fits (small post_residual) more than linearly:
    // exponential-ish reward via normalized fill ratio.
    let fill = 1.0 - post / cap;
    score -= fill * fill * 10.0;

    // Lookahead: if the next item fits the post-residual, reward this bin;
    // if it nearly fits, mild penalty for leaving awkward space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual far from the mean (fragmentation avoidance),
    // scaled smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * (1.0 + open_bins_count as f64).ln().max(1.0) * 3.0;

    // New-bin candidate: keep it attractive only when item is large relative
    // to capacity or all fits are poor; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let big_item = item / cap;
        let poor_fit = (post / cap).min(1.0);
        score += 12.0 - 10.0 * big_item * big_item + 8.0 * poor_fit * poor_fit;
        // Early in the stream, opening bins is cheaper.
        score -= 6.0 * (1.0 - prog_w);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (multiples of small sizes) should be favored.
    let cap = bin_capacity as f64;
    let fill = (bin_residual - post_residual) as f64 / cap; // 0..1 fill fraction

    // Reward high fill fraction (tight packing).
    score -= 40.0 * fill * fill;

    // Modulo-class analysis of post_residual: leftover that is itself a
    // plausible future item size (or near one) is valuable dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 6.0; }        // round leftovers reusable
        if pr % 5 == 0 { class_bonus += 2.0; }         // semi-round
        if pr >= 10 && pr <= 80 { class_bonus += 4.0; } // leftover in item range
        if pr < 10 { class_bonus -= 8.0; }              // tiny dead space
        score -= class_bonus;
    } else {
        score -= 15.0; // perfect closure is excellent
    }

    // Lookahead coupling: does post_residual fit the next item exactly-ish?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap); // leaves room for next item
            if pr == next_item_size { score -= 8.0; } // perfect two-item closure
        } else {
            // next item won't fit here; penalize mildly unless this is last-chance
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins would create big waste.
    if bin_residual == bin_capacity {
        // Opening fresh is good if mean residual is already fragmented/low.
        let frag = mean_residual / cap;
        score -= 20.0 * (1.0 - frag);
        if post_residual as f64 > 0.6 * cap { score -= 10.0; }
    }

    // Stream progression: pack tighter as the stream nears its end.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * t * fill;

    // Mild penalty for proliferating bins when many are already open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Integer-division threshold: penalize leftovers that can't hold even
    // the smallest plausible item class (>= 10 in classic regime, else small).
    let min_item = if item_size >= 10 { 10 } else { 1 };
    if pr > 0 && pr < min_item {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest conceivable follow-up item
    // (>= 1 per interface) is pure waste; scale the penalty non-linearly.
    let dead = if post_residual == 0 {
        0.0 // perfect fit: ideal
    } else if post_residual < 10 {
        40.0 // tiny sliver, essentially unusable
    } else if post_residual < 25 {
        12.0
    } else if post_residual < 50 {
        4.0
    } else {
        0.0
    };
    score += dead;

    // Reward near-perfect fits super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 && post_residual >= 10 {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new ones implicitly by favoring fills).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early.
        score += 18.0 + pressure;
    } else {
        // Slight reward for using existing bins, stronger later in the stream.
        score -= 3.0 + 2.0 * progress;
    }

    // Last-chance bin: strongly prefer it to avoid opening an extra bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // next item still fits here: mild reward proportional to fill ratio
        let r = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * r;
    }

    // Prefer bins tighter than the mean residual (closer to full).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this placement sets up the next item perfectly.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits, reward proportionally to tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward residuals
            // that are too small to be useful for typical items.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 15.0 * (10.0 - waste);
            } else if waste > 50.0 {
                score -= 5.0; // large residual still reusable
            }
        }
    } else {
        // Last item: just minimize waste directly.
        score -= 10.0;
    }

    // Reward tight fits relative to current bin residual (best-fit flavor).
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * (1.0 - tightness);

    // Compare post_residual against mean residual across open bins:
    // favor bins that end closer to the mean (keeps bin portfolio balanced).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * deviation;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Late in the stream, consolidate: penalize opening/spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 40.0 * progress;
        // But if no open bin offers a good lookahead chain, new bin is fine.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty per number of open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear discount.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tight * tight;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead can still fit here: strong reward.
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 0.08 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 3.0 * tight;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 3.0 * t;
    }

    // Global pressure: many open bins with small mean residual -> prefer consolidation.
    let pressure = mean_residual / bin_capacity as f64;
    score += 2.0 * pressure * (open_bins_count as f64).sqrt();

    // Early stream: be more open to spreading; late stream: pack tightly.
    score += (1.0 - t) * 1.5;

    // New empty bin candidate: neutral-ish baseline; only wins when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0 * tight + 4.0;
        if fitting_bins_count == 0 {
            score = -100.0; // nothing fits elsewhere, must open new bin
        } else {
            // Penalize new bin more when good alternatives exist.
            score += 5.0 + 3.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, with non-linear emphasis.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness.powi(3) * (0.5 + progress);

    // Penalty for leaving dead space that the next item likely cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let waste = (nxt - post) / cap;
            score += 8.0 * waste * (1.0 + progress);
        } else {
            // Bonus if next item fits exactly well into the post residual.
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 4.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 + post / cap);
    }

    // Mild penalty when this bin's residual deviates strongly from mean residual
    // (encourage balanced residual distribution, smooth quadratic coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for using existing bins over opening new ones,
    // weakening late in the stream when consolidation matters more.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    } else {
        score -= 1.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Classes of 10 (classic bin-packing granularity): residual mod 10 == 0
    // means the leftover can host whole items of size 10, 20, ... exactly.
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -12.0,           // perfect harmonic slot
        1..=3 => 6.0,         // tiny unusable dead space
        4..=6 => 2.0,         // moderate dead space
        _ => 0.0,             // 7..9: can still round down to a usable slot
    };
    score += class_penalty;

    // Integer-division thresholds: leftover large enough for common item classes
    // (1..=100 range) gets rewarded proportionally to how many classes fit.
    let slots = (post_residual / 10) as f64;
    score -= 3.0 * slots;

    // Penalize exact-fill waste: post_residual very small but nonzero is dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves another leftover; mild reward scaled by fit tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 * tightness;
        } else {
            // next item cannot use this bin's leftover: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin's score should reflect the
    // opportunity cost. Prefer reusing bins with good fits; only prefer a new
    // bin when the leftover after placement is large and flexible.
    if bin_residual == bin_capacity {
        // neutral base for new bin: slightly worse than a perfect fit into an
        // existing bin, but better than leaving large awkward leftovers.
        score += 15.0;
        // reward opening a new bin early in the stream when many items remain
        // (more chances to fill it perfectly later).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // Mild penalty for spreading across too many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (i.e., we're consuming a scarce small leftover), reward it.
    let residual_diff = mean_residual - post_residual as f64;
    score -= 0.2 * residual_diff.clamp(-50.0, 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host any plausible
    // future item are heavily penalized (treated as wasted capacity).
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score += 1000.0; // exact fit, ideal
    }

    // Dead-space threshold: gap that cannot fit even the smallest item
    // (post_residual in 1..min_useful) is pure waste.
    if post_residual >= 1 && post_residual < 10 {
        score += 500.0 * (10 - post_residual) as f64;
    }

    // Progressive dead-space penalty: gap too small for the lookahead item
    // but still nominally usable -> quadratic waste penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 8.0 * waste * waste / 100.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // item fits well; encourage using existing bins as bins accumulate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e. mean residual is low or this bin would leave a bad gap).
    if bin_residual == bin_capacity {
        let gap_bad = post_residual > 0 && post_residual < 10;
        if gap_bad || mean_residual < item_size as f64 * 0.5 {
            score -= 150.0;
        } else {
            score += 250.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Mild alignment bonus: residual after placement close to a common
    // future item size is more reusable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64) * 0.3;
        // Exact match is gold.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Post residual too small for next item: dead-space penalty grows as residual shrinks.
        let dead = post_residual as f64;
        score += (20.0 - dead).max(0.0) * 1.5;
    }

    // Penalize very small residuals (unusable slivers), scaled by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.15 {
        score += 25.0 * (0.15 - frac) / 0.15;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer bins below mean residual (pack fuller bins first, keep big gaps for big items).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Mild early-stream bias toward using open bins; late stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive if item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness * tightness;

    // Lookahead: reward residuals that can still host the next item,
    // penalize residuals that strand just below the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0;
        } else if post_residual > 0 {
            // dead space: residual too small for the known next item
            score += 8.0 * (1.0 - (post_residual as f64) / nxt);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: usually costly, but attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // Penalize opening a bin normally; discount if open bins are crowded
        // (mean residual small) or few bins fit the item.
        let mut open_penalty = 12.0 + 10.0 * progress;
        open_penalty -= 4.0 * (fitting_bins_count.min(4) as f64);
        open_penalty -= (avg_fit_gap / 10.0).min(8.0);
        score += open_penalty.max(-5.0);
    }

    // Slight preference for bins below average fullness (balance residuals),
    // keeping some bins available for larger future items.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for leaving large-but-unusable gaps relative to item range.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0; // tiny slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: polynomial in normalized post-residual modulated by progress
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr + 0.6 * progress * (1.0 - progress) * norm_pr * norm_pr);

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= (cap - pr) * 0.05 * (1.0 + progress);

    // Penalize near-mean residuals slightly (prefer diversifying residual sizes)
    let dev = (pr - mean_residual).abs() / cap;
    score -= 2.0 * dev * (1.0 - progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let tight = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 4.0 * tight;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage early, allow when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 12.0 - 10.0 * fragmentation * (1.0 + progress);
    }

    // Slight preference for bins with larger residual among many open bins
    score -= 0.5 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Leftovers that are "perfect divisors" of
    // typical item sizes are reusable; odd leftovers are dead space.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize leftovers in "awkward" harmonic classes (prime-ish remainders).
    let awkward = match post_residual {
        0 => -3.0,                 // perfect fit: heavily reward
        r if r % 10 == 0 => -2.0,  // decadal leftover: very reusable
        r if r % 5 == 0 => -1.0,   // half-decadal: reusable
        r if r % 2 == 0 => 0.5,    // even: mildly ok
        _ => 1.5,                  // odd leftover: likely dead space
    };
    score += awkward * (1.0 + frac);

    // Reward tight fits: post_residual small relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 8.0 * (-tightness).exp();

    // Lookahead coupling: if the next item exactly fills post_residual,
    // this placement chains perfectly.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 12.0;
    }
    // If next item fits into post_residual, mildly reward leaving that room.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 2.0 * (post_residual - next_item_size) as f64 / 100.0;
    }
    // If next item cannot use the leftover, penalize large leftovers.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0 * frac;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin for a mediocre reason.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when open bins are bad.
        score += 15.0;
        // Reward opening a new bin when mean residual across open bins is
        // too fragmented to accept future items harmonically.
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac < 0.25 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If the item leaves a harmonic-friendly residual in a fresh bin.
        let fresh_left = bin_capacity - item_size;
        if fresh_left % 10 == 0 {
            score -= 4.0;
        }
    }

    // Prefer filling bins with low residual relative to the fleet mean:
    // consolidating fragmented space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Many open bins: encourage closing them out (use fullest-fitting bins).
    score += 0.3 * open_bins_count as f64 * frac;

    // Integer-division threshold on post_residual classes.
    let class = post_residual / 10; // decadal class
    score -= (10 - class.min(10)) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for the smallest
    // plausible item) are heavily penalized with a superlinear term.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    } else {
        // Mild superlinear penalty on any leftover to prefer tight fits.
        score += 0.35 * (post_residual as f64).powf(1.6);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Near-exact fit: leftover that could still host a small item is fine.
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0; // awkward sliver, but not dead: keep pressure on
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, be pickier about bad fits.
    let obp = open_bins_count as f64;
    score += 0.8 * obp * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: if this bin's post_residual deviates far
    // below the mean (i.e., we're consuming lots of slack), reward it.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let delta = mean_residual - pr;
        score -= 0.25 * delta;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight bonus for keeping residual
        // small so this bin is "finished" cleanly.
        score -= 2.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline; only choose it when open bins
    // have terrible fits. Penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * obp;
        // But if the item is large and would leave a big residual anyway,
        // a fresh bin is relatively more attractive.
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Post residual can still hold the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable remainder.
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Deviation from mean residual: prefer bins tighter than average (best-fit flavor).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Slight preference for filling bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    // Penalize near-empty bins being consumed for tiny items (waste of a fresh bin),
    // unless it's the only fitting bin.
    if bin_residual == bin_capacity && item_size < bin_capacity / 2 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_ratio * waste_ratio;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += 10.0 * crowding * waste_ratio;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 8.0;
        } else if (post_residual as u64) < next_item_size as u64
            && (post_residual as u64) + (item_size as u64) >= next_item_size as u64
        {
            // dead space relative to next item: mild penalty
            score += 3.0;
        }
    }

    // Early stream: be picky (penalize loose fits) since many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * waste_ratio;

    // Global residual context: if mean residual is high, prefer bins below mean
    // (consolidate into emptier bins to create fewer large holes).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin; discount when item is large or few fitting bins.
        score += 20.0 - 14.0 * large_item - 4.0 * (fitting_bins_count.min(3) as f64);
        // Late in stream, opening a fresh bin is less costly.
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0), favor tight fills (low post_residual) strongly.
    // Later (progress ~ 1), tolerate residual slack in already-open bins to
    // avoid opening new bins unnecessarily.
    let tightness = pr / cap;
    let poly = tightness * tightness * (1.0 - progress) + tightness * progress;
    score += 8.0 * poly * cap / 100.0;

    // Reward bins whose residual matches the next item's size (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap) * (0.5 + 0.5 * (1.0 - progress));
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item, scaled
        // smoothly by how close the residual is to being useful.
        let closeness = 1.0 - (next_item_size - post_residual) as f64 / cap;
        score += 4.0 * closeness.max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless post_residual is tiny (dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (post_residual as f64 / cap + 0.5);
    }

    // New-bin candidate: penalize opening a new bin smoothly, more so early
    // in the stream when consolidation matters most.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (keeps residual spread even).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-class logic on post_residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are "usable" classes; odd fragments are dead space.
    let usable = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 25 == 0) as f64 * 5.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= usable;

    // Penalize residuals in awkward bands (tiny slivers 1..=5 are dead space).
    if post_residual > 0 && post_residual <= 5 {
        score += 30.0;
    }
    if post_residual > 5 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: residual large enough to hold a mid-size item
    // (>= 30) is valuable; reward it proportionally.
    if post_residual >= 30 {
        score -= 6.0 + (post_residual as f64) * 0.05;
    }

    // Lookahead coupling: does post_residual accommodate the next item exactly?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 200.0; // chain of perfect fits
        } else if gap <= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space for lookahead.
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base mild penalty; reduced when open bins are crowded.
        let crowded = mean_residual / cap; // average fill pressure
        score += 45.0 - crowded * 60.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If many bins fit the item, opening a new bin is wasteful.
        score += (fitting_bins_count as f64) * 10.0;
    }

    // Prefer bins tighter than the mean (better packing direction).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small exploration term tied to harmonic class of item size.
    score -= ((item_size % 20 == 0) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host a mid/large future item.
    if post_residual >= 30 {
        score -= 8.0;
    } else if post_residual >= 10 {
        score -= 3.0;
    }

    // Last-chance bin: strong pressure to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let ob_pressure = open_bins_count as f64 * 1.5;
    if bin_residual < bin_capacity {
        score -= ob_pressure * 0.5;
    } else {
        // New-bin candidate: penalize opening unless item is large and current
        // bins are crowded (poor fits elsewhere).
        score += 30.0 + ob_pressure;
        if item_size >= 50 && mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
    }

    // Lookahead coupling: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Late in stream: consolidate, avoid leaving many partially filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Mild tie-break toward tightest fit relative to mean residual.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of that follow-up fit.
            let follow_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * follow_tightness;
            if post_residual == next_item_size {
                score -= 200.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            let awkwardness = (next_item_size - post_residual) as f64;
            score += 0.3 * awkwardness;
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 120.0 - 100.0 * desperation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin preserves room for a bigger follow-up item
        }
    }

    // Slight bias toward consolidating fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins with small leftover space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap too small for the next item.
        score += 0.35 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Prefer fuller bins relative to global mean residual.
    score += 0.30 * (mean_residual - bin_residual as f64);

    // Slight penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if the item is large, a fresh bin is reasonable.
        score -= 0.2 * item_size as f64;
    }

    // Mild bonus for bins that would be nearly closed out.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * (1.0 - t) * 4.0; // smooth bump peaking mid-stream
    score += (pr_norm * pr_norm * pr_norm) * cap * poly * 2.0;

    // Reward tight fits with smooth decay term
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * tightness * cap * 0.6 * (1.0 + t);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += gap * gap * cap * 3.0 * (1.0 - t * 0.5);
        // Reward leaving exactly room for next item
        let match_term = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= match_term * match_term * 8.0 * (1.0 - t * 0.3);
    }

    // Last-chance bonus: smooth sigmoid-like weighting on fitting scarcity
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 + t);
    } else {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= scarcity * 4.0;
    }

    // Mild preference for bins below mean residual early, above late
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (1.0 - 2.0 * t) * 5.0;

    // Slight pull toward opening new bins when many bins already open
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + t) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // "harmonic" divisors are more reusable, so reward them.
    let pr = post_residual;
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        if r == 0 { return 40.0; } // perfect fit, huge reward
        if r % 10 == 0 { b += 6.0; }
        if r % 20 == 0 { b += 4.0; }
        if r % 25 == 0 { b += 4.0; }
        if r % 50 == 0 { b += 6.0; }
        b
    };
    score -= harmonic_bonus(pr);

    // Lookahead: if next item fits exactly or well into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0; // chained perfect fit
        } else {
            score -= 12.0 - 0.05 * slack;
        }
    } else if next_item_size > pr {
        // next item cannot use this residual; penalize proportionally
        score += 0.04 * ((next_item_size - pr) as f64);
    }

    // Integer-division thresholds on post_residual: classify dead-space quality
    let cls = pr / 10; // residual decile class
    match cls {
        0 => score += 8.0,          // 1..9: tiny dead space, nearly wasted
        1 | 2 => score -= 2.0,      // 10..29: moderately reusable
        3 | 4 => score -= 4.0,      // 30..49: good residual
        5 | 6 => score -= 1.0,      // 50..69: ok but half-empty bin
        _ => score += 3.0,          // 70+: very empty bin, wasteful placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin is a bad fit class.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bins more readily early on / when many bins already open
        score += 14.0 + 0.5 * pressure * (1.0 - progress) - 10.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean.
    score += 0.08 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64).abs();

    // Prefer tight fills relative to item size
    score += 0.05 * (item_size as f64) * (pr as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum plausible item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small-but-usable gaps are still risky; moderate penalty.
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Coupling with mean residual: prefer bins that are tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor using existing ones over
    // opening a new bin (new-bin candidate has bin_residual == bin_capacity,
    // so it gets penalized through its large post_residual already, but add
    // explicit pressure proportional to open bins for existing bins).
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed, penalize.
        score += 10.0;
    }

    // Early in the stream, be slightly more willing to open bins (better packing
    // later); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly or nearly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if next_item_size == post_residual {
            // Perfect 2-step match: huge reward.
            score -= 1000.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportional to tightness of the 2-step fill.
            let slack = post - next;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin's post-residual: penalize dead space,
            // especially when the leftover is small (unusable).
            let waste = next - post;
            score += 50.0 + 2.0 * waste;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild penalty for proliferation of open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.3;

    // New-bin candidate: neutral-ish base so it wins only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 120.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
        // extra reward if next item nearly fills remaining space too
        let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - chain_tight) * 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize creating dead space the next item can't use
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Global state: many open bins -> discourage spreading, prefer consolidation
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += bin_pressure * 3.0;

    // Mean residual coupling: if this bin is much tighter than average, prefer it
    let avg = mean_residual.max(1.0);
    let ratio = post_residual as f64 / avg;
    score += (ratio - 1.0) * 20.0;

    // Time horizon: early in stream, prefer keeping flexibility (larger post_residual ok);
    // late in stream, be greedy about fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 40.0 * (1.0 - tightness);
    score += (1.0 - progress) * 15.0 * tightness;

    // New-bin candidate: opening a fresh bin should only win if no open bin fits well
    if bin_residual == bin_capacity && item_size > 0 {
        // base penalty so open bins are preferred unless they score badly
        score += 90.0;
        // but if the item is large relative to capacity and mean residual is small,
        // a new bin is attractive
        let load_frac = item_size as f64 / bin_capacity as f64;
        score -= load_frac * 60.0 + (1.0 - avg / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Small residual waste penalty (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Primary: prefer tight fits, with non-linear (quadratic/cubic) shaping
    let mut score = norm_post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth coupling of tightness with stream progress: late in the stream,
    // tight fits matter even more (less room to recover waste)
    score *= 1.0 + 0.8 * progress * (1.0 - norm_post);

    // Penalize large dead space relative to mean residual (fragmentation)
    let frag = (post - mean_residual) / cap;
    score += 0.5 * frag * frag.abs();

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        } else {
            // post residual too small for next item: penalize proportionally
            score += 1.0 * (nxt - post) / cap;
        }
    } else {
        // last item: pure tightness
        score -= 2.0 * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += 0.02 * open_bins_count as f64 * norm_post;

    // Slight bias against opening a new bin when progress is low and fits exist
    if bin_residual == bin_capacity {
        score += 0.6 + 0.8 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual: classify dead space into harmonic bands.
    let band = post_residual / 10; // 0..=10, coarse harmonic class
    match band {
        0 => score -= 40.0,                      // near-perfect fit
        1 => score -= 25.0,                      // excellent
        2 => score -= 12.0,                      // good
        3 => score -= 5.0,                       // decent
        4 => score += 2.0,                       // mediocre
        5 => score += 6.0,                       // half-empty bin
        6 => score += 10.0,
        7 => score += 13.0,
        8 => score += 15.0,
        9 => score += 17.0,
        _ => score += 20.0,                      // nearly empty bin being used
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are more likely to be exactly filled by future items -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // fractional coupling: how much of the next item the residual absorbs
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 * frac;
            // penalty if next item leaves yet another awkward band-4/5 residual
            let npr = post_residual - next_item_size;
            if npr > 0 && npr < 10 { score -= 8.0; }
        } else {
            // next item won't fit here; residual becomes dead space until stream ends
            score += 4.0 + 0.06 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // best-fit pressure among multiple candidates: tighten score toward best fit
        score -= 3.0 * (bin_residual as f64 / cap);
    }

    // New-bin candidate handling: neutral baseline, slightly worse than a good fit,
    // better than dumping into a nearly-empty bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 18.0;
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // if many open bins already have large mean residual, prefer reusing them
        score += 0.05 * mean_residual;
        if open_bins_count > 6 { score += 4.0; }
    }

    // Mild global pressure to keep mean residual low (compact packing).
    score += 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=10 minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large leftover space only mildly; small gaps matter more
    // (non-linear coupling: quadratic in small range, linear above).
    if post_residual > 0 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.5 + progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit (post_residual of existing bins too small
    // or fragmented relative to mean residual).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with open bins count.
        score += 20.0 + pressure * 0.5;
        // If current item would leave a bad gap in existing bins, opening
        // fresh is more attractive: reduce the penalty.
        if post_residual >= 10 {
            score -= 15.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // Existing bin: reward if its residual tracks the mean (balanced use),
        // penalize bins far above mean residual (hoarding space).
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += dev * 0.15;
        }
        // Lookahead synergy: if next item fits the post_residual exactly-ish,
        // reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Residual can still host the next item: mild reward, better when close.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-gap / 20.0).exp();
        } else {
            // Next item won't fit: penalize dead space, worse for very small leftovers.
            let dead = (next_item_size - post_residual) as f64;
            score += 10.0 * (1.0 - (-dead / 30.0).exp());
            if post_residual < 10 {
                score += 15.0; // unusable sliver (items >= 10)
            }
        }
    } else {
        // Last item: minimize leftover directly (already base term).
        score += 5.0;
    }

    // Relative to mean residual: prefer bins whose post-residual stays near/below mean
    // (balance across bins), unless it's a perfect match.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (post_residual of a fresh bin = capacity - item_size, large).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; discount when many items remain or few bins open.
        score += 55.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0; // fresh bin has room for the lookahead too
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter fills overall.
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (100.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward;
    // if it would leave this bin wasted, penalize mildly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // Prefer fuller bins when many bins are open (reduce bin count pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 30.0 * progress;
        // But if mean residual across open bins is large, opening new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    } else {
        score -= progress * 6.0;
    }

    // Mild penalty for bins far from mean residual (prefer homogeneous packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize wasted residual, with non-linear polynomial shaping
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * (1.0 - pr_norm));

    // Smooth stream-progress coupling: waste penalized more later in the stream
    score *= 1.0 + 1.5 * t * t;

    // Interaction: post_residual vs mean residual — avoid outlier small residuals
    score += 0.3 * (pr_norm - mean_residual / cap) * (pr_norm - mean_residual / cap);

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like bump)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let fit = (-gap * gap / 900.0).exp();
        score -= 3.0 * fit;
    }

    // Last-chance bin: strong bonus to use it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild pressure against spreading across too many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Prefer tight fits: reward item filling most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // in quarter-capacity bands (modular arithmetic on capacity fractions).
    let quarter = bin_capacity / 4;
    let band = (post_residual / quarter) % 4; // 0..3 residual class
    // Smaller bands (tighter fit) are better: reward low bands.
    score -= (3 - band) as f64 * 4.0;

    // Exact modulo harmony: residual that is a multiple of small item classes
    // (e.g. 10s) is more likely reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Penalize residuals in the "dead zone": too small for typical items
    // (residual < 10 is pure waste), heavily penalize.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: good, especially if leftover stays small
            let chain_left = post_residual - next_item_size;
            score -= 8.0 + (chain_left as f64).min(20.0) * -0.3;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is (integer division threshold on gap).
            let gap = next_item_size - post_residual;
            score += (gap / 10) as f64 * 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that keeps it
    // competitive only when open bins would create large waste.
    if bin_residual == bin_capacity {
        // Opening a new bin costs roughly one bin; make it attractive only
        // if it preserves large residual structure for future items.
        score = cap * 0.9 - item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big-first heuristic: prefer fresh bin for large items
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Slight preference for keeping the number of open bins low early on.
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Mean residual coupling: if this bin is far below the mean residual
    // (already tight), it's a good target.
    if (mean_residual - post_residual as f64) > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum item size (1) is impossible, but small
    // residuals relative to typical item sizes create dead space. Penalize
    // post_residual in the "dead zone" [1, 20] super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - pr) * (21.0 - pr) * 0.8; // quadratic dead-space penalty
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when the stream is far along.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual cannot host the next item: mild dead-space penalty.
        score += 6.0;
    }

    // New-bin candidate: make it moderately unattractive by default; it should
    // win only when all open bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Slight preference for bins tighter than the mean (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching against next_item_size ---
    let next = next_item_size as f64;
    if next > 0.0 {
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect match: next item exactly fills this bin afterwards.
            score -= 45.0 + 25.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item still fits afterwards: mildly good.
            let slack = post_residual as f64 - next;
            score -= 12.0 - 0.15 * slack.min(60.0);
        } else {
            // Next item won't fit: penalize proportionally to the wasted gap.
            let gap = next - post_residual as f64;
            score += 8.0 + 0.35 * gap;
        }
    }

    // --- Relative-to-mean residual coupling ---
    // Prefer bins whose post_residual sits near the mean residual (keeps
    // the bin population homogeneous and reusable).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.12 * dev;

    // --- Dead-space penalty: tiny unusable remainders ---
    if pr > 0.0 && pr < 10.0 {
        score += 18.0 * (10.0 - pr) / 10.0;
    }

    // --- Last-chance bin: strongly favor using it before opening new ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // --- New-bin candidate: make it attractive only when no open bin
    //     offers a decent fit, and early in the stream. ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Early stream: opening bins is cheap; late: reuse matters.
        score -= 22.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        score -= 0.05 * next;
        // If many bins are already open, discourage opening more.
        score += 1.5 * open_bins_count as f64;
        // If this is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // --- Tight-fit bonus for current item itself ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize leaving awkward small residuals that most items (>=1..100) can't use well.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // dead space penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
        // If next item exactly fills residual, extra reward.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, less attractive late.
        score -= 25.0 * (1.0 - progress);
        score += 15.0 * progress;
        // Don't open a new bin if a decent fit exists and mean residual is large.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 0 {
            score += 30.0;
        }
    } else {
        score += 8.0 * (1.0 - progress); // mild penalty on using open bins early
    }

    // Global residual dispersion: if mean residual is small, cherish remaining space.
    score += 0.15 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // early on, keep flexibility (penalize tiny residuals mildly);
    // later, drive residuals to zero aggressively (super-linear penalty).
    let pr = post_residual as f64;
    let poly = pr * pr / (bin_capacity as f64 * bin_capacity as f64);
    score += 40.0 * poly * (0.5 + progress);
    score -= 12.0 * (1.0 - progress) * (pr / bin_capacity as f64).sqrt();

    // Reward tight fits non-linearly
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening a new bin, more so as bins accumulate / stream progresses
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * (open_bins_count as f64).ln() + 25.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slightly penalize leaving large unusable gaps
        score += 5.0 * (pr / bin_capacity as f64);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets (integer division thresholds)
    let item_class = item_size / 13;             // classes 0..6
    let next_class = next_item_size / 13;

    // Reward near-perfect fills: post_residual in {0} gets strong discount
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible item can fill:
    // items are >= 1, but small residuals < some threshold are wasteful if
    // next item cannot use them. Harmonic coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item can't fit here either way; residual becomes dead weight
            score += post_residual as f64 * 0.5;
        } else {
            // next item could chain into this bin: reward
            score -= (post_residual - next_item_size) as f64 * 0.3 + 10.0;
        }
    }

    // Class-affinity bonus: same harmonic class items pack well together
    if next_item_size > 0 && item_class == next_class {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer opening a
    // new bin when current bin fit is sloppy and bin is still fairly full.
    if bin_residual == bin_capacity {
        // fresh bin: score = residual (capacity). Encourage opening a new bin
        // only when the best existing fit is bad (high post_residual) —
        // achieved implicitly since open-bin scores rise with post_residual.
        // Slight penalty to avoid bin explosion early on.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += open_bins_count as f64 * 2.0 * (1.0 - progress);
    } else {
        // Prefer filling bins that are already relatively empty (large fill fraction)
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= fill_frac * 40.0;

        // Penalize picking a bin whose residual deviates from mean (fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    // Modulo-based micro-tuning on post_residual: residuals congruent to
    // common item sizes are more likely reusable.
    let reusable = [1u32, 2, 4, 5, 8, 10, 20, 25, 40, 50];
    let mut hit = false;
    for r in reusable.iter() {
        if post_residual >= *r && post_residual % r == 0 && post_residual <= 50 {
            hit = true;
            break;
        }
    }
    if hit {
        score -= 8.0;
    }

    // Mild penalty per open bin to consolidate load
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness;

    // Dead-space penalty: unusable small gaps (post_residual too small for typical items).
    if post > 0.0 && post < 10.0 {
        score += 30.0 * (10.0 - post) / 10.0; // worst when gap is tiny but nonzero
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (nxt - post) / nxt.max(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure, but allow when existing fits are poor.
        score += 15.0 + pressure;
    } else {
        // Favor bins whose residual is below mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight preference for filling larger-residual bins when few bins are open.
    if open_bins_count <= 2 {
        score -= 2.0 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly-ish: strong reward.
            if diff <= 5.0 {
                score -= 300.0 - diff * 10.0;
            } else {
                score -= 80.0 / (1.0 + diff);
            }
        } else {
            // Next item won't fit: penalize leaving a tempting-but-useless gap.
            score += 30.0 + diff * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: prefer it only when open bins would leave bad waste.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + pr - progress * 10.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 5.0 {
            score -= 60.0; // fresh bin fits next item well
        }
    }

    // Slight preference for fuller bins among open bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is too small to be useful.
    let useful_threshold = 10.0;
    if (post_residual as f64) < useful_threshold {
        score -= 30.0 * (useful_threshold - post_residual as f64);
    } else {
        score += 0.5 * (post_residual as f64 - useful_threshold);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit here; slight penalty if post_residual is wasted anyway.
            score += 5.0;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals large (flexibility);
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.3 * post_residual as f64;
    score -= progress * 10.0;

    // Many open bins: prefer filling existing ones over spreading out.
    if bin_residual < bin_capacity {
        score -= 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize unless current bins are too full on average.
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 25.0;
        } else {
            score += 20.0 + mean_residual * 0.2;
        }
    }

    // Relative fit quality: fraction of bin used by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of residual.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr) - 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth coupling of residual with stream progress: early on tolerate slack, late demand tightness.
    score += 30.0 * norm_pr * progress * (1.0 - progress);

    // Penalize large residuals when many bins are open (fragmentation pressure), smoothly.
    score += norm_pr * norm_pr * (open_bins_count as f64).ln_1p() * 8.0;

    // Reward bins whose residual is close to mean residual (balance), smooth term.
    let balance = (pr - mean_residual) / cap;
    score += 10.0 * balance * balance;

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it fall in?
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Dead-space penalty: residuals below quarter capacity are hard to fill.
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 3.0;
    }

    // Reward residuals that can still host a "large class" item (> half capacity).
    if post_residual >= half {
        score -= 12.0;
    } else if post_residual >= third {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < quarter {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += (next_item_size.min(post_residual) as f64).min(8.0);
    }

    // Modulo-harmonic bonus: residuals that are nice multiples pack well.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (tighter, more committed bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, encourage opening bins that keep large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        let poor_fit = post_residual < quarter && next_item_size > post_residual;
        if poor_fit {
            score -= 5.0;
        } else {
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + next_item_size as f64 * 0.25;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But allow new bin if existing residuals are large (poor fits elsewhere).
        if mean_residual > item_size as f64 * 2.5 {
            score -= 20.0;
        }
    } else {
        // Mild preference for tighter existing bins.
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
        score -= fitting_bins_count as f64 * 2.0;
    }

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward bins that become (near) full after placement.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is an ideal two-item chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a gap; penalize by gap size.
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover: penalize proportionally
            // to how unusable the dead space is.
            score += 0.2 * post_residual as f64;
        }
    }

    // Relative to mean residual: bins with less residual than average are
    // "tighter" — prefer filling them (keeps many usable bins open).
    if mean_residual > 0.0 {
        score += 0.4 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a fresh bin only attractive when the
    // item is large relative to residual capacity (poor fit elsewhere) or
    // few bins are open. Otherwise penalize slightly so existing bins win.
    if bin_residual == bin_capacity {
        score -= 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Fresh bin can host both current and next item nicely.
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate
    // into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving awkward small gaps that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // Perfect chaining: next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: with many open bins, discourage spreading; favor consolidation.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global slack: if mean residual is high, prefer reusing bins with low residual.
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be conservative (avoid opening new bins
    // that will remain nearly empty); early, allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: a fresh bin scores its full empty capacity;
    // penalize opening new bins unless the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 18.0 * progress + 10.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { 6.0 } else { 0.0 };
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += new_bin_penalty - large_item_bonus - desperation;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Small jitter-free deterministic tiebreak via step progression.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping.
    let mut score = post;

    // Non-linear waste penalty: dead space below the smallest possible item is unusable.
    let dead = (post - 1.0).max(0.0) / cap;
    score += 40.0 * dead * dead;

    // Perfect-fit reward, scaled by stream progress (tight packing matters more later).
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Interaction: post_residual relative to mean residual across open bins.
    let mr = mean_residual.max(1.0);
    let rel = post / mr;
    score += 6.0 * (rel - 1.0) * (rel - 1.0) - 4.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Smooth penalty for spreading across many open bins (encourages consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * progress;

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let gap = (post - nd).abs();
        if gap < 1.0 {
            score -= 20.0;
        } else {
            score += 5.0 * (gap / cap) * (gap / cap);
        }
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are very full.
    if bin_residual == bin_capacity {
        score = 45.0 - 20.0 * progress + (mean_residual / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 0..7 harmonic band
    let residue_mod = post_residual % 10;

    // Reward tight fits: post_residual in low harmonic band.
    if post_residual <= 5 {
        score -= 60.0;
    } else if class <= 1.0 {
        score -= 25.0;
    } else if class <= 3.0 {
        score -= 10.0;
    }

    // Penalize dead space that no plausible item (1..100) can fill well:
    // leftover that is not a multiple of a common item size wastes space.
    if post_residual > 0 && residue_mod != 0 {
        score += residue_mod as f64 * 0.8;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; leftover becomes dead until a small item arrives
            score += pr * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        // Opening a new bin is good for large items that leave a clean residual,
        // bad when many open bins exist that could absorb the item.
        score -= 30.0 + 20.0 * tightness;
        if open_bins_count > 0 && fitting_bins_count > 2 {
            score += 25.0;
        }
        // Prefer new bin early in stream (room to grow), penalize late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Favor filling already-open bins: mild bonus proportional to how full they are.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 12.0 * fill;
    }

    // Mean-residual coupling: if this bin's residual is far above mean, deprioritize
    // (keep balanced residuals across bins for future flexibility).
    let dev = pr - mean_residual;
    score += dev * 0.05;

    // Harmonic integer-division threshold: post_residual in [50,100) is a "half bin"
    // — acceptable; above that penalize progressively.
    if post_residual >= 50 {
        score += (post_residual - 50) as f64 * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately usable gap: mild penalty relative to base.
        score += 5.0;
    }

    // Large leftover space is fine (base score already favors it).

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; penalize leaving a gap that traps nothing.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * 4.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
        // Early in stream, new bins are cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mean residual alignment: prefer bins whose residual is below average (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 6.0 + slack_after_next as f64 * 0.05;
        if slack_after_next == 0 {
            score -= 12.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportional to mismatch.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.15;
    }

    // Penalize dead space relative to mean residual (fragmentation avoidance).
    score += (post_residual as f64 - mean_residual) * 0.08;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect pair.
    if bin_residual == bin_capacity {
        let perfect_pair = next_item_size > 0 && (bin_capacity - item_size) == next_item_size;
        if perfect_pair {
            score -= 4.0;
        } else {
            score += 10.0 + (open_bins_count as f64) * 0.3;
        }
    }

    // Small bonus for tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving small dead space the next item cannot use.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        if waste_frac < (next_item_size as f64 / bin_capacity as f64) {
            score += 6.0 * waste_frac;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: late in the stream, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Prefer bins with residuals below the mean residual (better balance of usage).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev;

    // Many open bins: encourage closing out low-residual bins.
    if open_bins_count > 3 {
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when the item is large or nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.6 || (fitting_bins_count == 0) {
            score -= 15.0 * fill;
        } else {
            // Penalize opening a new bin for small items when alternatives exist.
            score += 30.0 * (1.0 - fill);
        }
    }

    // Mild penalty for leaving awkward mid-range dead space (25..60) that few items fill.
    if post_residual >= 25 && post_residual <= 60 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, but with progress-dependent curvature.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: small post-residual is valuable (tight fit).
    let tightness = (-norm_post).exp();
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Penalize leaving residual that matches the next item poorly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = if post >= nxt { 1.0 - (gap / cap).powf(1.5) } else { (gap / cap).powf(1.5) - 1.0 };
        score -= 6.0 * fit_next;
    } else {
        score -= 4.0 * tightness; // last item: reward tight packing extra
    }

    // Last-chance bonus: this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0 * (1.0 - norm_post);
    }

    // Mildly discourage spreading across many open bins when mean residual is high.
    let open_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * open_pressure * (norm_post - mean_residual / cap).abs();

    // New-bin candidate: make empty bin less attractive unless residual would be tiny.
    if bin_residual == bin_capacity {
        score += 5.0 + 6.0 * progress - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "wasted" the leftover is
    // in terms of which item classes (small sizes) it can still host.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize dead space that cannot fit any plausible next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes dead after placement unless residual is tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (0.5 + 0.5 * progress);
        } else {
            // Reward bins whose residual still accommodates the lookahead item.
            score -= 2.0 * next_item_size as f64;
            // Extra reward if residual fits next item twice (harmonic doubling).
            if post_residual >= 2 * next_item_size {
                score -= 3.0;
            }
        }
    }

    // Modulo-class logic on post_residual relative to capacity quarters.
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    // Residuals just below a quarter-boundary are awkward (dead space).
    if class > 0 && class <= 5 {
        score += 4.0;
    }
    // Residuals near a quarter boundary from above are excellent.
    if class >= q - 5 {
        score -= 2.0;
    }

    // Integer-division thresholds: residual classes by fifths.
    let fifth = post_residual / (bin_capacity / 5).max(1);
    score -= match fifth {
        0 => 6.0, // nearly full bin: excellent
        1 => 3.0,
        2 => 0.0,
        3 => 1.5,
        _ => 3.0, // mostly empty: poor target
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large or no good fits.
    if bin_residual == bin_capacity {
        let large = item_size >= bin_capacity * 3 / 4;
        let poor_fits = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual_would_trap(item_size, bin_capacity, next_item_size));
        if large || poor_fits {
            score -= 10.0;
        } else {
            score += 12.0 + 8.0 * progress; // discourage wasting fresh bins
        }
    }

    // Slight preference for tighter bins overall (tightness coupling).
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Mean-residual coupling: when open bins are roomy on average, prefer
    // consolidating into the emptiest ones to reduce bin count pressure.
    score += 0.05 * mean_residual;

    score
}

fn post_residual_would_trap(item_size: u32, bin_capacity: u32, next_item_size: u32) -> bool {
    // If placing item leaves less than next_item_size and item is big,
    // a fresh bin may serve both items better.
    let r = bin_capacity - item_size;
    r < next_item_size && item_size > bin_capacity / 2
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into
    // the post residual (perfect chain match), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: this placement enables a perfect fill next step.
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how tight the chain is.
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64 * 0.5)).max(0.0);
        } else {
            // Next item cannot use the leftover space; penalize dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead.min(30.0);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual is good (bin well-utilized).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr).min(20.0);
    } else {
        score += 0.3 * (pr - mean_residual).min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good existing options exist,
    // unless current bins are all crowded (high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // New bin must beat existing fits: add a barrier scaled by crowding.
            score += 12.0 + 30.0 * (1.0 - crowding) * (1.0 - progress * 0.5);
        }
        // Slight bonus for new bin when existing bins are nearly full.
        score -= 8.0 * crowding;
    }

    // Mild preference for placing into bins with more open bins available
    // (keeps flexibility), scaled by stream progress.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Reward large item consumption of residual (tight fit bonus).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward if the next item can still fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward if next item would nearly fill the remainder.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 5.0;
            }
        } else {
            // Penalize leaving a remainder that is too small for the next item
            // but large enough to be wasted (dead space).
            if post_residual < 10 && post_residual > 0 {
                score += 4.0;
            }
        }
    }

    // New-bin candidate: penalize opening a new bin, more when good fits exist
    // and when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and would leave a big hole in any existing bin,
        // opening fresh may be fine: soften penalty.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global fragmentation pressure: if mean residual is high, prefer bins that
    // reduce the spread (place into bins with residual far from mean).
    let residual_f = bin_residual as f64;
    let dev = (residual_f - mean_residual).abs();
    score += 0.05 * dev;

    // Slight bias toward filling fuller bins (lower residual) earlier.
    score += 0.03 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Late-stream urgency: waste less as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Penalize dead space more aggressively as stream progresses
    let mut score = poly * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) with smooth falloff
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness;

    // Penalize residuals too small to fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += 2.0 * gap * (1.0 + progress);
        } else {
            let slack = (pr - ns) / cap;
            score -= 0.5 * slack * slack;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5 * (1.0 + progress);
    }

    // Mild penalty for opening a new bin when open bins could fit, scaled by progress
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // But favor new bin if mean residual of open bins is very small
        score -= 0.02 * mean_residual * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins close to mean for balance
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals in "nice" classes
    // (multiples of 10, or small enough to be near-full) are less wasteful.
    let class = post_residual % 10;
    score += (5 - class.min(5)) as f64 * 1.5; // prefer residuals landing on multiples of 10

    // Near-full bins are excellent: heavily reward tiny post_residual.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize dead space in the awkward 16..=40 band (hard to fill later).
    if post_residual > 15 && post_residual <= 40 {
        score += (40 - post_residual) as f64 * 0.35;
    }

    // Integer-division threshold: can the next item fit exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score += (gap % 10) as f64 * 0.8; // leftover after chaining, again by class
            if gap <= 5 { score -= 10.0; }
        } else {
            score += 6.0; // next item cannot use this bin's leftover at all
        }
    } else {
        // Last item: just minimize final residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 25.0; // large items deserve fresh bins
        } else {
            score += 18.0 + 20.0 * frac; // discourage wasting fresh bins on small items
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
    }

    // Coupling with mean residual: if open bins are already loose, tighten
    // preference for the tightest fits (exploit existing capacity).
    if mean_residual > 0.0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * mean_residual * 0.25;
    }

    // Modulo harmonic bonus: residual divisible by common item sizes (10, 20, 25).
    if post_residual % 25 == 0 || post_residual % 20 == 0 {
        score -= 6.0;
    }

    // Slight crowding penalty: prefer consolidating when many bins are open.
    if open_bins_count > 8 {
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized (non-linearly).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Penalize residuals in the awkward band (11..=20) more softly.
    if post_residual >= 10 && post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few bins are open, mild
    // tolerance for spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // If this bin is the last chance to fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no existing bin fits
    // well, or the item plus lookahead would leave a great residual.
    if bin_residual == bin_capacity {
        score += 12.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        // If the next item could exactly fill the leftover, opening is good.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: prefer leaving residuals that the next item can use.
    if next_item_size > 0 && bin_residual < bin_capacity {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 20.0;
        } else if gap > 0 && gap <= 5 {
            score -= 8.0;
        } else if gap < 0 && (-gap) <= 8 {
            score += 6.0; // just barely unusable for next item: bad
        }
    }

    // Late in the stream, tighten up: waste matters more as the end approaches.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (chains perfectly into the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = post_residual - next_item_size;
        if match_gap == 0 {
            score -= 800.0;
        } else {
            score -= 300.0 * (1.0 - match_gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space that blocks lookahead.
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual relative to mean residual: prefer leaving residuals
    // near the average (predictable usable space), penalize extremes.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin would
    // leave a large unusable residual and next item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0
            && (next_item_size == 0 || post_residual < next_item_size);
        score += if poor_fit { 0.0 } else { 500.0 };
        // Early stream: slightly discourage hoarding new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins over emptier ones when many bins are open.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Global pressure: when open bins are numerous, discourage opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 + 8.0 * pressure - 10.0 * progress;
    } else {
        // Mild bonus for consolidating into existing bins.
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * cap * 0.5;

    // Penalize mid-range dead space via cubic term
    score += 4.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.3;

    // Lookahead coupling: reward residual close to next item size
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (pr - next_item_size as f64) / cap;
        score -= (1.0 - gap) * (1.0 - gap) * 8.0 * (1.0 - progress);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Slight preference for bins below mean residual (consolidate fullness)
    score += (pr - mean_residual) * 0.15;

    // New-bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * tightness * (1.0 + progress);
    }

    // Mild penalty for many open bins to encourage reuse
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes on capacity fractions.
    let pr = post_residual;
    let cap_frac = (pr * 4) / bin_capacity; // 0..3 quarter-class of post residual

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus (exact fill).
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post-residual divisible by common item-size classes
    // (10/20/25/50) is more reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Dead space penalty for tiny unusable remainders (1..9).
        if pr < 10 {
            score += 15.0 * (10 - pr) as f64 / 10.0;
        }
    }

    // Quarter-class penalty: mid-range residuals (25..50) are least reusable.
    match cap_frac {
        0 => { if pr > 0 { score += 6.0; } }          // tiny leftover
        1 => { score -= 4.0; }                        // 25..50 reusable-ish
        2 => { score += 2.0; }                        // 50..75 mediocre
        _ => { score -= 6.0; }                        // large residual, flexible
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // chain completion
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // Prefer bins where next item leaves another harmonic residual.
            if slack % 10 == 0 { score -= 10.0; }
            score -= 8.0 * (1.0 - slack as f64 / pr.max(1) as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 5.0 * (next_item_size - pr).min(30) as f64 / 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 20.0 + 15.0 * progress;
        // If mean residual across open bins can't plausibly hold item, new bin is fine.
        if mean_residual < item_size as f64 {
            nb -= 30.0;
        }
        // Many open bins with slack: discourage new bin.
        nb += 1.5 * open_bins_count as f64;
        score += nb;
    } else {
        // Mild preference for fuller bins among open ones.
        score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any realistic future item are heavily penalized.
    let dead_threshold: f64 = 10.0; // gaps below this are almost unusable
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if (post_residual as f64) < 20.0 {
        // small awkward gaps still mildly penalized beyond their raw size
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual was tight before placement (good packing density).
    let pre_fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= pre_fill_ratio * 10.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize opening new ones.
    let open_pressure = open_bins_count as f64 * 1.2;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow only when current
        // bins would leave large dead space.
        score += 30.0 + open_pressure;
        if (post_residual as f64) < dead_threshold {
            // opening a fresh bin for a near-full fit is fine
            score -= 20.0;
        }
    } else {
        // Existing bin: discount when it's the only fitting option (last chance).
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else {
            score += fitting_bins_count as f64 * 0.5;
        }
        // If this bin would be left with a residual the next item can use,
        // reward it (lookahead k=2).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 3.0;
        }
        // Slight bonus for keeping mean residual spread consistent.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Early in the stream, be more tolerant of opening bins; later, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - pre_fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // exact match for the next item -> strong reward
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits: reward closeness, penalize wasted slack
            score -= 250.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space relative to mean residual
            score += 60.0 * diff / nxt.max(1.0);
        }
    }

    // Penalize leaving tiny unusable residual (< 10) that no item can use
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base = 400.0
            - 200.0 * (fitting_bins_count as f64).recip()
            + 0.3 * mean_residual;
        score += base;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * progress;
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 100.0;
        }
    }

    // Mild preference for filling already-open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills by subtracting a nonlinear bonus
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight * tight;

    // Lookahead: if the next item cannot fit into the post-residual,
    // this residual risks becoming dead space -> penalize proportionally.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = (post_residual as f64) / bin_capacity as f64;
            score += 6.0 + 10.0 * wasted;
        } else {
            // residual is reusable by next item: reward closeness of next item to residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer filling a bin as completely as possible
        score -= 20.0 * tight;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * (1.0 - t);
    }

    // New-bin candidate handling: opening a bin is expensive early / cheap late
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score += 10.0 + open_pressure * (1.0 - t) - 5.0 * t;
        // never open a new bin for a tiny item
        if item_size < bin_capacity / 4 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance remaining space)
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Penalize leaving awkward residuals (small but unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with a smooth non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, penalize large residuals more strongly
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Tightness reward: near-exact fits get a smooth cubic discount
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high
    let mean_norm = mean_residual / cap;
    score += 0.15 * open_bins_count as f64 * (1.0 - mean_norm);

    // Lookahead: reward leaving residual that can fit the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        let kernel = (-8.0 * diff * diff).exp();
        score -= 12.0 * kernel;
        // Penalize residuals just barely too small for the next item (dead space)
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild bonus for using open bins vs. new bin (new bin has bin_residual == bin_capacity,
    // so it gets full post_residual = cap, which the terms above already penalize)
    score += 0.05 * (bin_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strongest reward.
    // Class 1: tiny dead space (1..=10) -> nearly useless, penalize.
    // Class 2: medium (11..=30) -> usable for small items, mild reward.
    // Class 3: large (>30) -> flexible, reward.
    let pr = post_residual;
    let class: i32 = if pr == 0 { 0 } else if pr <= 10 { 1 } else if pr <= 30 { 2 } else { 3 };

    match class {
        0 => score -= 60.0,
        1 => score += 25.0, // dead space penalty
        2 => score -= 8.0,
        _ => score -= 15.0,
    }

    // Integer-division harmonic: does post_residual align with common item classes (10..80)?
    // Residuals divisible by 10 are "harmonious" with typical item sizes.
    if pr > 0 && pr % 10 == 0 {
        score -= 10.0;
    }
    // Residuals that are 1 mod 10 are worst-case dead space.
    if pr > 0 && pr % 10 == 1 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // chained perfect fit
        } else if next_item_size <= pr {
            score -= 12.0; // next item still fits
            // harmonic alignment of (pr - next_item_size)
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 20.0;
            } else if pr2 <= 10 {
                score += 10.0;
            }
        } else {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is less costly (fewer future uses).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item is large and current item small, deferring is cheaper.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // mean leaves other bins flexible; slightly reward that.
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * 0.5;

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Penalize creating many nearly-empty bins when many bins are open.
    if open_bins_count > 6 && pr > 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible future item
    // (sizes >= 1, but practically items in 1..=100) are heavily penalized.
    // Treat gaps <= 10 as "dead" — nothing useful fits them.
    if post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Semi-dead zone: only small items fit; penalize moderately.
        score += 25.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 30.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: residual likely becomes dead space.
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (3.0 + 4.0 * progress);

    // Last-chance bonus: if this is the ONLY bin that can fit the item, use it
    // rather than opening a new bin (avoids leaving an awkward item stranded).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 45.0;
        // If existing bins would leave dead space, opening a fresh bin is better.
        if post_residual <= 10 || (next_item_size > 0 && next_item_size > post_residual) {
            new_bin_score -= 50.0;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        new_bin_score += 20.0 * progress;
        // Many open bins with slack mean we should use them instead.
        new_bin_score += (open_bins_count as f64) * 2.5 + mean_residual * 0.3;
        score = score.max(new_bin_score);
    }

    // Alignment bonus: residual that matches common item sizes stays reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose post_residual tightly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact/near match with next item.
        score -= (bin_capacity as f64 - gap) * 0.5;
        // Extra bonus for a perfect chain: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item cannot fit here but fits elsewhere, mild penalty for large leftover.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: pure best-fit dominates; nothing extra needed beyond post_residual.
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual across open bins (waste normalization).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: only attractive when current fit is terrible or stream is early.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Penalize opening a new bin generally; discount when item is large or fit elsewhere is bad.
        score += 40.0 - tightness * 55.0 - poor_fit * 30.0
            - (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        // Opening new bin is good if next item also fits the fresh residual well.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Small reward for keeping many open bins consolidated (avoid bin proliferation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Reward perfect / near-perfect fits (non-linear) ----
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 25.0 * (fit_ratio - 0.9) / 0.1; // strong reward for tight fits
    }

    // ---- Lookahead: if next item fits in post_residual, big reward ----
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_efficiency = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 8.0 + 12.0 * chain_efficiency;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space penalty scaled by wasted space relative to next item
        score += 0.05 * post_residual as f64;
    }

    // ---- Last-chance bin: strongly favor using it to avoid opening a new bin ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // ---- Global residual coupling: prefer bins below mean residual (tighter bins first) ----
    if !is_new_bin {
        let rel = bin_residual as f64 - mean_residual;
        score += 0.03 * rel;
    }

    // ---- Penalize opening new bins when good alternatives exist ----
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln().max(0.0)
        } else {
            0.0
        };
        score += 20.0 + 10.0 * pressure;

        // Late in the stream, opening new bins is more acceptable (leftover items)
        score -= 12.0 * progress;

        // If mean residual is large, open bins are wasteful; prefer filling them
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
    }

    // ---- Mild bonus for filling many small items into one bin (fragmentation control) ----
    if post_residual < 10 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize leftover, with polynomial shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks mid-range, small at extremes
    score -= 30.0 * poly * (0.5 + progress);

    // Penalize very tight fits that leave near-zero residual only mildly early on
    score += 8.0 * (x * x) * (1.0 - progress);

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize wasting space the next item could nearly use
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * gap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Crowd penalty: prefer spreading across many open bins when residuals are high
    score += 0.5 * open_bins_count as f64 * x;

    // Mean residual coupling: discourage deviating far from the fleet mean
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it mildly unattractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals whose last digit
    // creates "dead" classes (large mod-10 remainders are harder to fill).
    let residue_class = (post_residual % 10) as f64;
    score += 0.6 * residue_class;

    // Integer-division thresholds: bins whose residual is in the tight
    // upper band (>= 3/4 of capacity worth of classes left) get a bonus.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score -= 3.0; // near-perfect packing class
    } else if post_residual > 3 * quarter {
        score += 2.0; // wasteful class
    }

    // Lookahead coupling: reward bins whose post_residual can host next item
    // exactly or with small harmonic remainder.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 5.0 + 0.25 * next_item_size as f64 - 0.3 * (slack % 10) as f64;
        } else {
            score += 2.5; // dead-ends the bin relative to lookahead
        }
    }

    // Last-chance bin: strongly favor the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default penalty: prefer reusing open bins.
        score += 35.0 - 15.0 * progress;
        // But if this is the only fitting option (or none), opening is fine.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Late in the stream, be more conservative about opening bins.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * ((bin_residual as f64) - mean_residual).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range awkward gaps: penalize proportionally to how unlikely they fit typical items.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: opening new bins is costly; penalize the new-bin candidate
    // especially when many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit in the leftover, mildly penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference toward fuller bins (relative fill).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Mean residual coupling: if this bin is much emptier than average, mild penalty
    // to prefer filling bins that are already partially used.
    if (bin_residual as f64 - mean_residual) > 20.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // next item fits, but leaves another residual chain
            let chain = (post_residual - next_item_size) as f64;
            score -= 100.0 - 0.5 * chain;
        } else {
            // next item cannot use this residual: dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when few bins fit or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 120.0 / fitting_bins_count as f64 };
        score += 80.0 + 100.0 * progress + scarcity - 0.3 * mean_residual;
    }

    // Prefer consolidating into fewer bins when many are open
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize leaving small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 - post as f64;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_fit = (post - nxt).abs();
            score -= 15.0 * (1.0 - nxt_fit / cap);
            if (nxt - post).abs() <= 2.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; slight penalty if we leave large residue.
            score += 3.0 * (post / cap);
        }
    } else {
        // Last item: maximize packing density.
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, consolidate into fuller bins (lower residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 6.0 * (open_bins_count as f64 / (1.0 + mean_residual / 20.0)) * (0.4 + 0.6 * progress);
    score += consolidation * (post / cap);

    // Prefer bins below mean residual slightly (pack fuller bins fuller).
    if (post as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0 * ((post - mean_residual) / cap).min(1.0);
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default new-bin cost; large item in fresh bin is fine, small item wasteful.
        let mut new_bin_score = cap - item + 20.0 + 15.0 * progress;
        if scarcity > 0.0 {
            new_bin_score -= 40.0;
        }
        if item >= 50.0 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score) * 0.0 + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let res_frac = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) waste sensitivity.
    let mut score = pr + 40.0 * res_frac * res_frac * cap;

    // Reward tight fits: small post_residual relative to item size gets a strong bonus.
    let tightness = (pr as f64 + 1.0) / (item_size as f64 + 1.0);
    score -= 30.0 * (-tightness * 2.0).exp();

    // Smooth stream-progress coupling: as stream progresses, waste tolerance shrinks.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Penalize bins whose residual deviates from mean residual (keep bin profile homogeneous),
    // with smooth non-linear interaction with progress.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * (dev * dev) / cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin unnecessarily), scaled by how much it would be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * fit_frac;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Mild progress-based penalty: prefer consolidation early, allow fresh bins later.
        score = 55.0 + 30.0 * progress + 0.3 * mean_residual;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64).ln();
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            let look = next_item_size as f64 / cap;
            score -= 35.0 * look * look;
        }
    } else {
        // Lookahead synergy: reward placing item such that next item still fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0 * (1.0 - progress) * (next_item_size as f64 / cap);
        }
        // Penalize leaving a sliver of dead space that likely nothing can use.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Slight preference to fill bins with smaller residuals first (best-fit style),
    // smoothly scaled by open-bin count to balance consolidation.
    score += 0.05 * (open_bins_count as f64) * res_frac * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below the minimum item size (1..100, min ~ small)
    // Post-residuals that fall into "unusable" low classes are penalized super-linearly.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.5; // near-zero residual is great
        score -= 20.0; // strong reward for almost-tight fit
    } else {
        // Integer-division harmonic classes: residuals are grouped by capacity/8 octiles
        let class = post_residual / 12; // ~8 harmonic classes on capacity 100
        score += class as f64 * 1.5;
    }

    // Perfect-fit class
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, scaled by how tight the chained fit is
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // next item will not fit here: penalize residuals just below next_item_size (wasted)
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 1.2; // near-miss is dead space for the lookahead
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when residuals
    // across open bins are poor (high mean residual) or the fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: high, but discounted when open bins are fragmented
        score = 70.0 + (mean_residual / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score = 10.0; // no alternative: must open
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if open_bins_count == 0 {
            score = 0.0; // first bin
        }
    }

    // Mild reward for filling large items into tight bins (relative fill fraction)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Penalize bins whose residual is far above the mean (fragmented outliers)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Modulo-4 harmonic class of item size: odd-sized items create awkward pairings
    if item_size % 4 != 0 && post_residual > 0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny gaps (<10) or gaps smaller than the next item
    // are effectively unusable, so punish them hard.
    if post_residual < 10 {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (small post_residual in the usable range).
    score -= (100.0 - post_residual.min(100) as f64) * 0.3;

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * 1.5 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= pressure * 0.1;
    }

    // Slight preference for bins below the mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 18.0 * next_tightness * next_tightness;
        } else {
            // Next item won't fit here; penalize wasted potential, scaled by how close it was.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.25 * overflow;
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    // (draining near-full bins keeps many emptier bins flexible).
    let rel = (mean_residual - post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge or
    // no open bin fits well. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Baseline penalty that grows with how many bins are already open
        // (discourage bin proliferation), but relax late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
        // If the item would leave a large residual, opening fresh is less bad.
        score -= 0.1 * post_residual as f64;
        // If next item is large, a fresh bin can host both better.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Slight preference for fewer open bins overall (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small leftover chunks are wasteful, especially tiny ones.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item would fit snugly in the leftover.
        let nxt = next_item_size as f64;
        let snug = nxt / post_residual.max(1) as f64;
        score -= 10.0 * snug * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for the next item: penalize proportionally to waste.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (smaller residual before placement).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, consolidation matters more.
        let openness = 1.0 - progress;
        // Prefer a new bin only if existing fit is bad (high post_residual relative to next item).
        let poor_fit = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            1.0
        } else {
            0.0
        };
        score = 40.0 + 30.0 * progress - 20.0 * poor_fit - 5.0 * openness;
        // If many open bins with large mean residual, discourage new bins.
        score += 0.1 * mean_residual;
    }

    // Mild global pressure: fewer open bins relative to stream length -> pack tighter.
    score += 0.02 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on wasted residual, scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * x * x * (0.5 + progress);

    // Cubic coupling: strongly punish mid-range residuals as stream matures
    score += 25.0 * x * x * x * (1.0 - progress).abs();

    // Reward tight fits (small post residual)
    if post_residual <= 10 {
        score -= 15.0 * (11.0 - post_residual as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0 * (next_item_size as f64 - pr) / cap;
        } else {
            score += 2.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Interaction with mean residual: prefer bins below mean (keeps large gaps alive)
    score += 0.15 * (mean_residual - pr);

    // Mild penalty for proliferating bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer opening early, discourage late unless nothing fits well
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 40.0 * progress;
        score = open_penalty + 0.5 * (mean_residual - pr).abs();
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit / quarter / third / half classes
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        // modulo classes on post_residual relative to capacity fractions
        let quarter = bin_capacity / 4;
        let third = bin_capacity / 3;
        let half = bin_capacity / 2;
        if pr < 10 {
            score += 25.0; // dead space too small for any item (sizes >= 1, but keep conservative)
        }
        if pr % quarter == 0 {
            score -= 8.0;
        }
        if pr % third == 0 {
            score -= 6.0;
        }
        if pr % half == 0 {
            score -= 5.0;
        }
        // integer division thresholds on post_residual
        let k = pr / 10; // decile class
        score += k as f64 * 1.5;
        // penalty for post_residual just above common item sizes
        for s in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr >= s && pr < s + 5 {
                score += 4.0; // awkward sliver just over a typical size
            }
            if pr == s {
                score -= 6.0; // exactly a typical size: likely reusable
            }
        }
    }

    // Lookahead coupling: does this placement leave room for next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0; // next item fits here too
            // harmonic bonus if combined exactly
            if (item_size + next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // next item won't fit
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins prefer tighter fits
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // open new bin only if existing residuals are poor fits
        let waste = mean_residual - item_size as f64;
        if waste > 0.0 && mean_residual > 0.0 {
            score -= waste.min(30.0); // existing bins have slack; slight bias to use them
        }
        score += 15.0 * (1.0 - progress); // early stream: allow opening bins
        score += open_bins_count as f64 * 0.5; // mild cost for bin proliferation
    }

    // mean residual coupling: prefer bins below mean residual (tighter)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 10) can use are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 20 {
        score += 15.0; // nearly dead space, only tiny items fit
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: attractive early in the stream, or when this fit is bad
    // and open bins are already numerous / have small mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // for empty bin = capacity - item
        let bad_fit = if fit_quality > 0.0 && fit_quality < 20.0 { 1.0 } else { 0.0 };
        let pressure = (open_bins_count as f64 / 6.0) + (20.0 - mean_residual.min(20.0)) / 20.0;
        score -= 10.0 + 25.0 * progress * bad_fit + 8.0 * pressure;
        // But never open a new bin for a perfect fit elsewhere.
        if post_residual == 0 { score += 100.0; }
    }

    // Slight preference for bins with below-average residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (100.0 - match_gap.min(100.0));
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: only the final residual matters.
        score += 10.0;
    }

    // Tightness reward: small post_residual is good (less dead space).
    score -= 0.8 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Penalize creating residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Compare against mean residual: bins already below mean are valuable to preserve;
    // prefer filling bins with larger-than-mean residual.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist;
    // allow new bins more readily late in the stream or when few bins fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score -= 6.0; // actually a good near-full fit; reward it
    }
    if post_residual >= 10 && post_residual < 25 {
        score += 4.0; // awkward leftover zone
    }

    // Lookahead (k=2): if the next item fits in the post residual, reward keeping it viable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item would exactly fill the post residual, extra reward (perfect pair).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 6.0;
    }
    // Penalize if post residual can't fit next item but is still sizeable.
    if next_item_size > post_residual && post_residual >= 10 {
        score += 2.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild penalty scaled by scarcity of alternatives.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; grows with number of open bins (fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // But if this item is large relative to capacity, opening fresh is less bad.
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin leaves a good fit, allow new bin: covered by competing scores.
    }

    // Global state coupling: prefer bins whose residual is below mean (denser bins first).
    score += 1.2 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) / 10.0;

    // Late-stream consolidation: as the stream ends, squeeze into open bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize post residual, with smooth non-linear coupling to progress
    let mut score = x * (1.0 + 0.9 * progress * progress);

    // Polynomial coupling: post_residual squared term scaled by item size
    let isz = item_size as f64 / cap;
    score += 0.35 * x * x * (1.0 - isz);

    // Interaction of post residual with mean residual: prefer bins near the mean
    let dev = (mean_residual - pr) / cap;
    score += 0.25 * dev * dev;

    // Lookahead: reward if next item fits into post residual (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = if x >= nx { 1.0 } else { 0.0 };
        let smooth = fit * (1.0 - (x - nx).abs());
        score -= 0.6 * smooth * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - x);
    }

    // Late stream: favor tighter fills (smaller post residual) more aggressively
    score += 0.5 * progress * (1.0 - x) * (1.0 - x);

    // Mild penalty proportional to number of open bins to consolidate
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (large enough for common small items) are favored.
    let r = post_residual;
    let class = (r % 10) as f64;

    // Reward residuals that are multiples of 10 (clean harmonic slots).
    if r % 10 == 0 {
        score -= 6.0;
    } else {
        // Penalize awkward leftovers proportional to distance from a multiple of 10.
        score += class * 0.4;
    }

    // Dead space: residuals too small for the minimum item (1..=100 interface).
    if r < 10 && r > 0 {
        score += 25.0;
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= r {
        let slack = (r - next_item_size) as f64;
        score -= 8.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
        // Harmonic check: next item leaves a clean multiple-of-10 residual too.
        if r % 10 == next_item_size % 10 {
            score -= 3.0;
        }
    } else if next_item_size > r && next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the wasted gap.
        score += 0.15 * (next_item_size - r) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, slightly discouraged
    // unless current bin would leave large dead space.
    if bin_residual == bin_capacity {
        score = 0.5 * bin_capacity as f64
            - 10.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= r {
            score -= 5.0;
        }
    }

    // Progress coupling: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * (mean_residual - post_residual as f64);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: only attractive if the item leaves a large, reusable gap
    // or no open bin fits well; make the empty-bin baseline moderate.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.5;
        // If this is the last chance among fitting bins, don't open a new bin.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving awkward gaps.
        if post_residual > 0 && post_residual < 15 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is below the mean (more filled bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    // => bin will be perfectly closed after next placement. Strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits into post_residual (two placements in a row).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Next item does NOT fit the post_residual: dead space penalty, worse when
    // the leftover is small (unusable) relative to typical item sizes.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 12.0 * (1.0 - dead / bin_capacity as f64);
        // Extra penalty if the dead space is below the minimum plausible item size.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual sits near the
    // mean residual (keeps the bin population homogeneous and reusable).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are badly fragmented (mean residual small) or when no
    // open bin fits well. Penalize the fresh bin mildly otherwise.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - mean_residual / bin_capacity as f64;
        // If open bins are fragmented (low mean residual), reward opening new bin.
        score -= 20.0 * fragmentation;
        // But if a good fit exists among open bins (post_residual small here means
        // nothing for a fresh bin; instead check if next item matches residual 100),
        // penalize slightly to prefer filling existing bins when they fit decently.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    // Mild stream-progression term: later in the stream, closing bins tightly
    // matters more (fewer chances to consolidate), so reward tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Lookahead: strongly reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let gap = (post_residual as u32 - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
            if post_residual as u32 == next_item_size {
                score -= 15.0; // perfect two-item chaining
            }
        } else {
            // next item cannot follow here; penalize proportionally
            score += 3.0 * (1.0 - (item_size as f64) / cap);
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize creating small unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: open only if existing bins are crowded or poor fits
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 18.0 * (1.0 - crowded);
        score += 10.0 * (mean_residual / cap) * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing fits, must open
        }
    } else {
        // Existing bin: slight bonus early, avoid hoarding many half-empty bins
        score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);
    }

    // Mild penalty for very empty placements into nearly-full bins is already
    // captured by post_residual; add small noise-free diversification term
    score += 0.01 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling: reward tight fits with progress-dependent weight
    let tight = 1.0 - norm_pr * norm_pr; // high when post_residual small
    score -= tight * (2.0 + 3.0 * t) * cap * 0.1;

    // Penalize large dead space non-linearly, stronger later in stream
    score += norm_pr * norm_pr * norm_pr * cap * (0.5 + t);

    // Exact fit bonus
    if post_residual == 0 {
        score -= cap;
    }

    // Lookahead: reward leaving space that next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 1.5 * (1.0 - ((pr - nxt) / cap).abs() * 2.0).max(0.0);
        } else {
            score += 0.5 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.8;
    }

    // New-bin candidate penalty unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_bad = mean_residual / cap;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += cap * (0.6 - 0.5 * mean_bad) - 10.0 * scarcity * (1.0 - norm_item);
        score += 5.0 * t;
    }

    // Mild dispersion penalty: prefer bins near mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 2.0;

    // Slight preference for fuller bins as bins accumulate
    score -= (open_bins_count as f64).ln().max(0.0) * (norm_item * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a "nice" fraction
    // of capacity (multiples of 10, 25, 50) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    if post_residual == 0 {
        score -= 60.0; // perfect fit, always best
    } else {
        // divisibility-based reusability bonus
        let mut bonus = 0.0;
        if post_residual % 50 == 0 { bonus += 25.0; }
        else if post_residual % 25 == 0 { bonus += 18.0; }
        else if post_residual % 10 == 0 { bonus += 12.0; }
        else if post_residual % 5 == 0 { bonus += 6.0; }
        score -= bonus;

        // Harmonic class of the item: small items (<= post_residual classes) fit later
        if post_residual % item_size == 0 {
            score -= 8.0; // leftover exactly divisible by this item's class
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic quality of the slack left for the next item
            if slack == 0.0 {
                score -= 40.0;
            } else if (post_residual % next_item_size) == 0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / cap);
            }
        } else {
            // next item cannot fit here; mild penalty scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the resulting residual is tiny dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 && post_residual > 0 {
            score += 10.0; // nearly-dead leftover makes new bin attractive
        }
    }

    // Penalize opening new bins when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0; // existing space could have hosted the item
        }
    }

    // Tightness reward: bins that were nearly full before placement are precious.
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * tightness * tightness;

    // Non-linear coupling: penalize mid-range residuals (awkward dead space)
    let frac = post / cap;
    score += 12.0 * (frac - 0.5) * (frac - 0.5) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // possible item (size 1..=10 under the general interface) are wasted.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0; // unusable gap penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect fill reward
    }

    // Reward tight fits relative to bin residual (best-fit flavor, sharpened).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let open_pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0) * 0.05);
    score += 8.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (avoid dumping into fat bins).
    score += 0.15 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would not fit here anyway, mild bonus for using this bin now.
    if next_item_size > post_residual && next_item_size > 0 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has a large baseline score so it is
    // only chosen when all open bins score badly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream opening bins is cheap; late, be conservative.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact matches with the lookahead item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // The next item fits here afterwards: reward closeness to a perfect 2-step fill.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the residual: penalize proportional to wasted potential.
            score += 8.0 * (diff / bin_capacity as f64);
        }
        // Perfect 2-step closure (residual exactly equals next item size).
        if diff < 1.0 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit, i.e. minimal post residual.
        score *= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual already below average (well-utilized bins):
    // placing into them keeps big residuals available for big future items.
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty for very small, hard-to-use leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Early in the stream, be more willing to open/use fresh space structure;
    // late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Discard-penalty for brand-new-bin candidate unless open bins are poor fits:
    // make the empty-bin candidate score slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.25 * (post_residual as f64);
        } else {
            // Reward bins whose leftover can host the next item.
            score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64));
        }
        // Exact pairing bonus: item + next item fills bin perfectly.
        if item_size + next_item_size == bin_residual {
            score -= 10.0;
        }
    } else {
        // Last item: prefer fullest fill possible.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into the best fits.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate handling: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = (step_index as f64) / (total_items.max(1) as f64);
        score += 22.0 - 20.0 * pressure - 6.0 * late;
        // Opening bins early in stream is fine; late in stream prefer filling.
        if open_bins_count > 8 {
            score += 4.0;
        }
    }

    // Global balance: discourage drifting far from mean residual (keeps bins uniform,
    // easier to combine later).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early on, slightly prefer keeping residuals flexible (mid-range),
    // late in stream, prefer maximum fill.
    let t = (step_index as f64) / (total_items.max(1) as f64);
    let mid_flex = 1.0 - (2.0 * t - 1.0).abs();
    score += 2.0 * mid_flex * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Tight fits (small post_residual) are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit, 0.0 = empty bin
    let tight_reward = tightness * tightness * (1.0 + 3.0 * progress);
    score -= 6.0 * tight_reward;

    // Cubic penalty on large wasted space, amplified late in the stream.
    let waste = pr / cap;
    score += 4.0 * waste * waste * waste * (1.0 + 2.0 * progress);

    // Interaction: prefer bins whose residual is close to mean residual (balance),
    // scaled non-linearly by normalized deviation.
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Penalize leaving residual that narrowly misses the next item (dead space),
    // smooth quadratic in the gap.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += 5.0 * g * g;
        } else {
            // Residual can host next item: reward smoothly.
            score -= 2.0 * tightness;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Slight preference for consolidating into fewer bins early on.
    score -= (open_bins_count as f64).recip() * (1.0 - progress);

    // New-bin candidate: neutral baseline with mild late-stream penalty so we
    // prefer reusing open bins unless this is a perfect fit.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * tightness;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    // Residuals in [0,10] are near-perfect (good), mid residuals (20..40) are
    // dead-space prone (bad), large residuals are flexible (ok).
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 80.0; // near-perfect closure
    } else if pr > 10 && pr <= 20 {
        score -= 25.0; // usable small slot
    } else if pr > 20 && pr <= 40 {
        score += 45.0; // dead-space danger zone
    } else if pr > 40 {
        score -= 10.0; // still flexible
    }

    // Modulo arithmetic: residuals that are multiples of common small sizes
    // (e.g. multiples of 5 or 10) are more likely to be exactly filled later.
    if pr % 10 == 0 && pr > 0 {
        score -= 30.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Odd, prime-unfriendly residuals are less reusable.
    if pr % 3 != 0 && pr % 7 != 0 && pr > 40 {
        score += 8.0;
    }

    // Lookahead: if next item exactly fills the post_residual, huge reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits here: mild reward proportional to how snugly.
        let snug = 1.0 - (pr - next_item_size) as f64 / pr.max(1) as f64;
        score -= 40.0 * snug;
    } else if next_item_size > pr {
        // Next item cannot use this residual; penalize leaving mid-size gaps.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has huge flexibility, but we
    // prefer using existing bins unless the fit is bad. Give the empty bin a
    // baseline penalty so it only wins when open-bin scores are worse.
    if bin_residual == bin_capacity {
        score += 140.0;
        // Late in the stream, opening fresh bins is cheaper (less fragmentation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress;
        // If many bins are open, prefer consolidating into them.
        score += 6.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin may be valuable.
        if next_item_size >= 70 {
            score -= 50.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate fills) when mean is small; prefer above-mean bins when
    // mean is large (spread usage).
    let dev = bin_residual as f64 - mean_residual;
    if mean_residual < 30.0 {
        score += 0.5 * dev;
    } else {
        score -= 0.3 * dev;
    }

    // Early stream: be slightly greedy for tight fits to establish structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size = 1..100, but tiny slivers < 12 are
    // practically unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    }
    // Perfect fit: strongly reward consuming the bin entirely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: the smaller the leftover relative to capacity,
    // the better (non-linear coupling).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 50.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; penalize placements that leave large gaps when the
    // bin population is already large.
    let obp = open_bins_count as f64;
    score += (post_residual as f64 / 100.0) * (obp / (obp + 5.0)) * 30.0;

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chaining opportunity).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 12 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover likely becomes dead space.
        score += (post_residual as f64).min(30.0) * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (already a "junk" bin), prefer dumping into it rather than into
    // healthier bins.
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual {
        score -= (mean_residual - this_residual) * 0.3;
    } else {
        score += (this_residual - mean_residual) * 0.2;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and open bins are scarce or all fits would be terrible.
    if bin_residual == bin_capacity {
        let mut base = 25.0 + obp * 6.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base *= (1.0 - progress * 0.5);
        // If the item is huge, a fresh bin gives a clean fit.
        if item_size >= 60 {
            base -= 20.0;
        }
        // If no good fit exists elsewhere (fitting bins all leave dead space),
        // soften the new-bin penalty.
        if fitting_bins_count > 0 {
            base -= 10.0;
        }
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead bonus: perfect match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward closeness of fit for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize large dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable residuals (dead space < 10).
    if post_residual < 10 {
        score -= 15.0; // a filled-to-near-capacity bin is good
    }

    // Slight preference for reusing open bins over opening new ones,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Early in the stream, be more liberal about opening bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Exact fit is nearly free.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for any plausible item.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 0.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (next_item_size as f64 / post_residual as f64).max(0.0));
        } else {
            // next item won't fit here: penalize less if residual is generally small anyway
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // If few fitting bins and mean residual is low, opening new bin is less bad.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if item_size > 60 {
            score -= 25.0; // big items prefer fresh bins
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer fuller bins overall (relative to fleet mean residual).
    score -= 3.0 * (mean_residual - post_residual as f64).signum() * (mean_residual - post_residual as f64).abs().min(50.0) / 50.0;

    // Mild preference to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Smooth non-linear coupling: waste (post_residual) is penalized more
    // aggressively as the stream progresses (dead space hurts more later).
    let waste_coupling = (post_residual as f64 / bin_capacity as f64)
        * (1.0 + 2.0 * prog2 + 1.5 * prog3);
    score += 3.0 * waste_coupling;

    // Perfect-fit reward: smooth polynomial in post_residual
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / bin_capacity as f64).powi(2);
    score -= 4.0 * tightness * (1.0 + progress);

    // Lookahead synergy: if next item fits into the resulting residual,
    // reward this placement smoothly based on how well it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 5.0 * fit_ratio * (1.0 - fit_ratio).powi(2) * (1.0 + 0.5 * progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: penalize proportional to wasted capacity
        score += 1.5 * (post_residual as f64 / bin_capacity as f64) * (1.0 + prog2);
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Favor bins whose residual is already below mean (filling tighter bins first)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-2.0).min(2.0);

    // New-bin candidate: only attractive when current residuals are poor
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let mean_waste = mean_residual / bin_capacity as f64;
        // Opening a new bin is good when mean residual is high (fragmented bins)
        score += 10.0 - 12.0 * mean_waste * (1.0 + progress);
        // Discourage hoarding bins early in the stream
        score += 2.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 5 classes.
    let class = post_residual / (bin_capacity / 5).max(1);
    let class_penalty: f64 = match class {
        0 => -40.0, // near-perfect fit (post_residual < 20)
        1 => -10.0, // small gap, moderately usable
        2 => 0.0,
        3 => 8.0,
        _ => 15.0,  // large dead space
    };
    score += class_penalty;

    // Reward exact fill strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits into post_residual, this bin keeps value.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Harmonic match: post_residual - next_item_size lands in a good class.
        let gap = post_residual - next_item_size;
        if gap < bin_capacity / 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: bin likely becomes dead space.
        score += 10.0;
        if post_residual < 10 {
            score -= 15.0; // but tiny residual is fine (sealed bin)
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    // or this bin would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0; // base cost of opening a new bin
        score -= congestion * 5.0;
        if class_penalty > 5.0 {
            score -= class_penalty * 1.5; // escape bins that would waste space
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful
    // (smaller than the minimum possible item) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    }

    // Penalize "unusable" gaps: residual smaller than the lookahead item and
    // smaller than a typical item => dead space.
    let lookahead = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < lookahead {
        score += 40.0 + 0.5 * (lookahead - post_residual) as f64;
    }

    // Reward leaving a gap that exactly fits the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill the fuller bins first, keep large residuals for future big items).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how contested the fit is.
        let pressure = if fitting_bins_count == 0 { -200.0 } else {
            120.0 + 15.0 * fitting_bins_count as f64
        };
        score += pressure;
        // Late in the stream, opening new bins is cheaper than hoarding dead space.
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect two-step match: leave exactly enough for next item
        } else if nxt <= post {
            // next item fits in residual: reward proportional closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving a large unusable gap
            score += 10.0 + 0.3 * (post - nxt);
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score -= 15.0 * (1.0 - (post / mean_residual).min(2.0) / 2.0);
    }

    // Penalize creating small dead space (< next plausible item size band).
    if post > 0.0 && post < 10.0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild pressure to fill existing bins when many are open.
    score -= 2.0 * open_bins_count as f64 * (1.0 - post / cap);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // make new bin slightly worse than any decent existing fit
            score += 5.0 + 0.5 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Wasted residual if it can't host the next item: penalize large leftover.
            let waste = post_residual as f64 - if post_residual >= next_item_size { next_item_size as f64 } else { 0.0 };
            score += 0.03 * waste;
            // Small residual that blocks next item but is large enough to be useful later:
            if post_residual < next_item_size && post_residual >= 10 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin, cheaper late in stream.
        let mut open_cost = 30.0 - 10.0 * progress;
        // If few fitting bins, opening a new one is reasonable.
        if fitting_bins_count <= 1 {
            open_cost -= 20.0;
        }
        // If mean residual across open bins is large, prefer filling existing bins.
        open_cost += 0.15 * mean_residual;
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size > post_residual + 5 && next_item_size > 0 {
            open_cost -= 6.0;
        }
        score += open_cost;
    } else {
        // Prefer bins below mean residual (fill the emptier ones to balance).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild entropy: discourage accumulating many nearly-full bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, but with non-linear polynomial in x
    let mut score = pr as f64;

    // Smooth non-linear coupling of residual with stream progress:
    // early on, large residuals are fine (score discount grows with progress)
    let poly = x * x * (1.0 - progress) - x * x * x * progress;
    score += 30.0 * poly;

    // Tightness bonus: near-zero post residual strongly favored, scaled by progress
    let tight = (1.0 - x).powi(3);
    score -= 25.0 * tight * (0.5 + progress);

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
        score -= 20.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Penalize spreading across many open bins when residuals are high
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // New-bin candidate: neutral baseline with slight progress-dependent preference
    if bin_residual == bin_capacity {
        score += 10.0 - 5.0 * progress;
        // open new bin if best existing fit is very wasteful
        if post_residual > 0 && x > 0.5 {
            score -= 15.0 * (x - 0.5);
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter)
    score += 3.0 * (mean_residual - pr).signum() * ((mean_residual - pr).abs().sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: classify leftover space by how likely
        // a future item (sizes 1..=100) can use it. Residuals that are multiples
        // of common item sizes are "reachable"; tiny residuals are dead space.
        let r = post_residual;
        let class: f64 = if r < 5 {
            0.0 // dead space class
        } else if r % 10 == 0 {
            3.0 // highly reusable (grid of 10s)
        } else if r % 5 == 0 {
            2.0 // reusable
        } else if r % 2 == 0 {
            1.0 // mildly reusable
        } else {
            0.5 // odd, less reusable
        };
        // Reward reachable residuals, penalize dead space.
        score -= class * 6.0;
        // Penalize small residuals non-linearly (dead space grows in cost).
        if r < 15 {
            score += (15 - r) as f64 * 1.5;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        if next_item_size == post_residual {
            score -= 200.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting a slot.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in stream, opening bins is cheaper; late stream, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
        // If many bins are open with slack, discourage another.
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps tight bins tight).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for tighter fits overall (best-fit tilt on large items).
    score += (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // later (below the minimum plausible item size) are heavily penalized,
    // while post_residuals that could still host a future item are mildly good.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fill is excellent
        score -= 40.0;
    }

    // Reward tight fits: fraction of residual consumed by the item
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open bins pressure: discourage proliferating bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are badly fragmented (high mean residual spread) or when
    // no bin fits well. Penalize new bin when mean residual is healthy.
    if bin_residual == bin_capacity {
        if mean_residual > 25.0 {
            // open bins are fragmented; a fresh bin is reasonable
            score -= 10.0;
        } else {
            // existing bins are roomy; avoid opening a new one
            score += 30.0 + mean_residual;
        }
        // If the next item is large, a fresh bin with full residual is valuable
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // For existing bins: if next item could exactly fill this bin's
        // post_residual, reward saving that space for it.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0;
        }
    }

    // Slight late-stream tightening: as stream progresses, prefer consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            // next item fits in the leftover: partial reward, scaled by how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 250.0 / (1.0 + slack * 0.5);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 2.0;
        }
    } else {
        // Last item: prefer tightest packing, exact fit already rewarded.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better hosts.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty discourages premature opening.
        score += 200.0;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 250.0;
        }
        // If this is the last-chance situation, allow opening a fresh bin
        // (compete with the lonely open bin, which already got -300).
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
        // Late in the stream, avoid leaving many half-empty bins behind.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 150.0 * (progress - 0.8) * 5.0;
        }
        // Many open bins with high mean residual: better to consolidate.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 80.0;
        }
    }

    // Mild global pressure: prefer denser bins when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize creating unusable dead space: residual too small for the
    // smallest plausible item (assume min item ~1, but small residuals waste).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // nearly-dead space penalty
    }

    // Lookahead: strongly reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else if bin_residual >= next_item_size {
            // next item could go elsewhere; slight penalty for consuming
            // space it might have needed.
            score += 2.0;
        }
        // If next item exactly fills leftover, huge reward (perfect pair).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: only one open bin fits -> strong reward to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    // Penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Cheaper to open bins early in the stream (amortization) or when
        // many bins are already open (diversification of residual sizes).
        score -= 10.0 * (1.0 - progress);
        score -= (open_bins_count as f64).sqrt() * 1.5;
        // If mean residual across open bins is large, prefer using them:
        // penalize new bin more.
        if mean_residual >= item_size as f64 + 5.0 {
            score += 10.0;
        }
        // If item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.15;
    }

    // Reward using bins whose residual is close to item (exact-fit shaping).
    let fit_gap = (bin_residual - item_size) as f64;
    if fit_gap < 5.0 {
        score -= 5.0;
    }

    // Mild preference for filling fuller bins (residual smaller than mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Polynomial coupling: penalize small unusable residuals, reward tight fits
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Interaction of residual with mean residual: penalize bins far from mean
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: if next item fits in post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 + 3.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize residuals that block the next item
        score += 2.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).abs().min(1.0);
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening new bins mildly, more so early in stream
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Penalize large open-bin count slightly to encourage consolidation
    score += 0.05 * open_bins_count as f64 * progress;

    // Smooth quadratic in item fill ratio
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "dead zones".
    let res = post_residual % 10;
    let quot = post_residual / 10;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual in 1..10 is nearly unusable (min item size 1).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Harmonic banding: reward post_residuals divisible by 10 (clean classes),
    // penalize awkward residues like 1..3 that create scrap.
    score += match res {
        0 => -(quot as f64) * 2.0,
        1 | 2 | 3 => 6.0 + res as f64,
        _ => res as f64 * 0.5,
    };

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item can't use this bin's leftover; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: it should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64;
        // Penalize opening new bins early in the stream or when many bins already open.
        score += open_bins_count as f64 * 2.0;
        score += (step_index as f64 / total_items.max(1) as f64) * 30.0;
        // If mean residual is large, open bins are wasteful; discourage new bin less.
        score -= mean_residual * 0.5;
        // If next item is large and this item is small, new bin may be justified.
        if next_item_size > 60 && item_size < 40 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit bias).
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // plausible follow-up item are pure waste -> heavy quadratic penalty.
    let min_useful = 10.0_f64.min(item.max(1.0));
    if post < min_useful {
        score += 40.0 + (min_useful - post) * 8.0;
    } else {
        // Smooth penalty ramping up as the gap becomes "hard to fill"
        let fill_ratio = post / cap;
        if fill_ratio < 0.2 {
            score += (0.2 - fill_ratio) * 60.0;
        }
    }

    // Reward excellent fits (small but still usable leftovers).
    if post > 0.0 {
        let tightness = item / bin_residual as f64;
        score -= tightness * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins whose residual is close to the mean (keep the pool uniform,
    // preserving large residuals in few bins for future large items).
    score -= 6.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap)).min(1.0);

    // Lookahead: if the next item fits exactly in the post gap, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 + (post - nxt).min(20.0) * 0.5;
        } else if post > 0.0 {
            score += 5.0; // next item won't fit here; slight penalty
        }
    }

    // New-bin candidate: attractive when this item would leave a bad gap
    // in any existing bin, or when few bins are open early on.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post < min_useful { 25.0 } else { 0.0 };
        score -= 18.0 - bad_fit_penalty - (fitting_bins_count as f64) * 2.0;
        if open_bins_count < 3 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match: heavy reward; decays quadratically with slack.
        score -= 60.0 * (1.0 - (slack / 50.0).min(1.0)).powi(2);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize mildly, scaled by how far off we are.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / 40.0).min(1.0);
    }

    // Penalize tiny dead space (unusable fragments) strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Prefer tight fits relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in stream: consolidate; early: allow opening bins for better packing.
    score -= 15.0 * progress * (bin_residual < bin_capacity as u32) as i32 as f64;
    score += 12.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Slight penalty for many open bins to encourage reuse.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio * bin_residual as f64;

    // Penalize leaving "awkward" residuals that are too small for typical items
    // (dead space in the 1..=9 band is nearly unusable for items >= 10).
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    } else if post_residual <= 19 {
        score += 3.0; // marginal zone
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving a large residual
            // that will likely be stranded anyway.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits available) and the item is big.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64; // high = open bins are empty-ish
        let new_bin_score = 25.0
            - 18.0 * pressure
            - 6.0 * (item_size as f64 / bin_capacity as f64)
            - 4.0 * progress
            + 0.5 * (open_bins_count as f64).ln().max(0.0);
        // If next item is huge, opening fresh may help pair it later.
        if next_item_size >= 60 {
            new_bin_score -= 3.0;
        }
        return new_bin_score;
    }

    // Global state: when mean residual is small (bins nearly full), prefer
    // consolidating into tight fits even more.
    score += 0.05 * mean_residual * (1.0 - fit_ratio);

    // Mild penalty for spreading across many open bins when this bin is loose.
    if fit_ratio < 0.5 {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fits preferred, with non-linear (quadratic/cubic) shaping of post_residual.
    let mut score = pr + 0.004 * pr * pr / cap - 0.00002 * pr * pr * pr / (cap * cap);

    // Smooth coupling: residual waste matters more as the stream progresses.
    let waste_coupling = pr * (0.5 + progress);
    score += 0.002 * waste_coupling;

    // Reward bins whose residual aligns with the mean residual (homogeneous packing).
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.3 + 0.7 * progress);

    // Lookahead: strongly reward leaving a residual that fits the next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_next = if pr >= nxt { 1.0 - gap / cap } else { 0.0 };
        score -= 8.0 * fit_next * fit_next;
        // Penalize leaving a residual slightly larger than next item (near-miss dead space).
        if pr >= nxt && gap < 10.0 {
            score += 3.0 * (10.0 - gap) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening bins, more so early and when many bins are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (1.0 - progress) + 0.4 * open_bins_count as f64;
        // But allow opening when all existing fits are terrible.
        let tightness = 1.0 - pr / cap; // = 1.0 for new bin, useless here
        score -= 0.0 * tightness;
    }

    // Mild reward for filling bins completely (smooth saturation).
    let fill = 1.0 - pr / cap;
    score -= 5.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division into capacity fractions.
    let class = post_residual / 10; // classes 0..=10
    // Reward small residuals (tight fits) with a step bonus per class.
    score -= (10 - class as i32) as f64 * 1.5;

    // Dead-space penalty: residual that no typical item (<=80) can use is worse.
    if post_residual > 80 {
        score += (post_residual - 80) as f64 * 2.0;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual (harmonic chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Penalize when next item cannot use the leftover space.
        score += 2.0;
    }

    // Modulo harmonic: residuals divisible by small common sizes are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it neutral-slightly high so it only wins
    // when open bins are poor fits (large post residual for the new bin is 100-ish,
    // but its class bonus is small since it stays empty).
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early stream: opening bins is fine; late stream: prefer filling open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // If many bins already open, discourage yet another one.
        score += open_bins_count as f64 * 0.5;
        // If no open bin fits, the new bin is the only option; soften.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to spread load when mean residual is low (bins nearly full).
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface => treat < 8 as near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    } else if post_residual < 15 {
        score += 12.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot use the leftover gap (dead space chain).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But a new bin is attractive if existing mean residual is small (all bins tight).
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // If no open bin fits well (this is the only fitting candidate), ease opening.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    } else {
        // Mild penalty for spreading across many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Early stream: be slightly conservative, keep bins open for future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: post_residual slightly larger than next item -> still good.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff > 0.0 && diff <= 20.0 {
            score -= 60.0 * (1.0 - diff / 20.0);
        }
    }

    // Penalize unusable dead space: post_residual too small for typical items.
    if post_residual < 10 {
        score += 80.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Prefer bins whose residual deviates from mean residual in a useful way:
    // a bin with less residual than average that still fits -> tighter packing.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score -= 0.5 * open_bins_count as f64;

    // Early in the stream, be more willing to open new bins (score new-bin candidate well);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual after placement relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Penalize dead space: residuals too small for the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 20.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones over opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 5.0 * pressure * tightness;

    // Mean residual coupling: if this bin is below mean residual (fuller than average), reward.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if item_size >= 60 {
            score -= 5.0; // large items may warrant fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Dead-space penalty when post-residual can't fit the lookahead item (smooth ramp).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 18.0 * gap * gap * (1.0 + t);
        // Bonus if the next item fits exactly in the post-residual.
        let fit_gap = (nx - pr).abs() / cap;
        score -= 6.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize the new-bin candidate (empty bin) unless few bins fit the item.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        score += 25.0 * (1.0 - t) + 10.0 * scarcity * (1.0 - t);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (more filled).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Small-scale polynomial interaction of post_residual with progress.
    score += 0.05 * pr * pr / cap * (0.5 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: residues mod 10 modulate desirability
    let residue_class = post_residual % 10;
    let harmonic_bonus = match residue_class {
        0 => -14.0,                       // perfectly aligned residual
        5 => -7.0,                        // half-capacity class
        2 | 8 => -3.0,
        4 | 6 => -1.5,
        _ => 0.0,                         // odd, awkward residues
    };
    score += harmonic_bonus;

    // Integer-division tier: how many size-10 slots remain
    let slots = post_residual / 10;
    score -= slots as f64 * 2.5;

    // Coupling with next item: reward residual that exactly fits the lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (10 - slack % 10) as f64 * 1.2;
        } else {
            // lookahead cannot fit here: penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 8.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening fresh bins unless item is huge
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * fill_ratio;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 6.0; // pairing possible in an existing bin instead
        }
    }

    // Tight fits are golden regardless of class
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 15.0 * tightness;
    }

    // Mean residual context: prefer bins near the mean (balance residuals)
    score += 0.6 * ((post_residual as f64 - mean_residual).abs());

    // Late in the stream: consolidate aggressively
    score -= progress * (bin_capacity - post_residual) as f64 * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but realistically < 10) are nearly worthless. Penalize them heavily.
    if post_residual < 10 {
        // Perfectly tight fit (post_residual == 0) is ideal.
        if post_residual == 0 {
            score -= 60.0;
        } else {
            // Small gap that can never be filled: heavy penalty.
            score += (10 - post_residual) as f64 * 12.0;
        }
    } else {
        // Graded penalty: prefer leaving larger, reusable gaps over mid-size gaps.
        // A gap is "reusable" if it can hold the next item or a typical small item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0; // gap remains useful for the lookahead item
        }
        // Mid-size dead zones (10..=25) are the worst offenders after tiny gaps.
        if post_residual <= 25 {
            score += (26.0 - post_residual as f64) * 3.0;
        }
    }

    // Exact-fit reward relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // When many bins fit, mild penalty encourages consolidation elsewhere.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 4.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing bins
    // (penalize the new-bin candidate implicitly via open_bins_count term).
    score += open_bins_count as f64 * 2.5;

    // New-bin candidate shaping: an empty bin is only attractive when the item
    // is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        } else {
            score += 35.0 + mean_residual * 0.3;
        }
    }

    // Lookahead coupling: if the next item would also fit here after placement,
    // reward this bin (chain placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in the leftover: leftover risk of becoming dead space.
        score += post_residual as f64 * 0.4;
    }

    // Stream progression: late in the stream, be more aggressive about filling
    // bins tightly rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Deviation from mean residual: prefer bins whose residual is already low
    // (i.e., nearly full bins) to concentrate packing.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post-residual,
    // this placement is excellent (chains a second fill).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0 + 0.5 * (post_residual - next_item_size) as f64;
        // Perfect chain: post residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that the next item cannot use: penalize proportionally
        // to how big the leftover gap is relative to the next item.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap;
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidate unless it enables a clean lookahead chain.
    if bin_residual == bin_capacity {
        score += 90.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - progress);
    }

    // Slight preference for bins with fewer competitors (spread load when many fit).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward if next item nearly fills the residual too.
        let combo = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - combo);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty for dead space.
        score += 8.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize bins far below mean residual (scattered small fills), prefer fuller bins.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Prefer opening new bins early in the stream when many bins are empty-ish;
    // later in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when progress is low or open bins are full-ish.
        let openness = 1.0 - progress;
        score -= 30.0 * openness;
        score += 0.3 * open_bins_count as f64 * progress;
        // If item is large, a fresh bin is safer.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Discourage leaving residuals that are too small to be useful (<10 unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear penalty on residual: quadratic coupling with stream progress
    let mut score = base * (1.0 + 0.6 * progress * (pr / cap));

    // Reward tight fits strongly (post_residual near zero)
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize leaving residuals that can't fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 4.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            // reward residuals that exactly accommodate the next item
            let gap = (pr - nx) / cap;
            score -= 3.0 * (1.0 - gap) * (1.0 - gap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 + progress);
    }

    // Penalize spreading across too many open bins relative to mean residual
    let mr = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).ln() * (0.3 + mr);

    // New-bin candidate: default moderate score, lowered only when open bins are poor
    if bin_residual == bin_capacity {
        score = 30.0 - 20.0 * progress - 10.0 * (1.0 - mr);
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "reusable" size classes should be rewarded (subtract), dead-space
    // classes penalized (add).
    let cap = bin_capacity as f64;

    // Class A: post_residual exactly 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Class B: post_residual small enough to be filled by common small items.
    // Residual classes via integer division thresholds (harmonic bands).
    let band = post_residual / 10; // 0..10 harmonic band
    match band {
        0 => score -= 8.0,                 // residual < 10: nearly full, great
        1 => score -= 4.0,                 // 10..19: fillable by any item
        2 => score -= 2.0,                 // 20..29
        3 => {},                           // 30..39 neutral
        4 => score += 2.0,                 // 40..49: awkward gap
        5 => score += 3.0,                 // 50..59
        6 => score += 2.0,                 // 60..69
        7 | 8 => {},                       // large residual: still flexible
        _ => {},                           // near-empty bin
    }

    // Modulo-10 class coupling: residuals that are multiples of 10 pair well
    // with the 10..80 item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize large leftover gaps
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 40 {
            score += 10.0; // don't burn a whole bin's worth of space
        }
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // no open bin offers a decent fit. Penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * (step_index as f64 / total_items.max(1) as f64));
        // But if mean residual across open bins is tiny (all nearly full),
        // opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Slight preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op keep signature clean
    score -= (cap - post_residual as f64) * 0.05; // reward fuller resulting bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    let usable_threshold = 20.0f64; // gaps below this are near-dead space
    if post_residual > 0 && (post_residual as f64) < usable_threshold {
        score += (usable_threshold - post_residual as f64) * 3.0; // dead-space penalty
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as f64) <= min_item {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // lookahead can't use this gap
        }
    }

    // Tightness reward: proportional fit quality.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: with many open bins, prefer packing existing bins
    // (especially the last-chance bin) over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // last-chance bin: strongly favor using it
    }

    // New-bin candidate: make it attractive only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let avg_gap = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Open a new bin when current bins are quite full on average and item is large.
        if avg_gap < item_size as f64 * 0.6 && fill_ratio > 0.5 {
            score -= 30.0;
        } else {
            score += 15.0 + poor_fit * 0.2; // discourage spreading items thin
        }
    }

    // Mean residual coupling: avoid dumping into bins whose residual is anomalous.
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (near-perfect packing).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the
    // post residual, this bin is doubly valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; small penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Relative-to-mean coupling: bins with residuals far below mean are
    // "tight" bins — using them is good; bins above mean are wasteful targets.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: opening a fresh bin wastes space equal to the
    // item unless the item is large or current bins are very tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins are loose; allow new bins
        // when the stream is deep and residuals are tight.
        score += 70.0 * (1.0 - tight) * (1.0 - 0.5 * progress);
        // Large items are fine in fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // If next item is small, a fresh bin wastes the lookahead chain.
        if next_item_size > 0 && next_item_size <= 20 && item_size >= 30 {
            score += 25.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize large dead space quadratically.
    if post_residual > 20 {
        let d = (post_residual - 20) as f64;
        score += 0.05 * d * d;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward for chaining fits.
        if post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    }
    // If next item won't fit, mildly penalize wasting a big residual.
    if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are bad and
    // many open bins exist (avoid bin proliferation early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 45.0
            - 0.15 * open_bins_count as f64
            - 20.0 * progress
            - scarcity;
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += 0.3 * mean_residual;
    }

    // Slight preference for filling fuller bins (small bin_residual).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Time-horizon coupling: late in the stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = post_norm * (1.0 + 0.8 * post_norm * post_norm);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly
    let coupling = post_norm * post_norm * (1.0 - progress) + post_norm * progress * 2.0;
    score += coupling * cap * 0.35;

    // Reward near-full bins smoothly (small post_residual quadratic discount)
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 6.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 + 3.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // penalize leaving residuals that waste the next item's potential
        score += 1.5 * ((next_item_size as f64 - post) / cap);
    }

    // Mild penalty when this bin's residual deviates from mean residual (balance pressure)
    score += 0.02 * (post - mean_residual).abs();

    // New-bin candidate handling: only attractive late or when few bins fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score = 8.0 + 12.0 * (1.0 - progress) * (1.0 - scarcity) - 6.0 * scarcity * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Harmonic dead-space classes on post_residual (mod-10 buckets) ---
    let dead_class = (pr / 10) as f64;
    score += 0.8 * dead_class; // larger coarse residual classes are mildly worse

    // Unusable sliver: residual too small for the minimum item size (1..10)
    if pr > 0 && pr < 10 {
        score += 40.0; // hard penalty: total dead space
    }

    // Exact fit reward (residual annihilated)
    if pr == 0 {
        score -= 35.0;
    }

    // --- Lookahead coupling (k=2): does the next item fit the leftover? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic bonus scaled by how snugly the next item nests
            score -= 12.0 + 8.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // leftover can't host next item: penalize proportionally to waste
            score += 6.0 + 0.15 * (pr as f64);
        }
    }

    // --- Last-chance bin: avoid opening a bin when only this one fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Spread pressure: prefer bins whose residual deviates from mean ---
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // --- Stream-phase modulation: late in stream, consolidate harder ---
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * t * (1.0 - (pr as f64 / bin_capacity as f64));

    // --- New-bin candidate baseline ---
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 8.0;
        // open a new bin if the item is large and next item likely needs fresh space
        if next_item_size > 0 && item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 3.0;
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 15.0;
    }
    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 1.5;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(6.0);
    } else {
        // New-bin candidate: penalize unless current bin fits are poor.
        score += 8.0 + mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins tighter than the mean residual.
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: exact fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (chain packing), mildly reward bins where
    // the next item still fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
            // Prefer tight chain fits: smaller slack after the pair is better.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot follow here: penalize leftover dead space
            // that is too small to be useful, scaled by how "wasted" it is.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residuals far below the mean residual (creating unusable slivers)
    // but reward bins that are close to being closed out.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score += (mean_residual - residual_f) * 0.2;
    } else {
        score -= (residual_f - mean_residual) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral baseline; only win if open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0 + residual_f * 0.1;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Slight preference for bins with less residual overall (best-fit core).
    score += residual_f * 0.05;

    // Mild pressure to close bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residuals nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize residuals that are too small to ever fit a future item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open relative to stream progress,
    // prefer consolidating into existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 15.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        // Allow a new bin early on or when existing bins are nearly full on average.
        score -= 50.0 * (mean_residual / bin_capacity as f64).powi(3);
    } else {
        // Reward placing into bins with residual close to the mean (balance spread).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight fits via non-linear decay of post_residual
    let mut score = pr * pr / cap; // quadratic waste penalty
    score += pr * (1.0 - progress); // early stream: waste matters more (long future)

    // Smooth coupling: fill ratio of the bin
    let fill = (cap - pr) / cap;
    score -= fill * fill * it * 0.5; // reward high fill, scaled by item size

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize unless the item fits poorly everywhere.
    // Empty-bin call has post_residual = cap - item_size; make it competitive
    // only when placement would leave large unusable residual.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress; // cheaper to open bins early
        // penalize new bin when item is small relative to capacity (easy fit elsewhere)
        score += (cap - it) * 0.05;
    }

    // Lookahead: if next item could use this post_residual, reward leaving it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 + 4.0 * (1.0 - pr / cap);
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidate)
    score += 0.3 * (mean_residual - (bin_residual as f64)).abs().sqrt();

    // Many open bins: encourage closing them out (tight placements)
    score -= (open_bins_count as f64).ln() * (cap - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact fill (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Small post_residuals are near-dead space; penalize the awkward band (1..=9).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }

    // Reward post_residuals that are clean harmonic divisions of capacity:
    // exact halves and quarters are easy to fill with typical items.
    if post_residual == half {
        score -= 40.0;
    }
    if post_residual == quarter {
        score -= 20.0;
    }
    if post_residual == 3 * quarter {
        score -= 25.0;
    }

    // Modulo arithmetic: post_residual divisible by common small item sizes
    // (10, 20, 25) is likely reusable; reward divisibility.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily; if next item cannot fit, this residual is dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > post_residual {
            score += 25.0;
        } else {
            // Next item fits: reward proportional tightness of the pair fit.
            let leftover2 = post_residual - next_item_size;
            score -= (cap - leftover2 as f64) * 0.05;
            if leftover2 <= 5 {
                score -= 30.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize unless current placements are bad.
    if bin_residual == bin_capacity {
        score = cap + 80.0;
        // If mean residual across open bins is already small (fragmented),
        // opening fresh is less painful.
        score -= mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Early in stream, prefer opening bins slightly less (keep bins tight later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild penalty proportional to how far below mean residual this bin sits
    // (prefer balanced usage slightly).
    score += (mean_residual - pr) * 0.05;

    // Nonlinear tightness reward: tighter fits get exponentially better.
    score -= (1.0 - pr / cap).powi(6) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small to be useful
    // are heavily penalized (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 / (1.0 + tightness);

    // Open bins pressure: prefer filling existing bins when many are open,
    // making new bins less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well, new bin becomes more attractive.
        if post_residual >= bin_capacity - item_size {
            score -= 35.0;
        }
    }

    // Lookahead: if next item could use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
