    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Opening a new bin: base penalty, reduced when few bins fit or item is large.
        let mut penalty = 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            penalty = -5.0; // no open bin fits: new bin is necessary
        } else if item_size > 60 && post_residual < 20 {
            penalty -= 15.0; // large item nearly filling a fresh bin is fine
        }
        score += penalty;
        // Too many open bins: discourage further proliferation.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Reward reusing existing bins mildly, more so late in the stream.
        score -= 3.0 + 4.0 * progress;
    }

    // Nonlinear coupling: strongly reward near-exact fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Smooth interaction: residual curvature grows with progress
    let curve = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += 40.0 * curve;

    // Reward near-perfect fits with a smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (1.0 + progress);

    // Penalize residuals that match the next item poorly (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 20.0 * gap * gap * (0.5 + progress);
        // Reward residuals that leave room for the lookahead item
        score -= 15.0 * (1.0 - gap) * (1.0 - gap) * (pr / (pr + nxt));
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress);

    // Coupling with mean residual: prefer bins deviating below mean residual
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals are scarce
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress - 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Classify leftover space into residue classes modulo 10 (common item granularity).
    let pr = post_residual as i64;
    let residue_class = (pr % 10) as i64;

    // Perfect fit: strongest reward.
    if pr == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty grows super-linearly for unusable slivers (< 10).
    if pr < 10 {
        score += 60.0 + (10 - pr) as f64 * 8.0;
    }

    // Harmonic bonus: leftover divisible by 10 is "reusable" by typical item sizes.
    if residue_class == 0 {
        score -= 15.0;
    } else {
        score += residue_class as f64 * 2.5; // penalize awkward remainders
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // leftover after next hypothetical placement
            let pr2 = post_residual - next_item_size;
            score -= 30.0 - (pr2 as f64) * 0.5;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer-division threshold: leftover >= half capacity is flexible.
    if post_residual * 2 >= bin_capacity {
        score -= 20.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: baseline penalty so we only open when leftovers are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.8 + open_bins_count as f64 * 2.0;
        // But if current item is huge relative to mean residual, opening is attractive.
        if (item_size as f64) > mean_residual * 1.5 {
            score -= 60.0;
        }
        // Late in stream, prefer closing out open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 25.0;
        }
    }

    // Mild global pressure to fill existing bins tightly.
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize "dead" residual: small gaps unlikely to be filled later
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual < 20 {
        score += 60.0;
    }

    // Reward residual that can still host a plausible future item
    if post_residual >= 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 180.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream
        score += 80.0 + 30.0 * (open_bins_count as f64).ln().max(0.0) + 50.0 * progress;
        // But if no open bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins slightly more as open_bins_count grows
        score -= 2.0 * (open_bins_count as f64);
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits: squashed residual penalty.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powf(6.0);

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let match_strength = (-gap / 12.0).exp(); // 1.0 when perfect chain fit
        score -= 55.0 * match_strength;

        // Slight penalty if post_residual is positive but too small for next item
        // (creates dead space the lookahead cannot use).
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 6.0 + 0.25 * post_residual as f64;
        }
    } else {
        // Last item: fill as tightly as possible.
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // Relative-to-mean coupling: prefer bins with residuals below the mean
    // (consolidate fullness) early; relax late in the stream.
    let mean_dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += mean_dev * (18.0 - 10.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64
        } else {
            0.0
        };
        // Penalize opening a new bin; escalate with number of open bins and progress.
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow opening when the lookahead chain from a fresh bin would be poor anyway.
        score += 0.15 * best_possible;
        // Encourage new bin when existing bins are all nearly full on average.
        score -= (mean_residual / bin_capacity as f64).powf(2.0) * 15.0;
    }

    score
}
